var LB_DT=[{"t":"Đề thi 2022-23 (bản sinh viên tổng hợp, có đáp án)","s":"Các câu nhận định đúng/sai và tình huống theo mã đề lớp: Thương mại 43, Dân sự 42A, CLC 41A, CLC 42D, Thương mại 41, CLC 39B.","g":[{"h":"THƯƠNG MẠI 43","items":[{"q":"Nội thủy và lãnh hải là hai vùng biển thuộc chủ quyền của quốc gia ven biển.","a":["Nhận định đúng.","Vùng biển thuộc chủ quyền quốc gia và lãnh thổ quốc gia trên biển gồm nội thủy, vùng nước quần đảo và lãnh hải. Do đó nội thủy và lãnh hải là hai vùng biển thuộc chủ quyền của quốc gia ven biển.","CSPL: Điều 2 UNCLOS 1982."]},{"q":"Quyền tự do hàng hải và quyền tự do hàng không chỉ được thực hiện ở vùng biển quốc tế.","a":["Nhận định sai.","Vì quyền tự do hàng hải và quyền tự do hàng không không chỉ được thực hiện ở vùng biển quốc tế mà tại khoản 1 Điều 58 UNCLOS 1982 còn ghi nhận cho các quốc gia có biển hay không có biển được hưởng các quyền tự do hàng hải, tự do hàng không trong vùng đặc quyền kinh tế.","CSPL: khoản 1 Điều 58 UNCLOS năm 1982."]},{"q":"Mỗi đảo thuộc chủ quyền của quốc gia ven biển sẽ có các vùng biển tiếp liền như đối với đất liền của quốc gia ven biển đó.","a":["Nhận định sai.","Mặc dù đảo nhân tạo có thể được xây dựng ở các vùng biển thuộc chủ quyền quốc gia (như nội thủy, lãnh hải) tuy nhiên đảo nhân tạo không có một mét biển nào cả vì đảo nhân tạo không có quy chế pháp lý của đảo quy định tại Điều 121 UNCLOS 1982. Đảo nhân tạo không có lãnh hải, tiếp giáp lãnh hải, đặc quyền kinh tế và thềm lục địa.","CSPL: Khoản 8 Điều 60, Điều 121 UNCLOS 1982."]},{"q":"Biện pháp xử lý của quốc gia ven biển đối với các tàu nước ngoài vi phạm khi hoạt động trong các vùng biển của quốc gia ven biển là giống nhau.","a":["Nhận định sai.","ở vùng lãnh hải, tàu quân sự được hưởng quyền miễn trừ còn tàu dân sự thì không.","Điều 27, Điều 28, Điều 32 UNCLOS."]},{"q":"Theo UNCLOS 1982, Trọng tài quốc tế về Luật Biển theo Phụ lục VII có thẩm quyền ưu tiên trong thụ lý, giải quyết các vụ tranh chấp.","a":["Nhận định sai.","Ưu tiên sự lựa chọn.","CSPL: Điều 287 UNCLOS 1982."]}]},{"h":"Dân sự 42A","items":[{"q":"Thềm lục địa của mọi quốc gia ven biển rộng tối đa là 350 hải lý","a":["Nhận định sai.","Nếu thềm lục địa của một quốc gia từ đường cơ sở đến rìa lục địa nhỏ hơn hoặc bằng 200 hải lý thì các quốc gia có quyền tuyên bố chiều rộng tối đa của thềm lục địa của mình là 200 hải lý.","Ví dụ, quốc gia A có thềm lục địa từ đường cơ sở đến rìa lục địa rộng 180 hải lý thì quốc gia A chỉ có quyền tuyên bố chiều rộng tối đa của thềm lục địa của mình bằng 200 hải lý mà không phải là 350 hải lý.","Nếu thềm lục địa của một quốc gia từ đường cơ sở đến rìa lục địa lớn hơn 200 hải lý thì thềm lục địa của quốc gia đó rộng bao nhiêu sẽ được tuyên bố bấy nhiêu nhưng tối đa không được vượt quá 350 hải lý tính từ đường cơ sở hoặc không được vượt quá 100 hải lý tính từ đường đẳng sâu 2500m. Ví dụ thềm lục địa của quốc gia B tính từ đường cơ sở đến rìa lục địa bằng 250 hải lý thì quốc gia B chỉ được tuyên bố chiều rộng của thềm lục địa của mình là 250 hải lý mà không phải là 350 hải lý.","Như vậy, không phải thềm lục địa của mọi quốc gia ven biển rộng tối đa 350 hải lý mà chỉ có quốc gia nào có thềm lục địa từ đường cơ sở đến rìa lục địa bằng 350 hải lý hoặc lớn hơn 350 hải lý thì mới được quyền tuyên bố chiều rộng tối đa thềm lục địa của mình là 350 hải lý.","CSPL: Điều 76 UNCLOS."]},{"q":"Phân định biển được đặt ra đối với mọi quốc gia có biển","a":["Sai. Chỉ áp dụng cho các quốc gia có biển kề nhau hoặc đối diện nhau.","CSPL: Điều 15,74,83 UNCLOS."]},{"q":"Tự do hàng hải chính là đi qua không gây hại (Trang 219)","a":["Tự do hàng hải chỉ có trong DQKT (điều 58), eo biển hàng hải quốc tế (Điều 45) Đi qua không gây hại chỉ có trong lãnh hải (Điều 18), vùng nước quần đảo (khoản 1","Điều 52)"]},{"q":"Phần nước phía trên thềm lục địa của quốc gia ven biển có chế độ pháp lý của vùng đặc quyền kinh tế.","a":["Nhận định sai.","Nếu thềm lục địa của một quốc gia từ đường cơ sở đến rìa lục địa nhỏ hơn hoặc bằng 200 hải lý thì các quốc gia có quyền tuyên bố chiều rộng tối đa của thềm lục địa của mình là 200 hải lý.","Trong trường hợp này phần nước phía trên thềm lục địa của quốc gia ven biển có chế độ pháp lý của vùng đặc quyền kinh tế.","Tuy nhiên, nếu thềm lục địa của một quốc gia từ đường cơ sở đến rìa lục địa lớn hơn 200 hải lý thì thềm lục địa của quốc gia đó rộng bao nhiêu sẽ được tuyên bố bấy nhiêu nhưng tối đa không được vượt quá 350 hải lý tính từ đường cơ sở hoặc không được vượt quá 100 hải lý tính từ đường đẳng sâu 2500m. Trong trường hợp này phần nước phía trên thềm lục địa của quốc gia ven biển bao gồm cả vùng đặc quyền kinh tế và một phần biển quốc tế. Do đó phần nước phía trên thềm lục địa lớn hơn 200 hải lý có chế độ pháp lý của vùng biển quốc tế.","CSPL: Điều 76, Điều 78 UNCLOS 1982."]},{"q":"Quy chế pháp lý của lãnh hải trong UNCLOS và LBVN là giống nhau","a":["Nhận định sai.","Theo quy định của LBVN chiều rộng lãnh hải được xác định là bằng 12 hải lý tính từ đường cơ sở, còn theo UNCLOS thì chiều rộng lãnh hải tối đa là 12 hải lý nghĩa là có thể là 7 hải lý hoặc 10 hải lý miễn sao không được vượt quá 12 hải lý.","Quyền thông báo.... trong UNCLOS không có quy định","CSPL: khoản 2 Điều 12 LBVN, Điều 17,18,19 UNCLOS"]},{"q":"Các thủ tục giải quyết tranh chấp tại Điều 287 được ưu tiên áp dụng mặc nhiên","a":["Nhận định sai.","Các thủ tục giải quyết tranh chấp tại Điều 287 sẽ không được ưu tiên áp dụng mặc nhiên mà chỉ được áp dụng khi đáp ứng đủ các điều kiện sau đây:","- Có tranh chấp liên quan đến giải thích hay áp dụng UNCLOS (liên quan đến các qui định của UNCLOS về các vùng biển).","- Các bên tranh chấp đã giải quyết bằng biện pháp hòa bình theo quy định tại Điều 279 UNCLOS 1982, đã trao đổi quan điểm về giải quyết tranh chấp bằng thương lượng hay các biện pháp hòa bình khác theo Điều 283 UNCLOS 1982 nhưng tranh chấp vẫn không giải quyết được.","- Các bên tranh chấp không bị ràng buộc bởi một biện pháp, cơ chế giải quyết tranh chấp nào trong một Điều ước quốc tế song phương hoặc đa phương thay thế cho cơ chế giải quyết tranh chấp của UNCLOS (Điều 282 UNCLOS 1982).","- Nội dung khởi kiện không bị giới hạn hoặc loại trừ theo Điều 297 và Điều 298 UNCLOS 1982.","CSPL: Điều 286 UNCLOS năm 1982."]},{"q":"Cho đến thời điểm hiện tại Việt Nam mặc nhiên chọn Trọng tài theo phụ lục VII để giải quyết tranh chấp về giải thích và áp dụng UNCLOS.","a":["Nhận định sai.","Vì Việt Nam chưa tuyên bố lựa chọn cơ quan tài phán nào của Điều 287 UNCLOS để giải quyết tranh chấp, vì VN chủ trương giải quyết tranh chấp theo con đường hòa bình. Vì vậy, nếu có tranh chấp xảy ra thì được xem là đã chấp nhận thủ tục trọng tài đã trù định theo phụ lục VII.","CSPL: Điều 287 khoản 3 UNCLOS 1982."]},{"q":"Đặc quyền kinh tế là vùng biển quan trọng nhất của quốc gia ven biển","a":["Nhận định sai. Trang 74 Mặc dù đặc quyền kinh tế là một vùng biển thuộc quyền chủ quyền, quyền tài phán của quốc gia ven biển, tuy nhiên nó không phải là vùng biển quan trọng nhất mà vùng biển quan trọng nhất của quốc gia ven biển là nội thủy.","Xét về phương diện pháp lý thì trong vùng nội thủy, quốc gia ven biển có chủ quyền hoàn toàn và tuyệt đối. Vì thế trong vùng nội thủy quốc gia ven biển sẽ thực hiện đầy đủ quyền lập pháp, hành pháp, tư pháp giống như trên đất liền mà không có bất kỳ ngoại lệ nào.","Xét thực tiễn khai thác, quản lý, sử dụng biển thì trong vùng nước nội thủy có nhiều cảng biển dùng vào mục đích quân sự, dân sự, thương mại của quốc gia ven biển. Do đó ở nội thủy, tàu buôn, tàu thương mại của các quốc gia thường xuyên ra vào, neo đậu và hoạt động nhằm mục đích thương mại.","Do đó, xét về phương diện pháp lý và thực tiễn khai thác, quản lý, sử dụng biển thì nội thủy chính là vùng biển “nhộn nhịp nhất”, có vai trò quan trọng nhất trong các vùng biển thuộc chủ quyền, quyền chủ quyền và quyền tài phán của quốc gia ven biển.","CSPL: Điều 8 UNCLOS 1982; Điều 2, Điều 10 Luật Biển Việt Nam năm 2012."]},{"q":"Địa hình bờ biển là yếu tố quyết định phương pháp xác định đường cơ sở của quốc gia ven biển.","a":["Nhận định đúng.","Địa hình bờ biển là yếu tố quyết định cho phép quốc gia ven biển chọn lựa một phương pháp xác định đường cơ sở mà phương pháp nào là UNCLOS quyết định. Tùy theo đặc điểm địa hình bờ biển mà quốc gia ven biển có thể xác định đường cơ sở theo phương pháp đường cơ sở thông thường hoặc phương pháp đường cơ sở thẳng, hoặc kết hợp cả hai phương pháp này để xác định đường cơ sở.","CSPL: Điều 5, Điều 7, Điều 14 UNCLOS 1982."]},{"q":"Chế độ pháp lý của TGLH giống như chế độ pháp lý của đặc quyền KT","a":["sai."]}]},{"h":"CLC 41A","items":[{"q":"Trong mọi trường hợp hoạch định và phân định biển đều dựa vào sự thỏa thuận giữa các quốc gia.","a":["- Tuyên bố 12/5/1977 của Chính phủ về các vùng biển của CHXHCNVN.","- Tuyên bố 12/11/1982 của Chính phủ về Đường cơ sở.","- Tuyên bố 06/5/1984 của Chính phủ về vùng trời của CHXHCNVN.","Sai. Hoạch định là hành vi đơn phương của quốc gia ven biển.","Phân định biển là hành vi đa phương dựa trên sự thỏa thuận của các quốc gia đối diện hoặc kề nhau Điều 74,83 UNCLOS"]},{"q":"Mọi quốc gia đều có vùng đặc quyền kinh tế riêng.","a":["Sai.","Quốc gia không có biển là quốc gia không tiếp giáp với biển, không có đảo và quần đảo (UNCLOS không quy định như thế nào là quốc gia không có biển). Ví dụ quốc gia không có biển:","Lào.","Quốc gia không có vùng đặc quyền kinh tế riêng là những quốc gia đối diện nhau vì khoảng cách giữa bờ biển những nước này rất nhỏ chỉ đủ để phân định lãnh hải nên không có vùng đặc quyền kinh tế riêng; quốc gia ven biển không có vùng đặc quyền kinh tế riêng là quốc gia bất lợi về địa lý.","CSPL: Điều 69, khoản 2 Điều 70 UNCLOS."]},{"q":"Đường biên giới quốc gia trên biển là đường phân định lãnh hải của các quốc gia đối diện hoặc tiếp giáp nhau. Trang 238","a":["Nhận định sai.","Vì việc phân định nội thủy và lãnh hải là để xác định biên giới quốc gia trên biển của các quốc gia đối diện hoặc tiếp giáp nhau. Do đó đường biên giới quốc gia trên biển không chỉ là đường phân định lãnh hải mà còn là đường phân định nội thủy của các quốc gia đối diện hoặc tiếp giáp nhau."]},{"q":"Việc quản lý, khai thác, bảo vệ vùng nước lãnh hải và vũng nước biên giới là giống nhau.","a":["Sai.","Vùng nước biên giới: bao gồm sông suối, đầm ao, kênh rạch... nằm trong khu vực biên giới giữa các quốc gia. Việc quản lý, khai thác, sử dụng thì các bên phải có sự thỏa thuận. Thuộc chủ quyền hoàn toàn, đầy đủ nhưng ko tuyệt đối như vùng nước nội địa.","Vùng nước lãnh hải: là vùng nước tiếp theo, nằm phía ngoài nội thủy, có chiều rộng tối đa 12 hải lý. Tính chất chủ quyền hoàn toàn, đầy đủ. Tàu thuyền đc đi lại ko cần xin phép nhưng không được xâm phạm (đi qua ko gây hại). Ranh giới phía ngoài của lãnh hải là BGQG trên biển. Việc khai thác, quản lý, sử dụng chỉ thuộc quốc gia ven biển."]},{"q":"Quyền “đi qua không gây hại” là một quyền mang tính biển và được áp dụng trên tất cả các vùng biển theo quy định của UNCLOS.","a":["Sai, vì quyền đi qua không gây hại là một quyền mang tính biển nhưng chỉ được áp dụng ở lãnh hải, vùng nước quần đảo.","Cspl: Điều 17, 52, 53 UNCLOS."]},{"q":"Việt Nam có biên giới biển với Trung Quốc, Campuchia, Indonesia, Thái Lan, Malaysia và Philipines.","a":["Nhận định sai.","Vì phân định nội thủy và lãnh hải chính là xác định biên giới trên biển của quốc gia, còn phân định đặc quyền kinh tế và thềm lục địa chính là phân định các vùng biển thuộc quyền chủ quyền và quyền tài phán của quốc gia ven biển không phải xác định biên giới trên biển của quốc gia.","Như vậy, Việt Nam chỉ có biên giới trên biển với TQ và Campuchia.","VN có biển kề nhau ở phía Bắc vs TQ: Vịnh Bắc bộ, phía Tây- Nam: camphuchia: Vịnh Thái Lan.","CSPL:","- Điều 3 Hiệp ước hoạch định biên giới quốc gia giữa nước CHXHCNVN và nước CHNN CAMPUCHIA. (trang 199).","- Điều 1 Hiệp định giữa CHXHCNVN và nước CHNDNNTH về phân định lãnh hải, vùng ĐQKT và TLĐ của hai nước trong Vịnh Bắc bộ (trang 157)."]},{"q":"Khi xác định đường cơ sở thẳng, quốc gia ven biển có quyền kéo đến hoặc xuất phát từ các bãi cạn lúc nổi lúc chìm.","a":["Nhận định sai.","CSPL: Đoạn 4 Điều 7, Điều 13 UNCLOS 1982"]}]},{"h":"CLC 42D","items":[{"q":"Có một tàu chở hàng mang cờ Ấn Độ trong hành trình đi qua lãnh hải Việt Nam đã dừng lại và thực hiện việc bốc, dỡ hàng hóa từ tàu này sang tàu khác. Anh chị hãy cho biết hành vi của chiếc tàu này có phù hợp với Luật biển quốc tế và Luật biển Việt Nam không? Tại sao?","a":["SAI. Điểm g Khoản 2 Điều 19 UNCLOS; Điểm h Khoản 3, Khoản 2 Điều 23 LBVN."]},{"q":"Có một chiếc tàu chở khách mang cờ Panama trong hành trình đi qua lãnh hải Việt Nam mà không vào nội thủy Việt Nam đã xảy ra một vụ đâm chém gây chết người. Anh chị hãy cho biết: Vụ việc náy sẽ thuộc thẩm quyền xử lý của quốc gia nào? Tại sao?","a":["Th1: Thẩm quyền xử lý thuộc về Panama. KHÔNG thuộc các Khoản 1 Điều 27 UNCLOS=> VN không có thẩm quyền.","Th2: Thẩm quyền xử lý thuộc về VN nếu nó thuộc k1 Điều 27 UNCLOS, Điều 30 LBVN"]},{"q":"Có một tàu quân sự mang cờ Trung Quốc phóng đi và tiếp nhận các phương tiện bay lên tàu trong hành trình đi qua lãnh hải của Việt Nam. Anh chị hãy cho biết: Các lực lượng chức năng của Việt Nam có thẩm quyền xử lý hành vi của chiếc tàu này không? Tại sao?","a":["VN không có thẩm quyền xử lý tàu quân sự tuy nhiên VN có quyền yêu cầu tàu đó rời khỏi lãnh hải ngay lập tức. Điều 30, Điều 32 UNCLOS, Điều 28 LBVN."]},{"q":"Có một tàu cá của ngư dân Indonesia không thu cất lưới và ngư cụ vào trong khoang khi đi qua vùng đặc quyền kinh tế của Việt Nam. Anh chị hãy cho biết: Các lực lượng chức năng của Việt Nam có thẩm quyền xử lý hành vi của chiếc tàu này không? Tại sao.","a":["VN có thẩm quyền xử lý. Khoản 9 Điều 37 LBVN, Điều 10 NĐ162/2013/NĐ-CP ( trang 356)"]},{"q":"Có một tàu nước ngoài chỉ treo cờ quốc tịch của tàu nhưng không treo cờ Việt Nam khi đi qua vùng đặc quyền kinh tế của Việt Nam. Anh chị hãy cho biết: Lực lượng chức năng của Việt Nam có thẩm quyền xử lý về hành vi này không? Tại sao?","a":["VN có thẩm quyền xử lý. Điểm a Khoản 2 Điều 7 NĐ số 162/2013/NĐ-CP"]}]},{"h":"THƯƠNG MẠI 41","items":[{"q":"Xác định đường cơ sở theo phương pháp nào là tùy thuộc vào sự lựa chọn của quốc gia ven biển.","a":["Nhận định sai.","Vì xác định đường cơ sở theo phương pháp nào không tùy thuộc vào sự lựa chọn của quốc gia ven biển mà địa hình bờ biển mới là yếu tố quyết định cho phép quốc gia ven biển chọn lựa một phương pháp xác định đường cơ sở mà phương pháp nào là do UNCLOS quyết định. Tùy theo đặc điểm địa hình bờ biển mà quốc gia ven biển có thể xác định đường cơ sở theo phương pháp đường cơ sở thông thường hoặc phương pháp đường cơ sở thẳng, hoặc kết hợp cả hai phương pháp này để xác định đường cơ sở.","CSPL: Điều 5, Điều 7, Điều 14 UNCLOS 1982."]},{"q":"Trong vùng lãnh hải của mình, quốc gia ven biển không được thực hiện bất kỳ hoạt động nào làm ảnh hưởng đến “Quyền đi qua không gây hại” của tàu thuyền nước ngoài.","a":["Sai. Khoản 1 Điều 27 UNCLOS","Điều 28."]},{"q":"Tuyên bố chiều rộng của vùng biển là hành vi pháp lý quan trọng nhất để xác lập thực thi quyền chủ quyền quốc gia trên biển.","a":["Nhận định sai.","Tuyên bố chiều rộng của vùng biển không là hành vi pháp lý quan trọng nhất để xác lập thực thi quyền chủ quyền quốc gia trên biển mà xác định đường cơ sở mới là hành vi pháp lý quan trọng nhất.","Vì nếu không có đường cơ sở thì các quốc gia không thể xác định chiều rộng của vùng biển dẫn đến việc không thể xác định được biên giới quốc gia trên biển đến đâu cũng như không thể xác định quyền chủ quyền và quyền tài phán đến đâu nếu không xác định được đường cơ sở."]},{"q":"Mọi đảo, đá đều có vùng đặc quyền kinh tế và thềm lục địa riêng.","a":["Nhận định sai.","Đảo nhân tạo không có một mét biển nào, đảo nhân tạo không có quy chế pháp lý của đảo quy định tại Điều 121 UNCLOS. Đảo nhân tạo không có lãnh hải, tiếp giáp lãnh hải, đặc quyền KT và thềm lục địa.","Đối với đảo tự nhiên không thích hợp cho con người đến ở hoặc không có đời sống kinh tế riêng thì không có đặc quyền kinh tế và thềm lục địa mà chỉ có lãnh hải rộng 12 hải lý.","CSPL: Khoản 8 Điều 60 và Khoản 3 Điều 121 UNCLOS 1982."]},{"q":"Khi có tranh chấp phát sinh liên quan đến giải thích và áp dụng UNCLOS 1982, các quốc gia được quyền sử dụng ngay các biện pháp tài phán để giải quyết.","a":["Nhận định sai.","Vì khi có tranh chấp phát sinh liên quan đến giải thích và áp dụng UNCLOS năm 1982, các quốc gia không được quyền sử dụng ngay các biện pháp tài phán để giải quyết mà chỉ được áp dụng các biện pháp tài phán để giải quyết khi đáp ứng đủ các điều kiện sau đây:","- Các bên tranh chấp đã giải quyết bằng biện pháp hòa bình theo quy định tại Điều 279 UNCLOS 1982, đã trao đổi quan điểm về giải quyết tranh chấp bằng thương lượng hay các biện pháp hòa bình khác theo Điều 283 UNCLOS 1982 nhưng tranh chấp vẫn không giải quyết được.","- Các bên tranh chấp không bị ràng buộc bởi một biện pháp, cơ chế giải quyết tranh chấp nào trong một Điều ước quốc tế song phương hoặc đa phương thay thế cho cơ chế giải quyết tranh chấp của UNCLOS (Điều 282 UNCLOS 1982).","- Nội dung khởi kiện không bị giới hạn hoặc loại trừ theo Điều 297 và Điều 298 UNCLOS 1982.","CSPL: Điều 286 UNCLOS năm 1982."]},{"q":"Quy chế pháp lý của các tàu thuộc sở hữu của nhà nước là giống nhau.","a":["Sai. Tiểu mục B, tiểu mục C UNCLOS"]},{"q":"Chiều rộng của thềm lục địa địa chất và thềm lục địa pháp lý là như nhau.","a":["Sai. Điều 76 Khoản 1 UNCLOS.","TLĐ địa chất: từ bờ -> vết rạn, TLĐ pháp lý: đường cơ sở -> rạn (sự chênh lệch là khoảng cách từ bờ đến đường cơ sở) TLĐ thực tế là từ ranh giới ngoài lãnh hải đến vết rạn."]}]},{"h":"CLC 39B","items":[{"q":"Việc giải quyết tranh chấp biển phải có sự thỏa thuận của các quốc gia hữu quan.","a":["Sai. Trường hợp áp dụng biện pháp tư pháp là không còn sự thỏa thuận. Điều 286 UNCLOS."]},{"q":"Chế độ pháp lý đối với tàu thuyền và phương tiện bay nước ngoài tại vùng nước và vùng trời của eo biển quốc tế là giống nhau.","a":["Trang 219 ./.","CSPL: Điều 39 UNCLOS 1982"]},{"q":"Chế độ pháp lý đối với tài nguyên sinh vật và tài nguyên không sinh vật của vùng đặc quyền kinh tế là giống nhau.","a":["Giống nhau: Chỉ thăm dò, khai thác ở vùng đặc quyền kinh tế vì mục đích kinh tế.","Nhận định sai.","Vì chế độ pháp lý đối với tài nguyên sinh vật có sự hạn chế, cụ thể UNCLOS 1982 nêu rõ, quyền thuộc chủ quyền của QGVB về tài nguyên sinh vật được cụ thể hóa bằng quyền thăm dò, khai thác, bảo tồn và quản lý tài nguyên sinh vật của vùng nước bên trên đáy biển, của đáy biển và lòng đất dưới đáy biển trong vùng DQKT; quyền ấn định khối lượng đánh bắt có thể chấp nhận đối với tài nguyên sinh vật; quyền thi hành các biện pháp thích hợp để bảo tồn và quản lý tài nguyên sinh vật; xác định khả năng đánh bắt của mình để ấn định số dư của khối lượng cho phép đánh bắt; cho phép các quốc gia không có biển và bất lợi về địa lý khai thác cá dư trong vùng DQKT của mình;","quy định các biện pháp nhằm bảo tồn nguồn lợi thủy sản. Còn đối với các loại tài nguyên không sinh vật, UNCLOS 1982 không có quy định bất kỳ hạn chế nào đối với quốc gia ven biển.","CSPL: điểm a khoản 1 Điều 56; khoản 1, 2 Điều 61; khoản 2,3,4 Điều 62 UNCLOS 1982."]},{"q":"Thềm lục địa chính là phần kéo dài tự nhiên của đất liền ra tới bờ ngoài của rìa lục địa.","a":["Nhận định sai Thềm lục địa tự nhiên (thềm lục địa địa chất) là phần kéo dài từ bờ đến vết rạn Thềm lục địa pháp lý là phần kéo dài từ đường cơ sở đến vết rạn Thềm lục địa thực tế là phần kéo dài từ ranh giới ngoài lãnh hải đến vết rạn.","CSPL: Điều 76 UNCLOS 1982"]},{"q":"Vùng là đáy biển và lòng đất dưới đáy biển phía ngoài vùng đặc quyền kinh tế.","a":["Nhận định sai.","Vùng là đáy biển và lòng đất dưới đáy biển nằm bên ngoài giới hạn quyền tài phán quốc gia.","Không gian biển thuộc quyền chủ quyền và quyền tài phán quốc gia bao gồm vùng tiếp giáp lãnh hải, vùng đặc quyền KT và thềm lục địa.","Như vậy vùng là toàn bộ đáy biển và lòng đất dưới đáy biển nằm phía ngoài thềm lục địa của tất cả các quốc gia.","CSPL: Khoản 1 Điều 1 UNCLOS 1982."]},{"q":"Tiếp giáp lãnh hải là một bộ phận của vùng đặc quyền đặc kinh tế","a":["- Nhận định đúng.","- Chiều rộng của ĐQKT bao gồm luôn TGLH.","- Chế độ pháp lý của vùng TGLH trong lĩnh vực hải quan, thuế quan, y tế, an ninh, nhập cư (theo pháp luật VN là xuất nhập cảnh) cũng được áp dụng như chế độ pháp lý của vùng ĐQKT.","Điều 14 của LBVN, chế độ pháp lý của TGLH áp dụng theo Điều 16 của LBVN mà Điều 16 của LBVN quy định chế độ pháp lý của DQKT do đó chế độ pháp lý của DQKT áp dụng cho TGLH mà không có sự phân biệt nào.","CSPL: Điều 33, 55 UNCLOS 1982, Điều 14,16 LBVN năm 2012."]},{"q":"Điều 102 Công ước UNCLOS 1982: Nó không còn quy chế pháp lý của tàu quân sự nữa mà là tàu hay phương tiện bay tư nhân.","a":["Vì: tàu quân sự trên tàu có trang bị vũ khí hơn nữa nếu vẫn là tàu quân sự sẽ được hưởng quyền miễn trừ đe dọa hòa bình, an ninh, chủ quyền vì thế để kiểm soát tàu quân sự bị nổi loạn Công ước quy định nó là tàu dân sự để các quốc gia có thể xử lý cái tàu đó.","Tàu không quốc tịch là tàu không treo cờ (bất kỳ quốc gia nào cũng có thể xử lý – Điều 90 UNCLOS)."]},{"q":"Điều 111: Quyền truy đuổi: Việc truy đuổi phải liên tục không được gián đoạn.","a":["Vùng biển quốc tế, ĐQKT, TGLH vẫn được truy đuổi nhưng vào lãnh hải (vào lãnh thổ) không truy đuổi được (Điều 111 khoản 3 UNCLOS 1982)."]},{"q":"*ĐQKT trong UNCLOS và LBVN giống nhau ở ranh giới trong là đều tính từ đường cơ sở; khác nhau là ranh giới ngoài, cụ thể trong UNCLOS thì không quá 200 hải lý, còn trong LBVN quy định vùng ĐQKT có chiều rộng bằng 200 hải lý.","a":["(?) UNCLOS và LBVN quy định ĐQKT nằm ở phía ngoài tiếp giáp là sai vì trong UNCLOS tại Điều 55 không dùng cụm từ “nằm bên ngoài tiếp giáp” mà dùng cụm từ “nằm ngoài lãnh hải”"]},{"q":"Bãi cạn lúc chìm lúc nổi có vai trò như là đảo tự nhiên ven bờ để xác định điểm cơ sở.","a":["Nhận định sai.","Vì đảo ven bờ là đương nhiên là một điểm xác định đường cơ sở còn bãi cạn không là đương nhiên là một điểm xác định đường cơ sở mà phải thỏa mãn 02 điều kiện:","Một là, Bãi cạn cách bờ biển hoặc đảo ven bờ không quá 12 hải lý;","Hai là, Trên các bãi cạn có công trình xây dựng thường xuyên nhô trên mặt nước.","=> Đường cơ sở được xác định theo ngấn nước ngoài cùng của bãi cạn lúc chìm lúc nổi.","CSPL: Đoạn 4 Điều 7, Điều 13 UNCLOS 1982."]},{"q":"Ghi chú đi kèm đề (sinh viên ghi)","a":["*Lưu ý:","*Chế độ pháp lý của thềm lục địa:","Khoản 3 Điều 77 UNCLOS phải tuyên bố các vùng biển (Tuyên bố 12/5/1977 của Chính phủ về các vùng biển của CHXHCNVN) trong đó có tuyên bố thềm lục địa là bằng bao nhiêu, còn các quyền như thăm dò, khai thác ở khoản 1 Điều 77 thì không cần tuyên bố mà mặc nhiên có các quyền này.","*Điều 78 UNCLOS:","Bên trên TLD có thể là DQKT hoặc biển quốc tế,","- Vùng trời, vùng nước DQKT thuộc quyền chủ quyền của quốc gia.","*Điều 86:","Biển quốc tế và đáy đại dương là không gian biển chung của nhân loại, không quốc gia nào được xác lập chủ quyền, quyền chủ quyền và quyền tài phán ở đây.","- Các quốc gia có quyền bình đẳng về hàng hải, hàng không, ống dẫn ngầm (Điều 112), các công trình xây dựng, đánh bắt hải sản, NCKH.","- Tàu thuyền hoạt động trên biển quốc tế phải tuân thủ nguyên tắc treo quốc kỳ để biết tàu đó mang quốc tịch của quốc gia nào.","- Biển quốc tế và đáy đại dương chỉ được sử dụng nhằm mục đích hòa bình.","*Phân biệt đá, đảo, bãi cạn lúc chìm lúc nổi: dựa vào ngấn nước thủy triều để gọi tên thực thể địa lý cho chính xác:","- Bãi cạn lúc nổi lúc chìm: thực thể nào thủy chiều xuống thấp nhất thì nổi lên.","- Đá ngầm: thực thể nào thủy triều xuống thấp nhất vẫn nằm dưới đáy biển.","- Đảo: thực thể nào thủy triều lên cao nhất mà nó vẫn ở trên mặt nước và có nước bao quanh (khoản 1 Điều 121).","*Điều 121: Đảo là vùng đất tự nhiên có nước bao bọc (đảo ko phải là đá) khi thủy triều lên vùng đất này ở trên mặt nước (khoản 1 Điều 121).","- Khoản 2 Điều 121: phải thích hợp cho con người đến ở và có một đời sống KT riêng thì mới có lãnh hải, tiếp giáp lãnh hải, đặc quyền KT và thềm lục địa (ví dụ như Đảo Lý Sơn, đảo Phú Quốc, đảo Phú Quý, đảo Bạch Long Vĩ).","- Đảo không thích hợp cho con người đến ở (ở gắn liền với sinh hoạt cộng đồng, có diện tích đủ lớn để làm nhà, có thức ăn, có nước uống) HOẶC không phù hợp cho một đời sống kinh tế riêng thì không có đặc quyền kinh tế và thềm lục địa (vẫn có lãnh hải rộng 12 hải lý) – khoản 3","Điều 121."]},{"q":"Ranh giới quốc gia ven biển là phía ngoài của lãnh hải quốc gia ven biển?","a":["Nhận định sai.","Ranh giới quốc gia ven biển là phía ngoài của lãnh hải quốc gia ven biển trong trường hợp quốc gia không đối diện với quốc gia nào trên biển, do đó nếu quốc gia đối diện với quốc gia khác trên biển thì biên giới quốc gia trên biển sẽ được phân định dựa trên sự thỏa thuận của các quốc gia đối diện với nhau.","*Pháp luật hình sự của quốc gia áp dụng ở nội thủy mà không có bất kỳ ngoại lệ nào. Quy chế pháp lý của nội thủy phụ thuộc vào pháp luật quốc gia.","BLHS có thể áp dụng cho người nước ngoài phạm tội ở nước ngoài."]},{"q":"Lãnh hải là vùng biển nằm ngoài nội thủy","a":["Nhận định sai.","Thông thường lãnh hải là vùng biển nằm ngoài nội thủy, tuy nhiên có trường hợp đặc biệt lãnh hải nằm ngoài lãnh thổ. Ví dụ như đường cơ sở của Việt Nam thì trong tổng số 11 điểm cơ sở thì có 1 điểm cơ sở được xác định theo phương pháp đường cơ sở thông thường (điểm A8). Lãnh hải là vùng biển các quốc gia có quyền mở rộng ra ngoài lãnh thổ. Điểm A8 là lãnh thổ đất liền thì bên ngoài điểm A8 là lãnh hải, những đường cơ sở theo ngấn nước thủy triều thấp nhất xác định theo điểm A8 thì bên trong là bờ còn bên ngoài là lãnh hải, khi thủy triều lên cao nhất thì mới có vùng nội thủy nhỏ hẹp ở đây. Quốc gia quần đảo mở rộng ra vùng nước quần đảo thì bên ngoài được coi là vùng lãnh hải.","CSPL: Điều 3 UNCLOS năm 1982."]},{"q":"Về bản chất, trọng tài đặc biệt là cơ quan tài phán quốc tế","a":["Nhận định sai Tòa trọng tài đặc biệt là cơ quan giải quyết tranh chấp nhưng thực chất nó không phải là cơ quan tài phán theo đúng nghĩa của nó vì nó không ra phán quyết mà ra văn bản có tính chất kiến nghị (kết quả làm việc của Tòa trọng tài đặc biệt chỉ ra văn bản kiến nghị là Nghị quyết để kiến nghị). Hơn nữa, Tòa trọng tài đặc biệt chỉ giải quyết nhóm tranh chấp liên quan đến 04 lĩnh vực:","đánh bắt hải sản, đánh bắt cá, bảo vệ môi trường, NCKH biển, liên quan đến hàng hải do đó Tòa trọng tài đặc biệt không giải quyết tất cả các tranh chấp các quốc gia muốn về giải thích và áp dụng UNCLOS 1982 mà nó chỉ giải quyết tranh chấp trong một phạm vi rất hẹp, rất nhỏ nên không thể giải quyết tất cả bất đồng của các quốc gia tại Tòa trọng tài đặc biệt.","CSPL: Khoản 3 Điều 5 Phụ lục VIII, khoản 1 Điều 287 UNCLOS năm 1982."]}]}]},{"t":"Bộ nhận định và bài tập có đáp án","s":"48 nhận định đúng/sai và 10 bài tập tình huống kèm đáp án tham khảo (tài liệu sinh viên tổng hợp).","g":[{"h":"Nhận định đúng/sai (48 câu)","items":[{"n":1,"q":"Biên giới quốc gia trên biển là đường song song với đường cơ sở, cách đường cơ sở tối đa không vượt quá 12 hải lý.","a":["Nhận định sai.","Vì đối với hai quốc gia có bờ biển kề nhau hoặc đối diện nhau thì đường biên giới là đường trung tuyến mà mọi điểm nằm trên đó cách đều các điểm gần nhất của đường cơ sở.","CSPL: Điều 15 UNCLOS 1982."]},{"n":2,"q":"Biên giới trên bộ và biên giới trên biển là khác nhau.","a":["Nhận định đúng.","Vì biên giới quốc gia trên bộ là đường biên giới được xác định trên đất liền, trên đảo, trên sông, hồ, biển nội địa.","Còn biên giới trên biển là đường được vạch ra để phân định lãnh hải của quốc gia trên biển với vùng tiếp liền tự nhiên của biển cả. Biên giới quốc gia trên biển chính là đường biên giới phía ngoài của lãnh hải do mỗi quốc gia quy định phù hợp với nguyên tắc chung của luật biển quốc tế."]},{"n":3,"q":"Các bãi cạn lúc nổi lúc chìm là các điểm thực chất và dương nhiên để quốc gia ven biển xác định đường cơ sở.","a":["Nhận định sai.","Bãi cạn lúc chìm lúc nổi là vùng đất nhô cao tự nhiên có biển bao quanh, khi thủy triều xuống thấp thì lộ ra, khi thủy triều lên cao thì bị ngập nước. Khi các bãi cạn này ở cách lục đia hoặc một đảo một khoảng cách vượt quá chiều rộng của lãnh hải thì không được sử dụng để xác định đường cơ sở.","Khi các bãi cạn này ở cách lục địa hoặc một đảo khoảng cách không quá chiều rộng của lãnh hải, quốc gia ven biển được quyền:","+ Hoặc áp dụng phương pháp đường cơ sở thông thường;","+ Hoặc áp dụng phương pháp đường cơ sở thẳng nếu ở các bãi cạn đó có những đèn biển hay các thiết bị tương tự thường xuyên nhô trên mặt nước."]},{"n":4,"q":"Các QG ven biển có quyền đơn phương phân định lãnh hải.","a":["Nhận định sai.","Các QG ven biển phải thỏa thuận, đàm phán, ký Điều ước quốc tế để phân định lãnh hải đối với các QG có biển kề nhau hoặc đối diện nhau."]},{"n":5,"q":"Chế độ pháp lý của các vùng biển theo quy định của UNCLOS 1982 và Luật biển VN 2012 là giống nhau.","a":["Nhận định sai.","UNCLOS 1982 là Công ước chung cho tất cả các chủ thể của luật quốc tế, nó có các quy định vừa bao quát vừa cụ thể. Công ước này đã đưa ra tất cả các trường hợp có thể xảy ra trên tất cả các quốc gia để tránh gây tranh chấp cũng như tạo ra sự công bằng cho tất cả các quốc gia.","Còn Luật biển VN 2012 dựa vào các quy định của Công ước để đưa ra những cách xác định các vùng biển hợp lý nhất, đảm bảo lợi thế và quyền của VN là tối đa trong khuôn khổ được cộng đồng quốc tế công nhận."]},{"n":6,"q":"Chế độ pháp lý của lãnh hải và chế độ pháp lý của vùng trời bao trùm lên lãnh hải là giống nhau?","a":["Nhận định sai.","Vì chế độ pháp lý của vùng nước lãnh hải thuộc chủ quyền hoàn toàn và đầy đủ, vì phải để cho tàu thuyền nước ngoài qua lại vô hạn. Chế độ pháp lý của vùng trời bao trùm lên lãnh hải thuộc chủ quyền hoàn toàn tuyệt đối và riêng biệt."]},{"n":7,"q":"Chế độ pháp lý của nội thủy và lãnh hải là giống nhau.","a":["Nhận định sai.","Vì chủ quyền quốc gia đối với nội thủy là chủ quyền hoàn toàn tuyệt đối riêng biệt. Vì vậy quốc gia có quyền quyết định mọi chế độ pháp lý cho vùng nội thủy.","Còn chủ quyền quốc gia đối với lãnh hải là chủ quyền hoàn toàn và đầy đủ. Theo Điều 17 UNCLOS 1982 có quy định tàu thuyền nước ngoài có quyền qua lại vô hại trong vùng này không cần phải xin phép nhưng với điều kiện phải chấp hành Công ước, tức là điểm khác biệt của lãnh hải so với nội thủy là ở lãnh hải, tàu thuyền của mọi QG có biển hay không có biển đều được hưởng quyền đi qua không gây hại.","CSPL: Điều 17, 18, 19 UNCLOS 1982."]},{"n":8,"q":"Chế độ pháp lý của tàu quân sự và tàu thuộc sở hữu của Nhà nước là giống nhau.","a":["Nhận định sai.","Từ Điều 27 đến Điều 32 tiểu mục B và C, Mục 3, Phần II UNCLOS 1982, tàu quân sự và tàu nhà nước phi thương mại mới có chế độ pháp lý giống nhau, còn tàu thương mại Nhà nước sẽ khác chế độ pháp lý khác tàu quân sự."]},{"n":9,"q":"Chế độ pháp lý của vùng tiếp giáp lãnh hải và đặc quyền kinh tế là giống nhau.","a":["Nhận định sai.","Đối với vùng tiếp giáp lãnh hải: Đây là một vùng biển mà QG ven biển được hưởng các quyền mang tính chất chủ quyền trên những lĩnh vực nhất định (mang tính chất cảnh giác). Các quyền thuộc chủ quyền quốc gia ở vùng biển này quy định tại khoản 1 Điều 33 UNCLOS 1982.","Đối với vùng đặc quyền kinh tế: Quyền của các QG ven biển trong vùng đặc quyền kinh tế là “quyền thuộc chủ quyền về việc thăm dò và khai thác, bảo tồn và quản lý các tài nguyên thiên nhiên, sinh vật hoặc phi sinh vật của vùng nước bên trên đáy biển, của đáy biển và lòng đất dưới đáy biển cũng như về những hoạt động khác nhằm thăm dò và khai thác vùng này nhằm mục đích kinh tế, như việc sản xuất năng lượng từ nước, hải lưu và gió” (Điều 56 UNCLOS 1982); các quốc gia ven biển có quyền tài phán trong các lĩnh vực cụ thể.","Vậy nên, chế độ pháp lý của vùng đặc quyền kinh tế thể hiện sự cân bằng giữa các quyền thuộc chủ quyền và quyền tài phán của quốc gia ven biển với các quyền và tự do của các quốc gia khác.","CSPL: Điều 33, Điều 56 và Điều 60 UNCLOS 1982."]},{"n":10,"q":"Chế độ pháp lý của thềm lục địa và đặc quyền kinh tế là giống nhau.","a":["Nhận định sai.","Vì các quyền của QG ven biển đối với thềm lục địa tồn tại đương nhiên, không phụ thuộc vào sự chiếm hữu thực sự hay danh nghĩa, cũng như vào bất cứ tuyên bố rõ ràng nào. Tương tự quy chế pháp lý vùng đặc quyền kinh tế nhưng có thêm hai quyền: Thăm dò, khai thác tài nguyên thiên nhiên và Cho phép khoan ở thềm lục địa. QG ven biển có đặc quyền cho phép và quy định việc khoan ở thềm lục địa bất kỳ vào mục đích gì.","Còn đối với chế độ pháp lý vùng đặc quyền kinh tế phải có tuyên bố đơn phương của QG đó chứ không đương nhiên tồn tại. Có quyền chủ quyền và quyền tài phán về đảo nhân tạo, công trình thiết bị, nghiên cứu khoa học biển và bảo vệ và gìn giữ môi trường biển."]},{"n":11,"q":"Chiều rộng thực tế của vùng đặc quyền kinh tế là 188 hải lý.","a":["Nhận định đúng.","Vì chiều rộng của vùng đặc quyền kinh tế là 200 hải lý tính từ ranh giới phía trong của lãnh hải, tức là đường cơ sở. Còn chiều rộng lãnh hải là 12 hải lý tính từ đường cơ sở. nên thực tế chiều rộng của vùng ĐQKT là 188 hải lý."]},{"n":12,"q":"Chiều rộng thực tế của vùng đặc quyền kinh tế và thềm lục địa là bằng nhau.","a":["Nhận định sai.","Vì chiều rộng của vùng ĐQKT không được mở rộng quá 200 hải lý kể từ đường cơ sở dùng để tính chiều rộng lãnh hải.","Đối với thềm lục địa thì chiều rộng của thềm lục địa có thể được xác lập theo hai giới hạn:","- Trường hợp nếu thềm lục địa của QG ven biển có chiều rộng hẹp hơn hoặc bằng 200 hải lý thì các QG có quyền tuyên bố chiều rộng tối đa của thềm lục địa của mình là 200 hải lý. - Trường hợp nếu thềm lục địa của quốc gia ven biển rộng hơn 200 hải lý thì quốc gia ven biển có thể xác định ranh giới phía ngoài của thềm lục địa bằng hai cách: + Một là, xác định thềm lục địa rộng tối đa là 350 hải lý tính từ đường cơ sở dùng để đo chiều rộng của lãnh hải + Hai là, kéo dài thêm 100 hải lý tính từ đường đẳng sâu là đường nối các điểm có độ sâu trung bình là 2500m.","Vì vậy, chiều dài thực tế của vùng đặc quyền kinh tế và thềm lục địa là không giống nhau.","CSPL: Điều 57 và khoàn 4, 5, 6 Điều 76 UNCLOS 1982."]},{"n":13,"q":"Chủ quyền quốc gia là một thuộc tính tự nhiên vốn có, chỉ quốc gia mới có.","a":["Nhận định đúng.","Vì chủ quyền quốc gia là quyền tối cao của quốc gia trong phạm vi lãnh thổ, và quyền đối với quốc gia khác =\\> Quyền độc lập của quốc gia với các mối quan hệ với các quốc gia khác.","Tổ chức quốc tế liên Chính phủ không có thuộc tính này."]},{"n":14,"q":"“Đánh bắt cá dư” trong vùng đặc quyền kinh tế của QG cùng khu vực là đặc quyền của mọi quốc gia không có biển và địa lý không thuận lợi.","a":["Nhận định sai.","Các QG không có biển và địa lý không thuận lợi muốn vào khai thác số cá dư trong vùng ĐQKT của nước ven biển thì phải đáp ứng được 4 điều kiện sau:","- Là QGG không có biển hoặc có bất lợi về địa lý - Các QG đó phải có vị trí địa lý trong cùng khu vực hoặc khu vực với QG ven biển - QG ven biển không có khả năng đánh bắt hết sản lượng cá có thể đánh bắt - Được QG ven biển chấp nhận thông qua việc ký kết ĐƯQT hoặc các thỏa thuận khác. 15. Đường biên giới của QG trên biển là đường giáp cạnh mà 2 quốc gia liên quan thỏa thuận, quy định."]},{"n":15,"q":"(Đề bài câu 15 không có trong bản trích của tài liệu gốc; giữ nguyên phần đáp án)","a":["Nhận định sai.","Nó chỉ đúng trong trường hợp hai quốc gia liền kề. Nó sai trong trường hợp hai quốc gia nằm đối diện và không nằm liền kề quốc gia nào. Hai quốc gia đối diện nhau thì đường biên giới biển là đường trung tuyến. Hai quốc gia liền kề nhau thì đường biên giới trên biển là đường cách đều."]},{"n":16,"q":"Đường biên giới QG trên biển là đường trung tuyến hoặc giáp cạnh mà các QG liên quan thỏa thuận, lựa chọn.","a":["Nhận định sai.","Đường biên giới QG trên biển là đường trung tuyến hoặc giáp cạnh mà các QG liên quan thỏa thuận lựa chọn chỉ đúng trong trường hợp 2 QG có biển liền kề hoặc đối diện nhau. Và trong trường hợp QG không nằm liền kề hoặc đối diện với QG nào thì đường biên giới của QG trên biển là ranh giới phía ngoài của lãnh hãi."]},{"n":17,"q":"Đường biên giới của quốc gia trên biển là đường song song với đường cơ sở và cách đường cơ sở 1 khoảng cách bằng chiều rộng của lãnh hải.","a":["Nhận định sai.","Trong trường hợp vùng biển có sự tiếp giáp, chồng lấn hoặc đối diện nhau thì việc phân định biên giới trên biển dựa trên thỏa thuận của các quốc gia."]},{"n":18,"q":"Đường cơ sở của Việt Nam được xác định ngày 12/11/1982 hoàn toàn phù hợp với UNCLOS 1982.","a":["Nhận định sai.","Đường cơ sở của VN được xác định ngày 12/11/1982 về cơ bản là phù hợp với UNCLOS 1982. Vì còn một số điểm còn tranh cãi sau:","- Đường cơ sở nước ta chệch quá xa chiều hướng chung của bờ biển - Chiều dài các đoạn cơ sở trung bình 84,6 hải lý (tổng chiều dài 846 hải lý) - Điểm A0 không thực chất - Nhiều điểm quá xa bờ (A1: 56 hải lý; A3: 53 hải lý; A6: 74 hải lý) 19. Lãnh thổ QG trên biển bao gồm: nội thủy, lãnh hải, tiếp giáp lãnh hải, đặc quyền kinh tế và thềm lục địa."]},{"n":19,"q":"(Đề bài câu 19 không có trong bản trích của tài liệu gốc; giữ nguyên phần đáp án)","a":["Nhận định sai.","Lãnh thổ QG trên biển chỉ bao gồm nội thủy và lãnh hải.","Tiếp giáp lãnh hải, đặc quyền kinh tế và thềm lục địa thì QG được quyền khai thác kinh tế và quyền tài phán.","CSPL: Điều 5 NĐ 140/2004/NĐ-CP"]},{"n":20,"q":"Luật biển quốc tế chỉ điều chỉnh quan hệ giữa các quốc gia với nhau.","a":["Nhận định sai.","Vì luật biển quốc tế ngoài điều chỉnh mối quan hệ giữa các quốc gia với nhau còn điều chỉnh các quan hệ quốc tế phát sinh giữa các quốc gia với các chủ thể khác của luật quốc tế, mà cụ thể theo Điều 1 của Phụ lục IX của UNCLOS 1982 về sự tham gia của các tổ chức quốc tế định nghĩa thì: “Các tổ chức quốc tế được hiểu là một tổ chức liên chính phủ được các quốc gia lập nên, nên các quốc gia này trao cho tổ chức có thẩm quyền về các vấn đề mà UNCLOS 1982 đề cập, kể cả thẩm quyền ký kết các Hiệp ước về những vấn đề này”.","VD: Tổ chức hàng hải quốc tế (IMO), Tổ chức khí tượng quốc tế (WMO)…"]},{"n":21,"q":"Mọi QG ven biển đều có các vùng biển thuộc chủ quyền và quyền chủ quyền rộng như nhau.","a":["Nhận định sai.","Vùng biển chủ quyền QG và lãnh thổ QG trên biển gồm nội thủy, vùng nước quần đảo và lãnh hải là những bộ phận cấu thành lãnh thổ vùng nước của quốc gia. Trong đó đối với việc xác định đường cơ sở có hai phương pháp xác định bao gồm đường cơ sở thẳng tại Điều 8 và đường cơ sở thông thường tại Điều 5 UNCLOS 1982, hai phương pháp này áp dụng cho các địa hình bờ biển khác nhau nên chiều rộng của nội thủy là khác nhau.","CSPL: Điều 5, Điều 7 UNCLOS 1982."]},{"n":22,"q":"Ngoài luật quốc tế ra có thể sử dụng các loại nguồn khác.","a":["Nhận định đúng.","Vì ngoài luật quốc tế, nếu hai bên thống nhất thì sự dụng nguồn luật quốc gia, các nguyên tắc pháp luật chung."]},{"n":23,"q":"Việt Nam áp dụng phương pháp đường cơ sở thẳng để xác định đường cơ sở theo Tuyên bố của Chính phủ nước CHXHCNVN ngày 12/11/1982.","a":["Nhận định sai.","Trong 11 điểm cơ sở mà VN đã tuyên bố có 10 điểm được xác định theo phương pháp đường cơ sở thẳng và 1 điểm được xác định theo đường cơ sở thông thường, đó là điểm A8."]},{"n":24,"q":"Quốc gia có chủ quyền hoàn toàn và tuyệt đối với tất cả những bộ phận cấu thành lãnh thổ quốc gia.","a":["Nhận định sai.","Vì chủ quyền của quốc gia đối với những vùng lãnh thổ khác nhau là khác nhau.","Vùng đất: chủ quyền hoàn toàn tuyệt đối Vùng nước: chủ quyền không tuyệt đối Vùng trời: chủ quyền tuyệt đối Vùng lòng đất: được mặc nhiên thừa nhận trong quan hệ quốc tế thuộc chủ quyền hoàn toàn tuyệt đối của quốc gia."]},{"n":25,"q":"Quốc gia có quyền đơn phương xác định biên giới trên biển","a":["Nhận định sai.","Về phương diện pháp lý, phân định biển là hành vi pháp lý do các quốc gia kề nhau hoặc đối diện nhau thỏa thuận thực hiện, có thể trực tiếp hoặc thông qua bên thứ 3 (Tòa án quốc tế hoặc trọng tài quốc tế) phù hợp với luật quốc tế nhằm xác định biên giới quốc gia trên biển.","CSPL: Điều 15 UNCLOS 1982."]},{"n":26,"q":"Quốc gia không có thẩm quyền tuyệt đối với các bộ phận lãnh thổ.","a":["Nhận định đúng.","Vì giữa các bộ phận lãnh thổ có quy chế pháp lý khác nhau. Đối với vùng biển của quốc gia thì có vùng biển thuộc chủ quyền quốc gia, có vùng biển không thuộc chủ quyền quốc gia. Trong đó lãnh hải là vùng biển thuộc chủ quyền quốc gia nhưng vẫn có chế độ “đi qua không gây hại”."]},{"n":27,"q":"Quốc gia ven biển có quyền xử lý, xét xử mọi hành vi vi phạm PL của tàu thuyền nước ngoài trong nội thủy của mình.","a":["Nhận định sai.","Chỉ có quyền yêu cầu tàu đó ra khỏi vùng nội thủy chứ không có quyền xử lý, xét xử hành vi vi phạm PL.","CSPL: khoản 2 Điều 27, khoản 3 Điều 28 và Điều 95 UNCLOS 1982."]},{"n":28,"q":"Quy chế pháp lý của lãnh hải theo quy định của UNCLOS 1982 và Luật biển VN 2012 là giống nhau.","a":["Nhận định sai.","Về cơ bản, các quy định về quyền đi qua không gây hại của tàu thuyền nước ngoài trong lãnh hải VN được quy định tại Luật biển VN 2012 là tương thích với UNCLOS 1982 ngoại trừ quy định tại khoàn 12 Điều 12 về việc “khi thực hiện quyền đi qua không gây hại trong lãnh hải VN, thông báo trước cho cơ quan có thẩm quyền của VN”. Vì quy định như vậy sẽ bảo đảm được sự chủ động trong việc giám sát hoạt động của tàu quân sự nước ngoài khi hoạt động trong lãnh hải VN. Nên quy chế pháp lý của lãnh hải theo quy định của UNCLOS 1982 và Luật biển VN 2012 là không giống nhau.","CSPL: khoản 2 Điều 12 Luật biển VN 2012."]},{"n":29,"q":"Quyền “đi qua không gây hại” là sự ưu tiên của nước ven biển dành cho tàu thuyền nước ngoài.","a":["Nhận định sai."]},{"n":30,"q":"Ranh giới phía ngoài của thềm lục địa là đường song song với đường cơ sở và cách đường cơ sở 1 khoảng cách 200 hải lý.","a":["Nhận định sai.","Vì nó chỉ đúng trong trường hợp những nước có thềm lục địa hẹp (nhỏ hơn 200 hải lý). Đối với những nước có thềm lục địa rộng (201 hải lý trở lên) được quyền lựa chọn 1 trong hai cách sau: Kéo dài tối đa 350 hải lý từ đường cơ sở hoặc Kéo dài tối đa 100 hải lý từ đường đẳng sâu 2500m."]},{"n":31,"q":"Ranh giới phía ngoài thềm lục địa là đường song song với đường đẳng sâu và cách đường đường sâu 100 hải lý.","a":["Nhận định sai.","Nhận định chỉ đúng trong trường hợp những nước có thềm lục địa rộng và tính bằng cách 2 (kéo dài tối đa 100 hải lý từ đường đẳng sâu 2500m)."]},{"n":32,"q":"Ranh giới phía ngoài thềm lục địa là đường song song với đường cơ sở và cách đường cơ sở một khoảng cách 350 hải lý.","a":["Nhận định sai.","Nhận định chỉ đúng trong trường hợp QG có thềm lục địa rộng và xác định chiều rộng của thềm lục địa bằng cách kéo dài tối đa 350 hải lý từ đường cơ sở."]},{"n":33,"q":"Tàu bay được quyền đi qua không gây hại trên lãnh hải","a":["Nhận định sai.","Quyền đi qua không ây hại chỉ áp dụng cho tàu thuyền trên mặt biển của lãnh hải, không bao gồm tàu ngầm.","Vùng trời trên lãnh hải thuộc chủ quyền hoàn toàn và tuyệt đối của QG nên tàu bay không được quyền đi qua trên vùng trời này.","Tàu bay quân sự được phép bắn nếu xâm phạm.","Tàu bay dân sự được dùng mọi biện pháp để đuổi ra và giám sát."]},{"n":34,"q":"Tàu quân sự không được hưởng quyền đi qua không gây hại theo UNCLOS.","a":["Nhận định sai.","Vùng lãnh hải thuộc chủ quyền đầy đủ nhưng không tuyệt đối.","Tàu quân sự được đi qua không gây hại nếu tuân thủ Điều 17 đến Điều 25 UNCLOS 1982."]},{"n":35,"q":"Tất cả các tàu thuyền của Nhà nước đều được hưởng quyền miễn trừ tuyệt đối về tài phán.","a":["Nhận định sai.","Vì tàu thuyền của Nhà nước chỉ chỉ có tàu quân sự, tàu Nhà nước phi thương mại mới được hưởng quyền miễn trừ tuyệt đối về tài phán. Còn tàu Nhà nước thương mại thì không được hưởng quyền miễn trừ tuyệt đối mà vẫn hưởng quy chế pháp lý của tàu dân sự thông thường."]},{"n":36,"q":"Thềm lục địa có chiều rộng tối đa là 350 hải lý.","a":["Nhận định sai.","Vì thềm lục địa có chiều rộng tối đa được xác định là 350 hải lý là so với đường cơ sở trong trường hợp khi mà bờ ngoài của rìa lục địa lớn hơn khoảng cách 200 hải lý tính từ đường cơ sở. Nhưng chiều rộng của thềm lục đại cũng cần được xác định theo cách khác nữa, đó là 100 hải lý tính từ đường đẳng sâu 2.500."]},{"n":37,"q":"Tiếp giáp lãnh hải là một vùng biển có quy chế pháp lý độc lập.","a":["Nhận định sai.","Theo Điều 33 và Điều 55 UNCLOS 1982, tiếp giáp lãnh hải chỉ là một bộ phận của vùng đặc quyền kinh tế, do đó nó không có quy chế pháp lý riêng mà vùng đặc quyền kinh tế bao trùm lên nó mới có quy chế pháp lý riêng."]},{"n":38,"q":"Tòa án công lý quốc tế có thẩm quyền giải quyết theo trình tự phúc thẩm.","a":["Nhận định sai.","Vì nếu giải quyết theo trình tự phúc thẩm thì ở cấp cao hơn, mà nó chỉ là xem xét lại phán quyết ấy, phán quyết của tòa án công lý quốc tế có giá trị trung lập, các bên không có quyền kháng án, hiệu lực của phán quyết là hiệu lực bắt buộc các bên phải thi hành."]},{"n":39,"q":"Tự do hàng hải chính là quyền đi qua không gây hại trên các vùng biển theo quy định của UNCLOS 1982.","a":["Nhận định sai.","Tự do hàng hải là quyền của tất cả các quốc gia, bao gồm cả những quốc gia không có bờ biển, được sử dụng các phương tiện vận chuyển trên mặt nước, dưới mặt nước để đi lại tự do, không bị khám xét trên các vùng biển quốc tế, được đi qua vô hại các vùng tiếp giáp lãnh hải, các vùng đặc quyền kinh tế của các quốc gia… thuộc chủ quyền của nước nào nhất thiết phải theo đúng quy định của PL nước đó.","Còn quyền đi qua không gây hại căn cứ tại Điều 17 UNCLOS 1982 là việc tàu thuyền của tất cả các QG có biển hay không có biển, đều được hưởng quyền đi qua không gây hại trong lãnh hải.","Như vậy, xét về phương tiện và phạm vi đi lại thì tự do hàng hải lớn hơn và bao trùm quyền đi qua không gây hại."]},{"n":40,"q":"Trên biển quốc tế, địa vị pháp lý của mọi tàu thuyền là giống nhau.","a":["Nhận định sai.","Chẳng hạn như tàu chiến và tàu Nhà nước được dùng vào các mục đích phi thương mại thì sẽ được hưởng quyền miễn trừ hoàn toàn khi nó hoạt động hợp pháp trên các vùng biển. Trong khi đó, nếu là tàu thuyền hoạt động dưới cờ của một quốc gia khi ra vùng biển quốc tế sẽ không được hưởng quyền này. Vậy nên, địa vị pháp lý của mọi tàu thuyền khi ở trên biển quốc tế là không giống nhau.","CSPL: khoản 1 Điều 92, Điều 95, Điều 96 UNCLOS 1982."]},{"n":41,"q":"Trong các vùng biển thuộc chủ quyền, quyền chủ quyền quốc gia, lãnh hải là vùng biển quan trọng nhất.","a":["Nhận định sai.","Trong các vùng biển thuộc chủ quyền, quyền chủ quyền quốc gia, nội thủy là vùng biển quan trọng nhất. Bởi vì 2 lý do sau:","- Về phương diện pháp lý: Trong vùng nội thủy quốc gia có chủ quyền hoàn toàn tuyệt đối - Về phương diện thực tiễn khai thác, quản lý, sử dụng biển: Trong vùng nước nội thủy có nhiều cảng biển dùng vào mục đích quân sự, dân sự, thương mại của quốc gia ven biển. Do vậy, ở vùng nội thủy, tàu buôn, tàu thương mại của các quốc gia thường xuyên ra vào, neo đậu và hoạt động vì mục đích thương mại. Ngoài ra còn có các tàu quân sự và tàu Nhà nước hoạt động phi thương mại của các quốc gia thực hiện các hoạt động thăm viếng, giao lưu, sửa chữa, hợp tác quốc tế. 42. Trong việc giải quyết các tranh chấp quốc tế là không có giới hạn."]},{"n":42,"q":"(Đề bài câu 42 không có trong bản trích của tài liệu gốc; giữ nguyên phần đáp án)","a":["Nhận định sai.","Vì các chủ thể tham gia tranh chấp phải có nghĩa vụ sử dụng các biện pháp hòa bình để giải quyết các tranh chấp quốc tế phát sinh, không được phép sử dụng vũ lực để giải quyết tranh chấp trong bất kỳ trường hợp nào."]},{"n":43,"q":"Trong hoạch định biển thì tuyên bố chiều rộng của các vùng biển thuộc chủ quyền quốc gia là hành vi quan trọng nhất","a":["Nhận định sai.","Việc tuyên bố đường cơ sở mới là quan trọng nhất, là tiền đề để các quốc gia hoạch định vùng biển thuộc chủ quyền, quyền chủ quyền và quyền tài phán của quốc gia."]},{"n":44,"q":"UNCLOS 1982 là cơ sở pháp lý để giải quyết mọi tranh chấp quốc tế về biển.","a":["Nhận định sai.","Vì UNCLOS 1982 chỉ là cơ sở pháp lý để giải quyết các tranh chấp quốc tế về biển thuộc phạm vi điều chỉnh của UNCLOS 1982, cụ thể chỉ đối với 08 loại tranh chấp sau:","(1) Việc xác định các vùng biển và phân định biển trong trường hợp tồn tại các vùng chồng lấn (2) Quy chế pháp lý của các cấu trúc địa chất trên biển (3) Việc thực thi chủ quyền, quyền chủ quyền và quyền tài phán của quốc gia trên biển (4) Việc thực thi quyền hàng hải, quyền hàng không, lắp đặt và sử dụng công trình thiết bị nhân tạo, đảo nhân tạo, khoan thăm dò ở thềm lục địa (5) Việc khai thác, quản lý và bảo tồn nguồn tài nguyên biển (6) Bảo vệ và giữ gìn môi trường biển (7) Nghiên cứu khoa học (8) Khai thác, sử dụng biển quốc tế và vùng đáy đại dương (la zone). 45. Về bản chất, trọng tài đặc biệt chính là một cơ quan tài phán quốc tế."]},{"n":45,"q":"(Đề bài câu 45 không có trong bản trích của tài liệu gốc; giữ nguyên phần đáp án)","a":["Nhận định sai.","Vì về bản chất, trọng tài đặc biệt chỉ có chức năng điều tra và xác lập các sự kiện từ nguồn gốc vụ tranh chấp liên quan đến đánh bắt hải sản, bảo vệ và giữ gìn môi trưởng biển, nghiên cứu khoa học biển và hàng hải, kể cả nạn ô nhiễm do các tàu thuyền hay do nhấn chìm chứ không thật sự là cơ quan có chức năng “giải quyết tranh chấp” (hay còn gọi là cơ quan tài phán) như trọng tài về Luật biển.","Vậy về bản chất thì trọng tài đặc biệt không phải là một cơ quan tài phán quốc tế.","CSPL: khoản 1 Điều 5 Phụ lục VIII UNCLOS 1982."]},{"n":46,"q":"Vùng đặc quyền kinh tế là vùng biển đặc thù, không phải là lãnh hải cũng không phải là công hải.","a":["Nhận định đúng.","Đường cơ sở là ranh giưới trong thềm lục địa. Vì chiều rộng của nó là 200 hải lý tính từ đường cơ sở nên nó đã bao gồm chiều rộng của lãnh hải và 1 bộ phận nằm ngoài lãnh hải. Mặt khác, vùng biển quốc tế lại tính từ ranh giới phía ngoài của nó. Do vậy, nó không phải là vùng lãnh hải cũng không phải là công hải."]},{"n":47,"q":"Vùng nội thủy, vùng lãnh hải, vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế là lãnh thổ của quốc gia ven biển.","a":["Nhận định sai.","Vì vùng nội thủy, vùng lãnh hải mới là lãnh thổ của quốc gia ven biển. Còn ranh giới phía ngoài lãnh hải gọi là đường biên giới quốc gia trên biển. Còn vùng tiếp giáp lãnh hải và vùng đặc quyền kinh tế theo định nghĩa là những vùng biển nằm ngoài lãnh hải và được xem là vùng biển thuộc quyền chủ quyền của quốc gia. Vì vậy hai vùng biển này không được coi là lãnh thổ của quốc gia."]},{"n":48,"q":"Vùng tiếp giáp lãnh hải không phải là bộ phận lãnh thổ quốc gia.","a":["Nhận định đúng.","Vì vùng biên giới quốc gia trên biển chính là ranh giới phía ngoài của lãnh hải, còn vùng tiếp giáp lãnh hải và vùng biển là không thuộc chủ quyền quốc gia."]}]},{"h":"Bài tập tình huống (10 bài)","items":[{"qs":["Bài tập 1. Có 3 chiếc tàu nước ngoài X (là tàu quân sự), Y (là tàu chở khách), Z (là tàu chở hàng) đang ở vùng nội thủy của quốc gia A. Bằng kiến thức về Luật biển quốc tế đã được học, anh/ chị hãy cho biết quốc gia A giải quyết thế nào trong trường hợp:","a) 3 chiếc tàu trên phạm vi pháp luật ở vùng nội thủy của quốc gia A?  Trường hợp tàu X vi phạm PL ở vùng nội thủy của quốc gia A:","Căn cứ tiểu mục C của Công ước luật biển 1982, vì tàu X là tàu quân sự nên được hưởng quyền miễn trừ tuyệt đối về mặt tư pháp và được coi là bất khả xâm phạm. Quốc gia A không có quyền tài phán hành vi vi phạm và thiệt hại do tàu X gây ra.","Trong trường hợp này, quốc gia A có quyền:","- Yêu cầu tàu X ra khỏi nội thủy trong một thời gian nhất định (Điều 30 UNCLOS) - Yêu cầu quốc gia có tàu X phải áp dụng chế tài hợp pháp với thủy thủ vi phạm - Yêu cầu quốc gia có tàu X phải bồi thường thiệt hại do hành vi vi phạm của tàu X gây ra trong thời gian đậu ở nội thủy của quốc gia A (Điều 31 UNCLOS)  Trường hợp tàu Y và tàu Z vi phạm PL ở vùng nội thủy của quốc gia A:","Nếu vi phạm PL đó là vi phạm hình sự: Tàu Y và tàu Z phải chịu sự tài phán của quốc gia A. Quốc gia A có quyền bắt giữ, truy tố, xét xử theo PL của nước mình trước Tòa án của nước mình đối với hành vi phạm pháp trên nội thủy của 2 tàu này (khoản 2 Điều 27 UNCLOS 1987). Những hành động phạm pháp xảy ra trên tàu trongg thời gian tàu đang đậu ở nội thủy của quốc gia A thì quốc gia A có quyền xét xử trong các trường hợp sau:","- Nếu hành vi phạm tội do một người ngoài thủy thủ đoàn thực hiện; - Nếu thuyền trưởng yêu cầu chính quyền nước A can thiệp; - Nếu hậu quả của nó ảnh hưởng tới an ninh trật tự của nội thủy.","Nếu vi phạm pháp luật đó là vi phạm dân sự: Tòa án của quốc gia A có quyền xét xử các vụ kiện dân sự (khoản 3 Điều 28 UNCLOS 1982):","- Giữa tàu Y và tàu Z với nhau hoặc với các tàu nước ngoài khác cùng đậu ở nội thủy của quốc gia A; - Giữa thủy thủ đoàn của tàu với công dân nước A.","Nếu vi phạm pháp luật đó là vi phạm hành chính: Cơ quan có thẩm quyền của quốc gia A có quyền xử phạt vi phạm hành chính đối với tàu và thủy thủ đoàn của tàu Y, Z khi vi phạm PL trong lãnh thổ của quốc gia A (Nội thủy là một bộ phận của lãnh thổ quốc gia).","b) Nhân viên của 3 chiếc tàu trên vi phạm pháp luật quốc gia A khi đã lên trên bờ? - Về mặt hình sự: Nếu nhân viên của 3 chiếc tàu trên vi phạm pháp luật hình sự quốc gia A khi đã lên trên bờ thì quốc gia A có thẩm quyền bắt giữ, truy tố và xét xử hành vi phạm tội theo PLHS của quốc gia A. - Về mặt dân sự: Cơ quan có thẩm quyền của quốc gia A có quyền xét xử các vụ kiện dân sự có liên quan đến nhân viên của 3 chiếc tàu này khi họ đã lên bờ. - Về mặt hành chính: Cơ quan có thẩm quyền của quốc gia A có quyền điều tra, xem xét các vụ vi phạm hành chính của các nhân viên 3 chiếc tàu này khi họ đã lên trên bờ."],"a":["Trong 3 chiếc tàu đã nêu: - tàu X là tàu quân sự","- tàu Y (tàu chở khách) và tàu Z (tàu chở hàng) là tàu dân sự dùng trong lĩnh vực thương mại a. Ø Trường hợp tàu X vi phạm pháp luật ở vùng nội thủy của quốc gia A: Căn cứ tiểu mục C của Công ước luật biển 1982, vì tàu X là tàu quân sự nên được hưởng quyền miễn trừ tuyệt đối về tư pháp và được coi là bất khả xâm phạm. Quốc gia A không có quyền tài phán hành vi vi phạm và thiệt hại do tàu X gây ra.","Trong trường hợp này, quốc gia A có quyền: - Yêu cầu tàu X ra khỏi nội thủy trong một thời gian nhất định (Điều 30 CƯ); - Yêu cầu quốc gia có tàu X phải áp dụng chế tài hợp pháp với thủy thủ vi phạm;- Yêu cầu quốc gia có tàu X phải bồi thường thiệt hại do hành vi vi phạm của tàu X gây ra trong thời gian đậu ở nội thủy của quốc gia A (Điều 31 CƯ).","Ø Trường hợp tàu Y và tàu Z vi phạm pháp luật ở vùng nội thủy của quốc gia A:","v Nếu vi phạm pháp luật đó là vi phạm hình sự: Tàu Y và tàu Z phải chịu sự tài phán của quốc gia A. Quốc gia A có quyền bắt giữ, truy tố, xét xử theo pháp luật của nước mình trước Tòa án của nước mình đối với hành vi phạm pháp trên nội thủy của 2 tàu này (khoản 2 Điều 27 CƯ). Những hành động phạm pháp xảy ra trên tàu trong thời gian tàu đang đậu ở nội thủy của quốc gia A thì quốc gia A có quyền xét xử trong các trường hợp sau:","- Nếu hành vi phạm tội do một người ngoài thủy thủ đoàn thực hiện; - Nếu thuyền trưởng yêu cầu chính quyền nước A can thiệp; - Nếu hậu quả của nó ảnh hưởng tới an ninh trật tự của nội thủy. v Nếu vi phạm pháp luật đó là vi phạm dân sự: Tòa án của quốc gia A có quyền xét xử các vụ kiện dân sự (khoản 3 Điều 28 CƯ):","- Giữa tàu Y và tàu Z với nhau hoặc với các tàu nước ngoài khác cùng đậu ở nội thủy của quốc gia A;","- Giữa thủy thủ đoàn của tàu với công dân nước A. v Nếu vi phạm pháp luật đó là vi phạm hành chính: Cơ quan có thẩm quyền của quốc gia A có quyền xử phạt vi phạm hành chính đối với tàu và thủy thủ đoàn của tàu Y, Z khi vi phạm pháp luật trong lãnh thổ của quốc gia A (Nội thủy là một bộ phận của lãnh thổ quốc gia).","b. Ø Về mặt hình sự: Nếu nhân viên của 3 chiếc tàu trên vi phạm pháp luật hình sự quốc gia A khi đã lên trên bờ thì quốc gia A có thẩm quyền bắt giữ, truy tố và xét xử hành vi phạm tội theo pháp luật hình sự của quốc gia A.","Ø Về mặt dân sự: Cơ quan có thẩm quyền của quốc gia A có quyền xét xử các vụ kiện dân sự có liên quan đến nhân viên của 3 chiếc tàu này khi họ đã lên bờ.","Ø Về mặt hành chính: Cơ quan có thẩm quyền của quốc gia A có quyền điều tra, xem xét các vụ vi phạm hành chính của các nhân viên 3 chiếc tàu này khi họ đã lên trên bờ."],"q":"Bài tập 1. Có 3 chiếc tàu nước ngoài X (là tàu quân sự), Y (là tàu chở khách), Z (là tàu chở hàng) đang ở vùng nội thủy của quốc gia A. Bằng"},{"qs":["Bài tập 2. Tàu đánh cá của quốc gia B khi đang đi qua lãnh hải của quốc gia cho 1 máy bay dân sự (đang đậu trên tàu) cất cánh. Bằng kiến thức về Luật biển quốc tế đã được học, anh/chị hãy cho biết: Tàu đánh cá và máy bay dân sự vi phạm nội dung gì? CSPL? Quốc gia A được thực hiện quyền gì đối với tàu đánh cá và máy bay dân sự nói trên? CSPL?"," Đối với tàu đánh cá:","Tàu đánh cá của quốc gia B khi đang đi qua lãnh hải của quốc gia cho 1 máy bay dân sự (đang đậu trên tàu) cất cánh thì tàu đánh cá này đã vi phạm quy định về quyền đi qua không gây hại tại Điều 17 UNCLOS 1982. Cụ thể, việc tàu đánh cá đi qua lãnh hải và cho máy bay đang đậu trên tàu cất cánh được xem là phương hại đến hòa bình, an ninh, trật tự của quốc gia ven biển, được quy định tại điểm d khoản 2 Điều 19 UNCLOS 1982. Như vậy, khi tàu này có vi phạm, quốc gia ven biển được phép thực hiện các biện pháp nhằm ngăn cản việc đi qua có hại theo quy định tại Điều 25 UNCLOS 1982 và có quyền tài phán về mặt hình sự đối với tàu đánh cá nước B, theo quy định tại điểm b khoản 1 Điều 27 UNCLOS 1982."," Đối với máy bay dân sự:","Lãnh hải bao gồm lớp nước biển, đáy biển, lòng đất dưới đáy biển và vùng trời bao trùm trên lãnh hải. Trong đó, đối với đáy biển, lòng đất dưới đáy biển và vùng trời bao trùm lên lãnh hải, quốc gia ven biển có chủ quyền tuyể đối. Vùng trời bao trùm trên lãnh hải là một bộ phận cấu thành vùng trời quốc gia, do đó, quốc gia có chủ quyền tối cao và trọn vẹn trong việc thiết lập và thực hiện các quyền năng về chiếm hữu, sử dụng và định đoạt các vấn đề pháp lý liên quan. Cụ thể, các quốc gia có quyền quyết định chế độ pháp lý của vùng trời nước mình một cách độc lập cũng như quy định trình tự, thủ tục và các điều kiện mà phương tiện bay nước ngoài sử dụng vùng trười quốc gia phải đáp ứng, quốc gia sẽ không cho phép bất kỳ một loại phương tiện giao thông nào của nước ngoài qua lại gây hại trên lãnh thổ của mình. Mọi hành vi qua lại của người, phương tiện giao thông nước ngoài đều phải xin phép hoặc áp dụng theo những quy định của các Điều ước quốc tế đã được các quốc gia hữu quan ký kết. Mọi hành vi tự ý bay vào không được sự cho phép của quốc gia sở tại đều lành hành vi xâm phạm vào lãnh thổ quốc gia. Như vậy, hành vi vi phạm của máy bay dân sự sẽ không được điều chỉnh, xử lý bằng UNCLOS 1982 mà được xử lý theo quy định PL của quốc gia A."],"a":["a. Đối với tàu đánh cá:","Tàu đánh cá của quốc gia B khi đi qua đang đi qua lãnh hải của quốc gia cho 1 máy bay dân sự (đang đậu trên tàu) cất cánh thì tàu đánh cá này đã vi phạm quy định về quyền đi qua không gây hại tại Điều 17 Công ước về Luật Biển 1982. Cụ thể, việc tàu đánh cá đi qua lãnh hải và cho máy bay đang đậu trên tàu cất cánh được xem là phương hại đến hòa bình, an ninh, trật tự của quốc gia ven biển, được quy định tại điểm d khoản 2 Điều 19 của Công ước về Luật Biển 1982. Theo đó: “Việc đi qua của một tàu thuyền nước ngoài bị coi như phương hại đến hòa bình, trật tự hay an ninh của quốc gia ven biển, nếu như ở trong lãnh hải, tàu thuyền này tiến hành một trong bất kỳ hoạt động nào sau đây:","…d) Phóng đi, tiếp nhận hay xếp lên tàu các phương tiện bay; …”. Như vậy, khi tàu này có vi phạm, quốc gia ven biển được phép thực hiện các biện pháp nhằm ngăn cản việc đi qua có hại theo quy định tại Điều 25 của Công ước về Luật Biển 1982 và có quyền tài phán về mặt hình sự đối với tàu đánh cá nước B, theo quy định tại điểm b khoản 1 Điều 27 của Công ước về Luật Biển 1982.","Điều 25. Quyền bảo vệ các quốc gia ven biển 1. Quốc gia ven biển có thể thi hành các biện pháp cần thiết trong lãnh hải của mình để ngăn cản mọi việc đi qua có gây hại.","2. Đối với tàu thuyền đi vào vùng nội thủy hay vào một công trình cảng ở bên ngoài vùng nội thủy đó, quốc gia ven biển cũng có quyền thi hành những biện pháp cần thiết để ngăn ngừa mọi sự vi phạm đối với các điều kiện mà tàu thuyền này buộc phải tuân theo để được phép vào vùng nội thủy hay công trình cảng nói trên.","3. Quốc gia ven biển có thể tạm thời đình chỉ việc thực hiện quyền đi qua không gây hại của tàu thuyền nước ngoài tại các khu vực nhất định trong lãnh hải của mình, nếu biện pháp này là cần thiết để bảo đảm an ninh của mình, kể cả để thử vũ khí, nhưng không được phân biệt đối xử về mặt pháp lý hay về mặt thực tế giữa các tàu thuyền nước ngoài. Việc đình chỉ này chỉ có hiệu lực sau khi đã được công bố theo đúng thủ tục.","Điều 27. Quyền tài phán hình sự ở trên một tàu nước ngoài 1. Quốc gia ven biển không được thực hiện quyền tài phán hình sự của mình ở trên một tàu nước ngoài đi qua lãnh hải để tiến hành việc bắt giữ hay tiến hành việc dự thẩm sau một vụ vi phạm hình sự xảy ra trên con tàu trong khi nó đi qua lãnh hải, trừ các trường hợp sau đây:","a) Nếu hậu quả của vụ vi phạm đó mở rộng đến quốc gia ven biển; b) Nếu vụ vi phạm có tính chất phá hoại hòa bình của đất nước hay trật tự trong lãnh hải;","c) Nếu thuyền trưởng hay một viên chức ngoại giao hoặc một viên chức lãnh sự của quốc gia mà tàu mang cờ yêu cầu sự giúp đỡ của các nhà đương cục địa phương hoặc d) Nếu các biện pháp này là cần thiết để trấn áp việc buôn lậu chất ma túy hay các chất kích thích.","2. Khoản 1 không đụng chạm gì đến quyền của quốc gia ven biển áp dụng mọi luật pháp mà luật trong nước mình qui định nhằm tiến hành các việc bắt giữ hay tiến hành việc dự thẩm ở trên con tàu nước ngoài đi qua lãnh hải, sau khi rời khỏi nội thủy.","3. Trong những trường hợp nêu ở các khoản 1 và 2, nếu thuyền trưởng yêu cầu, quốc gia ven biển phải thông báo trước về mọi biện pháp cho một viên chức ngoại giao hay cho một viên chức lãnh sự của quốc gia mà tàu mang cờ và phải tạo điều kiện dễ dàng cho viên chức ngoại giao hay viên chức lãnh sự đó tiếp xúc với đoàn thủy thủ của con tàu. Tuy nhiên trong trường hợp khẩn cấp, việc thông báo này có thể tiến hành trong khi các biện pháp đang được thi hành.","4. Khi xem xét có nên bắt giữ và các thể thức của việc bắt giữ, nhà đương cục địa phương cần phải chú ý thích đáng đến các lợi ích về hàng hải.","5. Trừ trường hợp áp dụng phần XII hay trong trường hợp có sự vi phạm các luật và quy định được định ra theo đúng phần V, quốc gia ven biển không được thực hiện một biện pháp nào ở trên một con tàu nước ngoài khi nó đi qua lãnh hải nhằm tiến hành bắt giữ hay tiến hành việc dự thẩm sau một vụ vị phạm hình sự xảy ra trước khi con tàu đi vào lãnh hải mà không đi vào nội thủy.","b. Đối với máy bay dân sự: Lãnh hải bảo gồm lớp nước biển, đáy biển, lòng đất dưới đáy biển và vùng trời bao trùm trên lãnh hải. Trong đó, đối với đáy biển, lòng đất dưới đáy biển và vùng trời bao trùm lên lãnh hải, quốc gia ven biển có chủ quyền tuyệt đối. Vùng trời bao trùm trên lãnh hải là một bộ phận cấu thành vùng trời quốc gia, do đó, quốc gia có chủ quyền tối cao và trọn vẹn trong việc thiết lập và thực hiện các quyền năng về chiếm hữu, sử dụng và định đoạt các vấn đề pháp lý liên quan. Cụ thể, các quốc gia có quyền quyết định chế độ pháp lý của vùng trời nước mình một cách độc lập cũng như quy định trình tự, thủ tục và các điều kiện mà phương tiện bay nước ngoài sử dụng vùng trời quốc gia phải đáp ứng, quốc gia sẽ không cho phép bất kì một loại phương tiện giao thông nào của nước ngoài qua lại không gây hại trên lãnh thổ của mình. Mọi hành vi qua lại của người, phương tiện giao thông nước ngoài đều xin phép, hoặc áp dụng theo những quy định của các điều ước quốc tế đã được các quốc gia hữu quan kí kết. Mọi hành vi tự ý bay vào không được sự cho phép của quốc gia sở tại đều là hành vi xâm phạm vào lãnh thổ quốc gia. Như vậy, hành vi vi phạm của máy bay dân sự sẽ không được điều chỉnh, xử lý bằng Công ước về Luật viển 1982 mà bằng luật của quốc gia A."],"q":"Bài tập 2. Tàu đánh cá của quốc gia B khi đang đi qua lãnh hải của quốc gia cho 1 máy bay dân sự (đang đậu trên tàu) cất cánh. Bằng kiến thứ"},{"qs":["Bài tập 3. Tàu chở hàng của quốc gia B khi đi qua vùng tiếp giáp của quốc gia A đã thực hiện các hành vi sau:","a) Cho 1 máy bay dân sự chở 1 kiện hàng cất cánh;","Đối với chiếc máy bay dân sự cất cánh từ vùng tiếp giáp lãnh hải:","Cần chia ra hai trường hợp, nếu chiếc máy bay dân sự này cất cánh bay về phía lãnh hải của quốc gia A thì quốc gia A có quyền ngăn chặn không cho phép máy bay trên bay vào, bởi lẽ máy bay là phương tiện bay và không được hưởn quyền đi qua không gây hại dành cho tàu biển theo quy định tại Điều 17 UNCLOS 1982. Còn trong trường hợp máy bay này bay ra phía biển quốc tế, thì quốc gia A không có quyền gì đối với máy bay dân sự này.","b) Cho dỡ 1 container hàng (chứa xe hơi) chuyển xuống tàu hàng của quốc gia A Hãy cho biết: QG A có quyền gì đối với hai chiếc tàu và máy bay nói trên? CSPL?"," Đối với tàu chở hàng của QG B: - Nếu tàu này không có sự vi phạm các luật hay quy định của quốc gia đó về hải quan, thuế khóa, y tế hay nhập cư trong phạm vi lãnh thổ hay lãnh hải của QG mình thì QG A không có quyền gì cả. - Nếu có sự vi phạm các luật hay quy định của quốc gia đó về hải quan, thuế khóa, y tế hay nhập cư thì tùy vào hướng đi của con tàu này mà sẽ giải quyết như sau:","+ Tàu này đang đi theo hướng vào vùng lãnh hải thì quốc gia A được quyền tiến hành các biện pháp kiểm soát cần thiết nhằm ngăn chặn sự vi phạm.","+ Tàu này đang từ vùng tiếp giáp đi ra vùng biển quốc tế và sự vi phạm này không xảy ra trong phạm vi lãnh thổ hay lãnh hải của quốc gia A thì quốc gia A không được quyền làm gì cả.","+ Tàu này đi ra vùng biển quốc tế nhưng sự vi phạm này xảy ra trong phạm vi lãnh thổ hay lãnh hải của quốc gia A thì quốc gia A được quyền trừng trị sự vi phạm đó đối với chiếc tàu này.","CSPL: khoản 1 Điều 33 UNCLOS 1982  Đối với tàu hàng của quốc gia A:","Quốc gia A sẽ có đầy đủ các quyền tài phán theo quy định và PL của QG A. Bởi lẽ, đây là tàu hàng của quốc gia A nên phải hoạt động và chịu sự điều chỉnh của PL do QG A ban hành. Trong tường hợp việc bốc dỡ container hàng chứa xe hơi này vi phạm các quy định về thuế hay hải quan thì quốc gia A có toàn quyền thực hiện các quyền tài phán của QG mình đối với con tàu hàng này."],"a":["è Đối với tàu chở hàng của quốc gia B:","Vì đề bài không cho rõ dữ liệu nên nhóm chia ra các trường hợp sau: - Nếu tàu này không có sự vi phạm các luật hay quy định của quốc gia đó về hải quan, thuế khóa, y tế hay nhập cư trong phạm vi lãnh thổ hay lãnh hải của mình thì quốc gia A không có quyền gì cả.","- Nếu có sự vi phạm các luật hay quy định của quốc gia đó về hải quan, thuế khóa, y tế hay nhập cư thì tùy vào hướng đi của con tàu này mà sẽ giải quyết như sau:"," Tàu này đang đi theo hướng vào vùng lãnh hải thì quốc gia A được quyềntiến hành các biện pháp kiểm soát cần thiết, nhằm ngăn chặn sự vi phạm."," Tàu này đang từ vùng tiếp giáp đi ra vùng biển quốc tế và sự vi phạm này không xảy ra trong phạm vi lãnh thổ hay lãnh hải của quốc gia A thì quốc gia A không được quyền làm gì cả."," Tàu này đi ra vùng biển quốc tế nhưng sự vi phạn này xảy ra trong phạm vi lãnh thổ hay lãnh hải của quốc gia A thì quốc gia A được quyền trừng trị sự vi phạm đó đối với chiếc tàu này.","Cơ sở pháp lý: khoản 1 Điều 33 Công ước của Liên hợp quốc về Luật biển năm 1982.è Đối với tàu hàng của quốc gia A:","Quốc gia A sẽ có đầy đủ các quyền tài phán theo quy định và pháp luật của quốc gia A. Bởi lẽ, đây là tàu hàng của quốc gia A nên phải hoạt động và chịu sự điều chỉnh của pháp luật do quốc gia A ban hành. Trong trường hợp việc bốc dỡ container hàng chứa xe hơi này vi phạm các quy định về thuế hay hải quan thì quốc gia A có toàn quyền thực hiện các quyền tài phán của quốc gia mình đối với con tàu hàng này.","è Đối với chiếc máy bay dân sự cất cánh từ vùng tiếp giáp lãnh hải: Theo nhóm cần chia ra hai trường hợp, nếu chiếc tàu dân sự này cất cánh bay về phía lãnh hải của quốc gia A thì quốc gia A có quyền ngăn chặn không cho phép máy bay trên bay vào bởi lẽ máy bay là phương tiện bay và không được hưởng quyền đi qua không gây hại dành cho tàu biển theo quy định tại Điều 17 Công ước về luật biển 1982 của Liên Hợp quốc. Còn trong trường hợp máy bay này bay ra phía biển quốc tế, thì quốc gia A không có quyền gì đối với máy bay dân sự này."],"q":"Bài tập 3. Tàu chở hàng của quốc gia B khi đi qua vùng tiếp giáp của quốc gia A đã thực hiện các hành vi sau:"},{"qs":["Bài tập 4. Trong vùng đặc quyền kinh tế của quốc gia A, tàu của quốc gia B thực hiện:","a) Đánh bắt hải sản b) Cho máy bay hạ cánh xuống tàu Quốc gia A có quyền gì đối với tàu và máy bay nói trên? CSPL?","a) Đối với tàu của nước B thực hiện việc đánh bắt hải sản trong vùng đặc quyền kinh tế của QG A:","Trong vùng ĐQKT của QG A, tàu của QG B thực hiện đánh bắt hải sản. Có 3 trường hợp sau:","- TH1: Trong trường hợp QG A cho phép tàu của QG B được khai thác đánh bắt số lượng cá dư thông qua các ĐƯQT hoặc các thỏa thuận khác tại Điều 62 UNCLOS 1982 và đồng thời tàu của QG B cugx tuân thủ các biện pháp bảo tồn và các thể thức, các điều kiện khác được đề ra trong các luật và quy định của QG A thì việc tàu của QG B thực hiện đánh bắt hải sản trong vùng ĐQKT của QG A là hợp pháp. QG A có các quyền đối với tàu đánh bắt hải sản của QG B về các vấn đề được quy định tại khoản 4 Điều 62 UNCLOS 1982.","Ví dụ: Vào năm 2000 giữa Chính phủ nước CHXHCN Việt Nam và Chính phủ nước CHDCND Trung Hoa đã ký với nhau “Hiệp định hợp tác nghề cá Vịnh Bắc Bộ”. Qua sáu vòng đàm phán cấp chuyên viên về nghề cá, qua thương lượng, hai bên đã nhất trí hợp tác nghề cá trong vịnh Bắc Bộ bằng việc thiết lập một Vùng đánh cá chung. Phạm vi Vùng đánh cá chung trong vịnh Bắc Bộ từ vĩ tuyến 20° Bắc xuống đường đóng cửa Vịnh, bề rộng là 30,5 hải lý kể từ đường phân định về mỗi phía; có tổng diện tích là 33.500 km², khoảng 27,9% diện tích Vịnh. Thời hạn của Vùng đánh cá chung là 15 năm (12 năm chính thức và ba năm gia hạn).- TH2: đối với trường hợp cả hai nước đều không thỏa thuận hay ký kết các điều ước cho phép khai thác đánh bắt số lượng cá dư ở quốc gia A, thì lúc này việc đánh bắt cá của tàu quốc gia B là trái phép, không hợp pháp, đã xâm phạm đến lợi ích về quản lý khai thác tài nguyên sinh vật của quốc gia A. Do đó, quốc gia A sẽ có các quyền tài phán xử lý hành vi vi phạm theo quy định tại Điều 73 Công ước Liên Hợp Quốc về Luật biển 1982. Quốc gia A có quyền thi hành mọi biện pháp cần thiết, kể cả việc khám xét, kiểm tra, bắt giữ và khởi tố tư pháp để bảo đảm việc tôn trọng các quy định mà họ đã ban hành theo đúng Công ước. Tuy nhiên, cần lưu ý:","+ Khi có sự bảo lãnh hay một bảo đảm đầy đủ khác thì cần thả ngay chiếc tàu bị bắt và trả tự do ngay cho đoàn thủy thủ của chiếc tàu này.","+ Không được áp dụng các hình phạt giam giữ cũng như các hình phạt thân thể khác nếu không có thỏa thuận khác.","+ Phải thông báo ngay cho quốc gia B biết các biện pháp cũng như các chế tài áp dụng đối với hành vi đánh bắt cá trái phép đối với tàu của quốc gia B.","Ví dụ: Giới chức Philippines ngày 17/5/2016 xác nhận vụ bắt giữ hai tàu cá Trung Quốc cùng 25 ngư dân, khi các tàu giả treo cờ Philippines và đánh bắt trộm trong vùng biển nước này.","Cảnh sát biển Philippines phối hợp với Cục Nghề cá và Nguồn lợi thủy sản (BFAR) bắt giữ 2 tàu cá Trung Quốc ở giữa khu vực vùng biển ngoài khơi đảo Babuyan và tỉnh Batanes, phía Bắc Philippines.","Vị trí hai tàu bị bắt gặp có hoạt động đánh bắt trái phép nằm trong vùng đặc quyền kinh tế (EEZ) của Philippines, không phải trong vùng biển tranh chấp ở Biển Đông.","- TH3: Dựa vào vùng có tính chất lịch sử (ngư trường đánh bắt truyền thống). Nếu tàu của quốc gia B đánh bắt cá trong vùng đặc quyền kinh tế của quốc gia A nhưng đây lại là vùng có tính chất lịch sử của quốc gia B và quốc gia B đã có căn cứ chứng minh về vùng nước này thì việc đánh bắt cá của tàu trong trường hợp này là hợp pháp. Bởi lẽ đây là vùng mà ngư dân quốc gia B đã khai thác, sử dụng lâu đời được cộng đồng quốc tế thừa nhận và đồng thời đây là vùng nước mang lại nguồn cung cấp kinh tế rất lớn, chủ yếu cho quốc gia B nên tàu của quốc gia B có quyền đánh bắt cá trên vùng có tính chất lịch sử của quốc gia mình hay còn gọi là ngư trường đánh bắt truyền thống.","VD: Indonesia vốn không phải một bên trong cuộc tranh chấp trên biển Đông, nhưng nước này đã bị kéo vào cuộc, sau khi Bắc Kinh tuyên bố vùng đặc quyền kinh tế gần quần đảo Natuna của Indonesia là một phần trong “ngư trường đánh cá truyền thống” của Trung Quốc và tàu cá Trung Quốc được tự do đánh bắt trong khu vực này.","Tất nhiên, Indonesia không xem vùng đặc quyền kinh tế của mình là “ngư trường truyền thống” của Trung Quốc, luận điệu mà Bắc Kinh thường xuyên lặp lại. Thay vào đó, Jakarta coi hoạt động đánh cá của các nước khác ở khu vực này là trộm cắp.","Bộ trưởng Các vấn đề hàng hải và ngư nghiệp Indonesia đã phát biểu: “Chúng tôi không biết về điều này (như Trung Quốc tuyên bố), chúng tôi không công nhận bất kỳ tuyên bố chủ quyền của bên nào về ngư trường bên trong vùng đặc quyền kinh tế của Indonesia; ngoại trừ một vùng mà chúng tôi đã ký thỏa thuận với Malaysia ở Eo Malacca”.","b) Đối với trường hợp QG B cho máy bay hạ cánh xuống tàu:","Theo quy định tại khoản 1 Điều 58 Công ước Liên hợp quốc về Luật biển (CƯLB 1982), trong vùng đặc quyền kinh tế, tất cả các quốc gia, dù là quốc gia đó có biển hay không có biển thuộc trong những điều kiện, những quy định thích hợp của Công ước đã trù định, được hưởng các quyền tự do hàng hải và hàng không,… nêu ở Điều 87 của Công ước này.","Đối với hành động cho máy bay hạ cánh xuống tàu của quốc gia B đang ở trong vùng đặc quyền kinh tế của quốc gia A thì theo quy định của CƯLB 1982 đã trình bày ở trên, có thể thấy tàu thuyền, máy bay của quốc gia B có quyền được tự do hàng hải và tự do hàng không trong vùng đặc quyền kinh tế của quốc gia A. Tuy nhiên, với dữ kiện đề đưa ra ta có thể chia thành 2 trường hợp và tùy từng trường hợp cụ thể mà quốc gia A có quyền đối với tàu và máy bay của quốc gia B khác nhau:","Thứ nhất, theo quy định của khoản 2 Điều 58 CƯLB 1982 nếu quốc gia B thực hiện quyền tự do hàng hải, hàng không, quyền tự do sử dụng biển thông qua hành động cho hạ cánh máy bay xuống tàu nhằm những mục đích khác nhau nhưng đảm bảo tính hợp pháp về mặt quốc tế gắn liền với việc thực hiện các quyền tự do hàng hải, hàng không của mình trong vùng đặc quyền kinh tế của quốc gia A. Mục đích cho hạ cánh máy bay phải nhằm thực hiện hoạt động thích hợp với các quy tắc, pháp luật quốc tế qui định được áp dụng ở vùng đặc quyền kinh tế, thực hiện hoạt động tự do nhưng trong chừng mực, khuôn khổ cho phép và không mâu thuẫn với phần V của Công ước, phù hợp với các quy định khác của CƯLB 1982, thì máy bay của quốc gia B có quyền tự do hạ cánh xuống tàu của quốc gia mình khi ở trong vùng đặc quyền kinh tế của quốc gia A. Do đó, trong trường hợp này quốc gia A không có quyền đối với hoạt động của tàu và máy bay nói trên.","Thứ hai, tàu thuyền, máy bay của quốc gia B có quyền tự do hàng hải và tự do hàng không trong vùng đặc quyền kinh tế của quốc gia A nhưng tàu thuyền, máy bay của họ thực hiện các hoạt động gắn liền với các quyền này bằng việc cho máy bay hạ cánh xuống tàu nhằm mục đích thực hiện những hoạt động nằm ngoài khuôn khổ được khai thác theo quy định, không phù hợp, vượt quá giới hạn hay mâu thuẫn với phần V cũng như các quy định khác của CƯLB 1982 hoặc vi phạm các qui định pháp luật của quốc gia A đã ban hành theo đúng các quy định của Công ước và không mâu thuẫn với các quy tắc khác của pháp luật quốc tế thì theo khoản 3 Điều 53 CƯLB 1982, quốc gia A có quyền áp dụng pháp luật quốc gia của mình đã ban hành cụ thể, điều chỉnh các hoạt động mà tàu, máy bay nói trên vi phạm (nếu có). Ngoài ra, quốc gia A còn có quyền dùng các quy tắc khác của pháp luật quốc tế để xử lý đối với hành vi vi phạm của tàu và máy bay của quốc gia B đã thực hiện."],"a":["1. Chế độ pháp lý riêng của vùng đặc quyền kinh tế:","Vùng đặc quyền kinh tế là vùng biển nằm ở phía ngoài lãnh hải và tiếp liền với lãnh hải rộng không quá 200 hải lý kể từ đường cơ sở dùng để tính chiều rộng của lãnh hải, và được đặt dưới chế độ pháp lý riêng theo đó các quyền chủ quyền và quyền tài phán của quốc gia ven biển cũng như các quyền và các quyền tự do của quốc gia khác đều do các quy định thích hợp của Công ước điều chỉnh.","Cơ sở pháp lý: Điều 55 Công ước LHQ về Luật biển 1982. Vùng đặc quyền về kinh tế không phải là biển cả mà là một vùng đặc thù sui generic, trong đó quốc gia ven biển thực hiện thẩm quyền riêng biệt của mình nhằm mục đích kinh tế được Công ước của Liên Hợp Quốc về Luật biển năm 1982 quy định. Để xác lập vùng đặc quyền về kinh tế, quốc gia ven biển cần đưa ra tuyên bố về vùng đặc quyền về kinh tế để xác lập quyền của mình.","v Các quyền, quyền tài phán và nghĩa vụ của các quốc gia ven biển trong vùng đặc quyền kinh tế:","Theo Điều 56 Công ước của Liên hợp quốc về luật biển 1982, trong vùng đặc quyền về kinh tế, quốc gia ven biển có:","a) Các quyền thuộc chủ quyền về thăm dò và khai thác, bảo tồn và quản lý các tài nguyên thiên nhiên, sinh vật hoặc không sinh vật, của vùng nước bên trên đáy biển và lòng đất dưới đáy biển, cũng như về những hoạt động khác nhằm thăm dò và khai thác vùng này vì mục đích kinh tế, như việc sản xuất năng lượng từ nước, hải lưu và gió. b) Quyền tài phán theo đúng những quy định thích hợp của Công ước về việc: i. Lắp đặt và sử dụng các đảo nhân tạo, các thiết bị và công trình; ii. Nghiên cứu khoa học về biển; iii. Bảo vệ và gìn giữ môi trường biển; c) Các quyền và nghĩa vụ khác do Công ước quy định. Đồng thời, trong vùng đặc quyền kinh tế, các quốc gia khác đều được hưởng quyền tự do hàng hải, hàng không, quyền tự do đặt dây cáp và ống dẫn ngầm cũng như quyền tự do sử dụng biển vào các mục đích khác hợp pháp về mặt quốc tế và gắn liền với việc thực hiện các quyền tự do này và phù hợp với các quy định khác của Công ước (Điều 58 Công ước Liên Hợp Quốc về Luật biển 1982).","2. Giải quyết tình huống pháp lý: a) Tàu của nước B thực hiện việc đánh bắt hải sản trong vùng đặc quyền kinh tế của nước A.","Trong vùng đặc quyền kinh tế của quốc gia A, tàu của quốc gia B thực hiện đánh bắt hải sản. Vậy quốc gia A có quyền gì đối với tàu của quốc gia B hay không? Để giải quyết tình huống này nhóm xin đặt ra 3 trường hợp sau:","Thứ nhất, trong trường hợp quốc gia A cho phép tàu của quốc gia B được khai thác đánh bắt số lượng cá dư thông qua các điều ước hoặc các thỏa thuận khác tại Điều 62 của Công ước Liên Hợp Quốc về Luật biển 1982 và đồng thời tàu của quốc gia B cũng đã tuân thủ các biện pháp bảo tồn và các thể thức, các điều kiện khác được đề ra trong các luật và quy định của quốc gia A thì việc tàu quốc gia B thực hiện đánh bắt hải sản trong vùng đặc quyền kinh tế của quốc gia A là hợp pháp. Quốc gia A có các quyền đối với tàu đánh bắt hải sản của quốc gia B về các vấn đề được quy định tại Khoản 4 Điều 62 Công ước LHQ về Luật biển 1982.","Ví dụ: Vào năm 2000 giữa Chính phủ nước CHXHCN Việt Nam và Chính phủ nước CHDCND Trung Hoa đã ký với nhau “Hiệp định hợp tác nghề cá Vịnh Bắc Bộ”. Qua sáu vòng đàm phán cấp chuyên viên về nghề cá, qua thương lượng, hai bên đã nhất trí hợp tác nghề cá trong vịnh Bắc Bộ bằng việc thiết lập một Vùng đánh cá chung. Phạm vi Vùng đánh cá chung trong vịnh Bắc Bộ từ vĩ tuyến 20° Bắc xuống đường đóng cửa Vịnh, bề rộng là 30,5 hải lý kể từ đường phân định về mỗi phía; có tổng diện tích là 33.500 km², khoảng 27,9% diện tích Vịnh. Thời hạn của Vùng đánh cá chung là 15 năm (12 năm chính thức và ba năm gia hạn).","Thứ hai, đối với trường hợp cả hai nước đều không thỏa thuận hay ký kết các điều ước cho phép khai thác đánh bắt số lượng cá dư ở quốc gia A, thì lúc này việc đánh bắt cá của tàu quốc gia B là trái phép, không hợp pháp, đã xâm phạm đến lợi ích về quản lý khai thác tài nguyên sinh vật của quốc gia A. Do đó, quốc gia A sẽ có các quyền tài phán xử lý hành vi vi phạm theo quy định tại Điều 73 Công ước Liên Hợp Quốc về Luật biển 1982. Quốc gia A có quyền thi hành mọi biện pháp cần thiết, kể cả việc khám xét, kiểm tra, bắt giữ và khởi tố tư pháp để bảo đảm việc tôn trọng các quy định mà họ đã ban hành theo đúng Công ước. Tuy nhiên, cần lưu ý:","- Khi có sự bảo lãnh hay một bảo đảm đầy đủ khác thì cần thả ngay chiếc tàu bị bắt và trả tự do ngay cho đoàn thủy thủ của chiếc tàu này.","- Không được áp dụng các hình phạt giam giữ cũng như các hình phạt thân thể khác nếu không có thỏa thuận khác.","- Phải thông báo ngay cho quốc gia B biết các biện pháp cũng như các chế tài áp dụng đối với hành vi đánh bắt cá trái phép đối với tàu của quốc gia B.","Ví dụ: Giới chức Philippines ngày 17/5/2016 xác nhận vụ bắt giữ hai tàu cá Trung Quốc cùng 25 ngư dân, khi các tàu giả treo cờ Philippines và đánh bắt trộm trong vùng biển nước này.","Cảnh sát biển Philippines phối hợp với Cục Nghề cá và Nguồn lợi thủy sản (BFAR) bắt giữ 2 tàu cá Trung Quốc ở giữa khu vực vùng biển ngoài khơi đảo Babuyan và tỉnh Batanes, phía Bắc Philippines.","Vị trí hai tàu bị bắt gặp có hoạt động đánh bắt trái phép nằm trong vùng đặc quyền kinh tế (EEZ) của Philippines, không phải trong vùng biển tranh chấp ở Biển Đông.Thứ ba, dựa vào vùng có tính chất lịch sử (ngư trường đánh bắt truyền thống). Nếu tàu của quốc gia B đánh bắt cá trong vùng đặc quyền kinh tế của quốc gia A nhưng đây lại là vùng có tính chất lịch sử của quốc gia B và quốc gia B đã có căn cứ chứng minh về vùng nước này thì việc đánh bắt cá của tàu trong trường hợp này là hợp pháp. Bởi lẽ đây là vùng mà ngư dân quốc gia B đã khai thác, sử dụng lâu đời được cộng đồng quốc tế thừa nhận và đồng thời đây là vùng nước mang lại nguồn cung cấp kinh tế rất lớn, chủ yếu cho quốc gia B nên tàu của quốc gia B có quyền đánh bắt cá trên vùng có tính chất lịch sử của quốc gia mình hay còn gọi là ngư trường đánh bắt truyền thống.","Ví dụ: Indonesia vốn không phải một bên trong cuộc tranh chấp trên biển Đông, nhưng nước này đã bị kéo vào cuộc, sau khi Bắc Kinh tuyên bố vùng đặc quyền kinh tế gần quần đảo Natuna của Indonesia là một phần trong “ngư trường đánh cá truyền thống” của Trung Quốc và tàu cá Trung Quốc được tự do đánh bắt trong khu vực này.","Tất nhiên, Indonesia không xem vùng đặc quyền kinh tế của mình là “ngư trường truyền thống” của Trung Quốc, luận điệu mà Bắc Kinh thường xuyên lặp lại. Thay vào đó, Jakarta coi hoạt động đánh cá của các nước khác ở khu vực này là trộm cắp.","Bộ trưởng Các vấn đề hàng hải và ngư nghiệp Indonesia đã phát biểu: “Chúng tôi không biết về điều này (như Trung Quốc tuyên bố), chúng tôi không công nhận bất kỳ tuyên bố chủ quyền của bên nào về ngư trường bên trong vùng đặc quyền kinh tế của Indonesia; ngoại trừ một vùng mà chúng tôi đã ký thỏa thuận với Malaysia ở Eo Malacca”.","b) Quốc gia B cho máy bay hạ cánh xuống tàu. Theo quy định tại khoản 1 Điều 58 Công ước Liên hợp quốc về Luật biển (CƯLB 1982), trong vùng đặc quyền kinh tế, tất cả các quốc gia, dù là quốc gia đó có biển hay không có biển thuộc trong những điều kiện, những quy định thích hợp của Công ước đã trù định, được hưởng các quyền tự do hàng hải và hàng không,… nêu ở Điều 87 của Công ước này.","Đối với hành động cho máy bay hạ cánh xuống tàu của quốc gia B đang ở trong vùng đặc quyền kinh tế của quốc gia A thì theo quy định của CƯLB 1982 đã trình bày ở trên, có thể thấy tàu thuyền, máy bay của quốc gia B có quyền được tự do hàng hải và tự do hàng không trong vùng đặc quyền kinh tế của quốc gia A. Tuy nhiên, với dữ kiện đề đưa ra ta có thể chia thành 2 trường hợp và tùy từng trường hợp cụ thể mà quốc gia A có quyền đối với tàu và máy bay của quốc gia B khác nhau:","Thứ nhất, theo quy định của khoản 2 Điều 58 CƯLB 1982 nếu quốc gia B thực hiện quyền tự do hàng hải, hàng không, quyền tự do sử dụng biển thông qua hành động cho hạ cánh máy bay xuống tàu nhằm những mục đích khác nhau nhưng đảm bảo tính hợp pháp về mặt quốc tế gắn liền với việc thực hiện các quyền tự do hàng hải, hàng không của mình trong vùng đặc quyền kinh tế của quốc gia A. Mục đích cho hạ cánh máy bay phải nhằm thực hiện hoạt động thích hợp với các quy tắc, pháp luật quốc tế qui định được áp dụng ở vùng đặc quyền kinh tế, thực hiện hoạt động tự do nhưng trong chừng mực, khuôn khổ cho phép và không mâu thuẫn với phần V của Công ước, phù hợp với các quy định khác của CƯLB 1982, thì máy bay của quốc gia B có quyền tự do hạ cánh xuống tàu của quốc gia mình khi ở trong vùng đặc quyền kinh tế của quốc gia A. Do đó, trong trường hợp này quốc gia A không có quyền đối với hoạt động của tàu và máy bay nói trên.","Thứ hai, tàu thuyền, máy bay của quốc gia B có quyền tự do hàng hải và tự do hàng không trong vùng đặc quyền kinh tế của quốc gia A nhưng tàu thuyền, máy bay của họ thực hiện các hoạt động gắn liền với các quyền này bằng việc cho máy bay hạ cánh xuống tàu nhằm mục đích thực hiện những hoạt động nằm ngoài khuôn khổ được khai thác theo quy định, không phù hợp, vượt quá giới hạn hay mâu thuẫn với phần V cũng như các quy định khác của CƯLB 1982 hoặc vi phạm các qui định pháp luật của quốc gia A đã ban hành theo đúng các quy định của Công ước và không mâu thuẫn với các quy tắc khác của pháp luật quốc tế thì theo khoản 3 Điều 53 CƯLB 1982, quốc gia A có quyền áp dụng pháp luật quốc gia của mình đã ban hành cụ thể, điều chỉnh các hoạt động mà tàu, máy bay nói trên vi phạm (nếu có). Ngoài ra, quốc gia A còn có quyền dùng các quy tắc khác của pháp luật quốc tế để xử lý đối với hành vi vi phạm của tàu và máy bay của quốc gia B đã thực hiện.","Ví dụ: Malaysia bị sốc trước hai đợt tập trận trong vòng chưa đầy một năm của hải quân Trung Quốc gần bãi cạn James nằm trong vùng đặc quyền kinh tế của mình. Bắc Kinh xem bãi cạn James là phần lãnh thổ cực Nam của nước này. Tháng 3/2013, Malaysia từng phản đối 4 tàu Trung Quốc xâm nhập James. Các thủy thủ Trung Quốc đã bắn chỉ thiên khi ghé vào bãi cạn này. Sau đó, tháng 4/2013, 1 tàu hải giám Trung Quốc quay lại bãi cạn James và đặt ở đó những cột bằng thép đánh dấu chủ quyền.","Quan chức ngoại giao của Malaysia cho biết, vụ việc hải quân Trung Quốc tập trận gần bãi cạn James khiến Malaysia quyết định thúc đẩy hợp tác với các quốc gia khác trong ASEAN, nhằm khiến Trung Quốc phải tuân thủ quy tắc ứng xử trên biển Đông. Những tuyên bố chủ quyền của Trung Quốc trên biển Đông cũng có thể đẩy Malaysia xích lại gần Mỹ hơn. Trước đó, Malaysia thường hạ nhiệt các lo ngại về an ninh nhằm theo đuổi quan hệ kinh tế thân thiết hơn với đối tác thương mại lớn, nhất là Trung Quốc."],"q":"Bài tập 4. Trong vùng đặc quyền kinh tế của quốc gia A, tàu của quốc gia B thực hiện:"},{"qs":["Bài tập 5. Quốc gia A tiến hành khai thác dầu khí trong khu vực cách đường cơ sở dùng để tính chiều rộng lãnh hải 280 hải lý. Anh/chị hãy cho biết:","a) Quốc gia A có quyền nêu trên không? Điều kiện? CSPL? b) Nghĩa vụ của QG A trong trường hợp này?","Giả sử QG A có biển sâu. Vì vậy, quốc gia A chỉ áp dụng đường cơ sở để xác định chiều rô ̣ng của thềm lục địa trong trường hợp bờ ngoài của rìa lục địa vượt quá 200 hải lý tính từ đường cơ sở (không áp dụng đường đẳng sâu 2.500m để xác định chiều rô ̣ng của thềm lục địa).","Quốc gia A sẽ có quyền khai thác dầu khí trong khu vực cách đường cơ sở dùng để tính chiều rô ̣ng của lãnh hải 280 hải lý trong hai (02) trường hợp sau:","(1)Trường hợp 1: Bờ ngoài của rìa lục địa quốc gia A nhỏ hơn 280 hải lý kể từ đường cơ sở dùng để tính chiều rộng lãnh hải.","Trong trường hợp này, khu vực cách đường cơ sở dùng để tính chiều rô ̣ng của lãnh hải 280 hải lý này sẽ nằm bên ngoài thềm lục địa của quốc gia A và thuô ̣c phần Biển quốc tế và Vùng (Đáy đại dương). Theo khoản 1 Điều 1 Công ước của Liên Hiê ̣p Quốc về Luâ ̣t biển 1982 thì “vùng (zone) là toàn bô ̣ đáy biển và lòng đất dưới đáy biển nằm bên ngoài giới hạn quyền tài phán của quốc gia”. Như vâ ̣y, viê ̣c quốc gia A tiến hành viê ̣c khai thác dầu khí tại khu vực 280 hải lý tức là quốc gia A đang tiến hành khai thác dầu khí tại phần Vùng (Đáy đại dương).","Mà căn cứ theo quy định tại Điều 136 và khoản 1 Điều 137 Công ước của Liên Hiê ̣p Quốc về Luâ ̣t biển 1982 thì vùng (đáy đại dương) và tài nguyên của nó là di sản chung của nhân loại và không một quốc gia nào có quyền đòi hỏi chủ quyền hay các quyền chủ quyền ở đáy biển quốc tế, kể cả tài nguyên ở đó.","Vâ ̣y nên quốc gia A không có quyền khai thác dầu khí tại khu vực này như mô ̣t quyền thuô ̣c quyền chủ quyền của mình.","Tuy nhiên, quốc gia A vẫn có thể tiến hành khai thác dầu khí tại khu vực này nhưng không được thực hiê ̣n mô ̣t cách tự do mà phải được tổ chức mô ̣t cách có hiê ̣u quả; phải tuân theo pháp luâ ̣t, tâ ̣p quán quốc tế và phải đă ̣t dưới sự điều hành, kiểm soát của Cơ quan quyền lực quốc tế về đáy biển (khoản 2 Điều 1 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982). Đây là mô ̣t tổ chức quốc tế liên chính phủ, được thành lâ ̣p theo phần XI của Công ước của Liên Hợp Quốc về Luật Biển 1982, nhằm mục đích bảo đảm viê ̣c phân chia công bằng, trên cơ sở không phân biê ̣t đối xử những lợi ích tài chính và những lợi ích kinh tế khác do những hoạt đô ̣ng tiến hành trong Vùng thông qua bô ̣ máy của mình. Cơ quan quyền lực quốc tế về đáy biển có quyền tự quyết định khai thác hoă ̣c cho các nước khai thác theo điều kiê ̣n do cơ quan đó quyết định.","Nghĩa vụ của quốc gia A trong trường hợp này:","– Trước hết, vùng phải được sử dụng nhằm mục đích hoà bình và an ninh quốc tế, vì lợi ích thúc đẩy sự hợp tác quốc tế.","– Bên cạnh đó, hoạt đô ̣ng khai thác dầu khí của quốc gia A ở vùng phải được tiến hành vì mục đích:","+ Phục vụ toàn thể loài người (Điều 140 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982);","+ Mang lại lợi ích cho tất cả các quốc gia trên thế giới, không phân biê ̣t vị trí địa lý, nước có biển hay không có biển (Điều 141 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982);","+ Đă ̣c biê ̣t chú ý đến nhu cầu của các nước đang phát triển (Điều 148 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982).","– Quốc gia A phải tôn trọng đầy đủ các quyền lợi chính đáng của quốc gia ven biển (Điều 142 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982).","– Các hiê ̣n vâ ̣t có tính chất cổ và lịch sử tìm thấy trong vùng sẽ được bảo tồn và định đoạt vì lợi ích của toàn thể loài người (Điều 149 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982).","– Quốc gia A phải tuân thủ các quy định tại Mục 3, Phần IX Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982 về khai thác các tài nguyên của vùng.","(2)Trường hợp 2: Bờ ngoài của rìa lục địa quốc gia A lớn hơn hoặc bằng 280 hải lý kể từ đường cở sở dùng để tính chiều rộng lãnh hải.","Trong trường hợp này, vùng thềm lục địa pháp lý của quốc gia A có thể sẽ nằm trong phạm vi 280 hải lý đến tối đa 350 hải lý kể từ đường cơ sở dùng để tính chiều rô ̣ng lãnh hải (Điều 76 Công ước của Liên Hiê ̣p Quốc về Luâ ̣t biển 1982). Như vâ ̣y, viê ̣c quốc gia A tiến hành khai thác dầu khí trong khu vực cách đường cơ sở dùng để tính chiều rô ̣ng của lãnh hải 280 hải lý này được thực hiê ̣n trong khu vực thềm lục địa của quốc gia A.","Do đó, quốc gia A có quyền khai thác dầu khí trong khu vực này bởi vì quốc gia ven biển được thực hiện các quyền chủ quyền đối với thềm lục địa của mình về mặt thăm dò và khai thác tài nguyên thiên nhiên (khoáng sản, tài nguyên không sinh vật như dầu khí, các tài nguyên sinh vật như cá, tôm…) của mình. Vì đây là đặc quyền của quốc gia A nên không ai có quyền tiến hành các hoạt động như vậy nếu không có sự thỏa thuận với quốc gia A. Nghĩa là chỉ quốc gia A mới có quyền cho phép và quy định việc khoan ở thềm lục địa bất kỳ vào mục đích gì. Tuy nhiên, quốc gia A khi thực hiện quyền đối với thềm lục địa của mình không được đụng chạm đến chế độ pháp lý của vùng nước phía trên, không được gây thiệt hại đến hàng hải hay các quyền tự do của các quốc gia khác.","– Cơ sở pháp lý: Điều 77 Công ước của Liên Hiệp Quốc về Luật biển 1982.","Nghĩa vụ của quốc gia A trong trường hợp này:","+ Thông báo những thông tin về ranh giới các thềm lục địa của mình khi thềm lục địa mở rộng quá 200 hải lý tính từ đường cơ sở dùng để tính chiều rộng lãnh hải cho Ủy ban ranh giới thềm lục địa (Khoản 8 Điều 76 Công ước Liên Hiệp Quốc về Luật biển 1982);","+ Gửi cho Tổng thư ký Liên Hiệp Quốc các tài liệu cần thiết để chỉ rõ một cách thường xuyên thềm lục địa của mình (Khoản 9 Điều 76 Công ước Liên Hiệp Quốc về Luật biển 1982);","+ Không cản trở chế độ pháp lý của vùng nước phía trên và vùng trời phía trong vùng nước đó (Điều 78 Công ước Liên Hiệp Quốc về Luật biển 1982);","+ Không cản trở quốc gia khác đặt dây cáp ngầm và ống dẫn ngầm trên thềm lục địa (Điều 79 Công ước Liên Hiệp Quốc về Luật biển 1982);","+ Do quốc gia A tiến hành khai thác thềm lục địa ngoài 200 hải lý kể từ đường cơ sở nên A phải nộp một khoản đóng góp bằng tiền hay hiện vật về việc khai thác tài nguyên thiên nhiên không sinh vật (Điều 82 Công ước Liên Hiệp Quốc về Luật biển 1982)."],"a":["Giả sử quốc gia A có biển sâu. Vì vậy, quốc gia A chỉ áp dụng đường cơ sở để xác định chiều rô ̣ng của thềm lục địa trong trường hợp bờ ngoài của rìa lục địa vượt quá 200 hải lý tính từ đường cơ sở (không áp dụng đường đẳng sâu 2.500m để xác định chiều rô ̣ng của thềm lục địa).","Quốc gia A sẽ có quyền khai thác dầu khí trong khu vực cách đường cơ sở dùng để tính chiều rô ̣ng của lãnh hải 280 hải lý trong hai (02) trường hợp sau:","(1)Trường hợp 1: Bờ ngoài của rìa lục địa quốc gia A nhỏ hơn 280 hải lý kể từ đường cơ sở dùng để tính chiều rộng lãnh hải.","- Trong trường hợp này, khu vực cách đường cơ sở dùng để tính chiều rô ̣ng của lãnh hải 280 hải lý này sẽ nằm bên ngoài thềm lục địa của quốc gia A và thuộc phần Biển quốc tế và Vùng (Đáy đại dương). Theo khoản 1 Điều 1 Công ước của Liên Hiê ̣p Quốc về Luâ ̣t biển 1982 thì “vùng (zone) là toàn bô ̣ đáy biển và lòng đất dưới đáy biển nằm bên ngoài giới hạn quyền tài phán của quốc gia”. Như vâ ̣y, viê ̣c quốc gia A tiến hành viê ̣c khai thác dầu khí tại khu vực 280 hải lý tức là quốc gia A đang tiến hành khai thác dầu khí tại phần Vùng (Đáy đại dương). Mà căn cứ theo quy định tại Điều 136 và khoản 1 Điều 137 Công ước của Liên Hiê ̣p Quốc về Luâ ̣t biển 1982 thì vùng (đáy đại dương) và tài nguyên của nó là di sản chung của nhân loại và không một quốc gia nào có quyền đòi hỏi chủ quyền hay các quyền chủ quyền ở đáy biển quốc tế, kể cả tài nguyên ở đó.","è Vâ ̣y nên quốc gia A không có quyền khai thác dầu khí tại khu vực này như mô ̣t quyền thuô ̣c quyền chủ quyền của mình.","è Tuy nhiên, quốc gia A vẫn có thể tiến hành khai thác dầu khí tại khu vực này nhưng không được thực hiê ̣n một cách tự do mà phải được tổ chức một cách có hiê ̣u quả; phải tuân theo pháp luâ ̣t, tâ ̣p quán quốc tế và phải đă ̣t dưới sự điều hành, kiểm soát của Cơ quan quyền lực quốc tế về đáy biển (khoản 2 Điều 1 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982). Đây là mô ̣t tổ chức quốc tế liên chính phủ, được thành lập theo phần XI của Công ước của Liên Hợp Quốc về Luật Biển 1982, nhằm mục đích bảo đảm viê ̣c phân chia công bằng, trên cơ sở không phân biê ̣t đối xử những lợi ích tài chính và những lợi ích kinh tế khác do những hoạt động tiến hành trong Vùng thông qua bô ̣ máy của mình. Cơ quan quyền lực quốc tế về đáy biển có quyền tự quyết định khai thác hoă ̣c cho các nước khai thác theo điều kiê ̣n do cơ quan đó quyết định."," Nghĩa vụ của quốc gia A trong trường hợp này: - Trước hết, vùng phải được sử dụng nhằm mục đích hoà bình và an ninh quốc tế, vì lợi ích thúc đẩy sự hợp tác quốc tế.","- Bên cạnh đó, hoạt động khai thác dầu khí của quốc gia A ở vùng phải được tiến hành vì mục đích:","+ Phục vụ toàn thể loài người (Điều 140 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982);","+ Mang lại lợi ích cho tất cả các quốc gia trên thế giới, không phân biê ̣t vị trí địa lý, nước có biển hay không có biển (Điều 141 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982);","+ Đă ̣c biê ̣t chú ý đến nhu cầu của các nước đang phát triển (Điều 148 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982).","- Quốc gia A phải tôn trọng đầy đủ các quyền lợi chính đáng của quốc gia ven biển (Điều 142 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982).","- Các hiê ̣n vâ ̣t có tính chất cổ và lịch sử tìm thấy trong vùng sẽ được bảo tồn và định đoạt vì lợi ích của toàn thể loài người (Điều 149 Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982).","- Quốc gia A phải tuân thủ các quy định tại Mục 3, Phần IX Công ước của Liên Hợp Quốc về Luâ ̣t biển 1982 về khai thác các tài nguyên của vùng.","(2)Trường hợp 2 : Bờ ngoài của rìa lục địa quốc gia A lớn hơn hoặc bằng 280 hải lý kể từ đường cở sở dùng để tính chiều rộng lãnh hải.","- Trong trường hợp này, vùng thềm lục địa pháp lý của quốc gia A có thể sẽ nằm trong phạm vi 280 hải lý đến tối đa 350 hải lý kể từ đường cơ sở dùng để tính chiều rộng lãnh hải (Điều 76 Công ước của Liên Hiê ̣p Quốc về Luâ ̣t biển 1982). Như vâ ̣y, viê ̣c quốc gia A tiến hành khai thác dầu khí trong khu vực cách đường cơ sở dùng để tính chiều rộng của lãnh hải 280 hải lý này được thực hiê ̣n trong khu vực thềm lục địa của quốc gia A.","è Do đó, quốc gia A có quyền khai thác dầu khí trong khu vực này bởi vì quốc gia ven biển được thực hiện các quyền chủ quyền đối với thềm lục địa của mình về mặt thăm dò và khai thác tài nguyên thiên nhiên (khoáng sản, tài nguyên không sinh vật như dầu khí, các tài nguyên sinh vật như cá, tôm…) của mình. Vì đây là đặc quyền của quốc gia A nên không ai có quyền tiến hành các hoạt động như vậy nếu không có sự thỏa thuận với quốc gia A. Nghĩa là chỉ quốc gia A mới có quyền cho phép và quy định việc khoan ở thềm lục địa bất kỳ vào mục đích gì. Tuy nhiên, quốc gia A khi thực hiện quyền đối với thềm lục địa của mình không được đụng chạm đến chế độ pháp lý của vùng nước phía trên, không được gây thiệt hại đến hàng hải hay các quyền tự do của các quốc gia khác.","- Cơ sở pháp lý: Điều 77 Công ước của Liên Hiệp Quốc về Luật biển 1982.  Nghĩa vụ của quốc gia A trong trường hợp này: - Thông báo những thông tin về ranh giới các thềm lục địa của mình khi thềm lục địa mở rộng quá 200 hải lý tính từ đường cơ sở dùng để tính chiều rộng lãnh hải cho Ủy ban ranh giới thềm lục địa (Khoản 8 Điều 76 Công ước Liên Hiệp Quốc về Luật biển 1982);","- Gửi cho Tổng thư ký Liên Hiệp Quốc các tài liệu cần thiết để chỉ rõ một cách thường xuyên thềm lục địa của mình (Khoản 9 Điều 76 Công ước Liên Hiệp Quốc về Luật biển 1982);","- Không cản trở chế độ pháp lý của vùng nước phía trên và vùng trời phía trong vùng nước đó (Điều 78 Công ước Liên Hiệp Quốc về Luật biển 1982);","- Không cản trở quốc gia khác đặt dây cáp ngầm và ống dẫn ngầm trên thềm lục địa (Điều 79 Công ước Liên Hiệp Quốc về Luật biển 1982);","- Do quốc gia A tiến hành khai thác thềm lục địa ngoài 200 hải lý kể từ đường cơ sở nên A phải nộp một khoản đóng góp bằng tiền hay hiện vật về việc khai thác tài nguyên thiên nhiên không sinh vật (Điều 82 Công ước Liên Hiệp Quốc về Luật biển 1982)."],"q":"Bài tập 5. Quốc gia A tiến hành khai thác dầu khí trong khu vực cách đường cơ sở dùng để tính chiều rộng lãnh hải 280 hải lý. Anh/chị hãy ch"},{"qs":["Bài tập 6. Tàu quân sự của quốc gia B đi qua lãnh hải (không vào nội thủy của QG A. Anh/chị hãy cho biết:","a) Tàu quân sự của quốc gia B có cần phải xin phép quốc gia A? CSPL? b) Tàu quân sự của quốc gia B có cần phải thông báo trước cho QG A? CSPL? c) Nếu QG A là VN, Luật biển VN 2012 quy định về vấn đề này như thế nào?","CSPL? Đánh giá và nhận xét dưới góc độ Luật quốc tế?","Tàu quân sự của QG B đi qua lãnh hải (không vào nội thủy) của quốc gia A. Việc chỉ trình bày việc đi qua (passage) theo điểm a khoản 1 Điều 18 UNCLOS 1982, chưa thể xác định được cơ chế pháp lý được áp dụng với tàu quân sự của quốc gia B này khi xâm nhập lãnh hải của quốc gia ven biển, do đó để giải quyết cần thiết việc chia trường hợp là đi qua không gây hại hay đi qua gây hai.","Trường hợp 1: đi qua không gây hại.","a) Tàu quân sự của nước a được phép đi qua lãnh hải mà không cần xin phép vì đây là quyền được đi qua không gây hại mà bất kỳ tàu biển nào cũng được hưởng theo Điều 17 UNCLOS 1982, quốc gia ven biển có trách nhiệm tạo điều kiện cho tàu biển được thực hiện quyền này theo khoản 1 Điều 24 Công ước này. Tuy nhiên, Tàu quân sự nước B phải thông báo cho A và phải tuân thủ các luật và quy định của Luật biển. b) Việc tàu quân sự của quốc gia B đi qua lãnh hải của quốc gia A cần phải thông báo trước cho quốc gia A và phải tuân theo nguyên tắc đi qua không gây hại trong lãnh hải theo tiểu mục A, Mục 3 Công ước Viên Luật biển 1982.","Tuy không có quy định cụ thể nào trong Công ước viên của Liên Hợp Quốc về Luật biển 1982 quy định về việc tàu quân sự nước ngoài phải thông báo trước cho quốc gia ven biển được biết về việc tàu quân sự nước ngoài đi vào lãnh hải của quốc gia mình. Nhưng xét thấy các quy định trong Công ước đã gợi mở cho các quốc gia ven biển có quyền thiết lập các biện pháp cần thiết nhằm ngăn cản mọi việc đi qua có gây hại, được biểu đạt qua các lập luận sau:","(i) Theo Điều 19 (Nghĩa của thuật ngữ đi qua không gây hại) và Điều 25 (Quyền bảo vệ của quốc gia ven biển), Quốc gia ven biển có quyền thi hành các biện pháp cần thiết để bảo vệ lợi ích an ninh quốc gia, điều này sẽ bao gồm cả việc yêu cầu tàu quân sự nước ngoài phải tiến hành thông báo trước khi vào lãnh hải của quốc gia đó. Khoản 1 Điều 25 quy định rằng quốc gia ven biển có thể thi hành các biện pháp cần thiết trong lãnh hải của mình để ngăn cản mọi việc đi qua gây hại. Khoản 3 Điều 25 cho phép quốc gia ven biển đình chỉ thực hiện việc đi qua không gây hại của tàu thuyền nước ngoài tại các khu vực nhất định trong lãnh hải của mình, nếu biện pháp này là cần thiết để bảo đảm an ninh.","(ii) Các quy định tại Điều 30 Công ước Luật biển 1982 liên quan đến việc tàu chiến không tuân thủ các luật và quy định của quốc gia ven biển khi đi qua lãnh hải, cho phép quốc gia ven biển được xây dựng các luật lệ về lãnh hải. Do đó, các quốc gia này có thể đưa ra những quy định bắt buộc tàu quân sự phải xin phép hoặc thông báo trước khi vào lãnh hải trong luật lệ của mình.","(iii) Hơn nữa, Lãnh hải luôn là một phần lãnh thổ của quốc gia ven biển và thuộc chủ quyền của quốc gia. Vì vậy, theo nguyên tắc bảo đảm sự toàn vẹn lãnh thổ và bảo vệ chủ quyền, an ninh quốc gia, quốc gia ven biển được phép áp dụng các quy định trên.","c) Dựa vào khoản 2 Điều 12 Luâ ̣t Biển Viê ̣t Nam 2012quy định: “Đối với tàu quân sự nước ngoài khi thực hiện quyền đi qua không gây hại trong lãnh hải Việt Nam, thông báo trước cho cơ quan có thẩm quyền của Việt Nam”. Chính vì thế khi tàu quân sự nước B đi qua lãnh hải của Việt Nam phải có nghĩa vụ thông báo cho cơ quan quản lý nhà nước có thẩm quyền của Việt Nam.","Nhìn nhận quy định phải thông báo đối với hành vi đi qua không gây hại của tàu quân sự dưới lăng kính của luật quốc tế, thì nhiều người có thể đánh giá rằng quy định này vi phạm nguyên tắc tận tâm thực hiện các điều ước quốc tế đã ký kết, bởi theo quy định tại Điều 17 đây là quyền của tất cả các tàu thuyền, hơn nữa không có một quy chế cụ thể nào trong Công ước ràng buộc để quốc gia ven biển có thể hạn chế quyền đi qua không gây hại như yêu cầu phải xin phép, thông báo. Tuy nhiên nhóm cho rằng đánh giá như trên là không thuyết phục, và quy định của Điều 12 Luật biển Việt Nam hợp lý, tuân thủ Công ước:","Một là, lãnh hải là một phần lãnh thổ của quốc gia ven biển và thuộc chủ quyền của quốc gia. Vì vậy, theo nguyên tắc bảo đảm sự toàn vẹn lãnh thổ và bảo vệ chủ quyền, an ninh quốc gia, quốc gia ven biển được phép áp dụng.","Hai là, tại khoản 1 Điều 19 Công ước quy định “không làm phương hại đến hòa bình trật tự và an ninh của quốc gia viên biển”. Việc tàu quân sự đi qua lãnh thổ một quốc gia dù ít hay nhiều cũng hàm chứa những rủi ro nhất định, nên việc yêu cầu thông báo, như là một sự chuẩn bị sự phòng vệ của quốc gia quen biển, Ba là, pháp luật Việt Nam chỉ quy định là phải “thông báo”, việc thông báo này không hạn chế quyền đi qua không gây hại, mà nó gần giống như một thủ tục báo trước đối với Việt Nam.","Bốn là, các quy định tại Điều 30 Công ước Luật biển 1982 liên quan đến việc tàu chiến không tuân thủ các luật và quy định của quốc gia ven biển khi đi qua lãnh hải, cho phép quốc gia ven biển được xây dựng các luật lệ về lãnh hải. Do đó, các quốc gia này có thể đưa ra những quy định bắt buộc tàu quân sự phải xin phép hoặc thông báo trước khi vào lãnh hải trong luật lệ của mình.","Cuối cùng, quy định này không chỉ được Việt Nam áp dụng, mà nó còn được cái nước áp dụng một cách rộng rãi, và dần trở thành một “nguyên tắc” trong quy chế đi qua không gây hại của tàu quân sự trong lãnh hải quốc gia. Điển hình như đối với một số các quốc gia như Croatia, Egypt, Finland, Guyana, India, South Korea, Libya, Malta, Mauritius, và Serbia phải tiến hành thủ tục thông báo trước.","Trường hợp hai: đi qua gây hại.","Đây là trường hợp tàu quân sự quốc gia B mặc dù đi qua lãnh hải không vào nội thủy, đi liên tục hành chóng nhưng có một hoặc một số hoạt động quy định tại khoản 2 điều 19 UNCLOS.","a) Tàu quân sự này bắt buộc phải xin phép quốc gia ven biển, trừ trường hợp quốc gia có tàu quân sự và quốc gia ven biển có thỏa thuận khác, bởi đây là lãnh thổ của quốc gia ven biển, quốc gia ven biển có chủ quyền hoàn toàn và đầy đủ. Tàu quân sự có những hoạt động gây hại không được hưởng các quyền được quy định tại Điều 17. Phải xin phép và tuân thủ các quy định pháp luật của quốc gia ven biển, chịu một số hạn chế nhất định. Mặc khác theo quy định tại khoản 1 Điều 25 UNCLOS “quốc gia ven biển có thể thi hành các biện pháp cần thiết trong lãnh hải của mình để ngăn chặn mọi việc đi qua có hại”. Đối với các trường hợp đi qua gây hại, thì thường các quốc gia quen biển sẽ không cho phép hành vi này diễn ra trên lãnh hải quốc gia mình. b) Trong Công ước không có quy định cụ thể về việc thông báo, tuy nhiên có thể căn cứ theo điều 25, quốc gia ven biển có thể yêu cầu tàu quân sự đi qua gây hại có thể thông báo hoặc không thông báo, tuy nhiên trước đó vẫn phải thực hiện nghĩa vụ xin phép, trừ trường hợp hai quốc gia có thỏa thuận khác. c) Trước hết là pháp luật Việt Nam không có quy định trực tiếp về giải quyết việc đi qua gây hại. Tuy nhiên, căn cứ vào Luật biển Việt Nam quy “Nhà nước thực hiện chủ quyền đầy đủ và toàn vẹn đối với lãnh hải”. Nên đối với tàu quân sự phải được sự cho phép của Việt Nam mới được đi qua lãnh hải, và có thể áp dụng các quy định về chế độ pháp lý về biên giới quốc gia trong trường hợp này.","Dưới góc độ luật quốc tế đây là một quy định hợp lý được thừa nhận chung, đảm bảo được các nguyên tắc cơ bản trong công pháp quốc tế, tuân thủ các quy định trong UNCLOS 1982."],"a":["Tàu quân sự của quốc gia B đi qua lãnh hải (không vào nội thủy) của quốc gia A. Việc chỉ trình bày việc đi qua (passage) theo điểm a khoản 1 Điều 18 UNCLOS 1982, chưa thể xác định được cơ chế pháp lý được áp dụng với tàu quân sự của quốc gia B này khi xâm nhập lãnh hải của quốc gia ven biển, do đó để giải quyết cần thiết việc chia trường hợp là đi qua không gây hại hay đi qua gây qua gây hai.","Trường hợp 1: đi qua không gây hại. A. Tàu quân sự của nước a được phép đi qua lãnh hải mà không cần xin phép vì đây là quyền được đi qua không gây hại mà bất kỳ tàu biển nào cũng được hưởng theo Điều 17 UNCLOS 1982, quốc gia ven biển có trách nhiệm tạo điều kiện cho tàu biển được thực hiện quyền này theo khoản 1 Điều 24 Công ước này. Tuy nhiên, Tàu quân sự nước B phải thông báo cho A và phải tuân thủ các luật và quy định của Luật biển.","B. Theo nhóm, việc tàu quân sự của quốc gia B đi qua lãnh hải của quốc gia A cần phải thông báo trước cho quốc gia A và phải tuân theo nguyên tắc đi qua không gây hại trong lãnh hải theo tiểu mục A, Mục 3 Công ước Viên Luật biển 1982.","Tuy không có quy định cụ thể nào trong Công ước viên của Liên Hợp Quốc về Luật biển 1982 quy định về việc tàu quân sự nước ngoài phải thông báo trước cho quốc gia ven biển được biết về việc tàu quân sự nước ngoài đi vào lãnh hải của quốc gia mình. Nhưng xét thấy các quy định trong Công ước đã gợi mở cho các quốc gia ven biển có quyền thiết lập các biện pháp cần thiết nhằm ngăn cản mọi việc đi qua có gây hại, được biểu đạt qua các lập luận sau:","(i) Theo Điều 19 (Nghĩa của thuật ngữ đi qua không gây hại) và Điều 25 (Quyền bảo vệ của quốc gia ven biển), Quốc gia ven biển có quyền thi hành các biện pháp cần thiết để bảo vệ lợi ích an ninh quốc gia, điều này sẽ bao gồm cả việc yêu cầu tàu quân sự nước ngoài phải tiến hành thông báo trước khi vào lãnh hải của quốc gia đó. Khoản 1 Điều 25 quy định rằng quốc gia ven biển có thể thi hành các biện pháp cần thiết trong lãnh hải của mình để ngăn cản mọi việc đi qua gây hại. Khoản 3 Điều 25 cho phép quốc gia ven biển đình chỉ thực hiện việc đi qua không gây hại của tàu thuyền nước ngoài tại các khu vực nhất định trong lãnh hải của mình, nếu biện pháp này là cần thiết để bảo đảm an ninh.","(ii) Các quy định tại Điều 30 Công ước Luật biển 1982 liên quan đến việc tàu chiến không tuân thủ các luật và quy định của quốc gia ven biển khi đi qua lãnh hải, cho phép quốc gia ven biển được xây dựng các luật lệ về lãnh hải. Do đó, các quốc gia này có thể đưa ra những quy định bắt buộc tàu quân sự phải xin phép hoặc thông báo trước khi vào lãnh hải trong luật lệ của mình.","(iii) Hơn nữa, Lãnh hải luôn là một phần lãnh thổ của quốc gia ven biển và thuộc chủ quyền của quốc gia. Vì vậy, theo nguyên tắc bảo đảm sự toàn vẹn lãnh thổ và bảo vệ chủ quyền, an ninh quốc gia, quốc gia ven biển được phép áp dụng các quy định trên.","C. Dựa vào khoản 2 Điều 12 Luâ ̣t Biển Viê ̣t Nam 2012 quy định: “Đối với tàu quân sự nước ngoài khi thực hiện quyền đi qua không gây hại trong lãnh hải Việt Nam, thông báo trước cho cơ quan có thẩm quyền của Việt Nam”. Chính vì thế khi tàu quân sự nước B đi qua lãnh hải của Việt Nam phải có nghĩa vụ thông báo cho cơ quan quản lý nhà nước có thẩm quyền của Việt Nam.","Nhìn nhận quy định phải thông báo đối với hành vi đi qua không gây hại của tàu quân sự dưới lăng kính của luật quốc tế, thì nhiều người có thể đánh giá rằng quy định này vi phạm nguyên tắc tận tâm thực hiện các điều ước quốc tế đã ký kết, bởi theo quy định tại Điều 17 đây là quyền của tất cả các tàu thuyền, hơn nữa không có một quy chế cụ thể nào trong Công ước ràng buộc để quốc gia ven biển có thể hạn chế quyền đi qua không gây hại như yêu cầu phải xin phép, thông báo. Tuy nhiên nhóm cho rằng đánh giá như trên là không thuyết phục, và quy định của Điều 12 Luật biển Việt Nam hợp lý, tuân thủ Công ước:","Một, lãnh hải là một phần lãnh thổ của quốc gia ven biển và thuộc chủ quyền của quốc gia. Vì vậy, theo nguyên tắc bảo đảm sự toàn vẹn lãnh thổ và bảo vệ chủ quyền, an ninh quốc gia, quốc gia ven biển được phép áp dụng.","Hai là, tại khoản 1 Điều 19 Công ước quy định “không làm phương hại đến hòa bình trật tự và an ninh của quốc gia viên biển”. Việc tàu quân sự đi qua lãnh thổ một quốc gia dù ít hay nhiều cũng hàm chứa những rủi ro nhất định, nên việc yêu cầu thông báo, như là một sự chuẩn bị sự phòng vệ của quốc gia quen biển, Ba là, pháp luật Việt Nam chỉ quy định là phải “thông báo”, việc thông báo này không hạn chế quyền đi qua không gây hại, mà nó gần giống như một thủ tục báo trước đối với Việt Nam.","Bốn, các quy định tại Điều 30 Công ước Luật biển 1982 liên quan đến việc tàu chiến không tuân thủ các luật và quy định của quốc gia ven biển khi đi qua lãnh hải, cho phép quốc gia ven biển được xây dựng các luật lệ về lãnh hải. Do đó, các quốc gia này có thể đưa ra những quy định bắt buộc tàu quân sự phải xin phép hoặc thông báo trước khi vào lãnh hải trong luật lệ của mình.","Cuối cùng, quy định này không chỉ được Việt Nam áp dụng, mà nó còn được cái nước áp dụng một cách rộng rãi, và dần trở thành một “nguyên tắc” trong quy chế đi qua không gây hại của tàu quân sự trong lãnh hải quốc gia. Điển hình như đối với một số các quốc gia như Croatia, Egypt, Finland, Guyana, India, South Korea, Libya, Malta, Mauritius, và Serbia phải tiến hành thủ tục thông báo trước.","Trường hợp hai: đi qua gây hại.","Đây là trường hợp tàu quân sự quốc gia B mặc dù đi qua lãnh hải không vào nội thủy, đi liên tục hành chóng nhưng có một hoặc một số hoạt động quy định tại khoản 2 điều 19 UNCLOS.","a. Tàu quân sự này bắt buộc phải xin phép quốc gia ven biển, trừ trường hợp quốc gia có tàu quân sự và quốc gia ven biển có thỏa thuận khác, bởi đây là lãnh thổ của quốc gia ven biển, quốc gia ven biển có chủ quyền hoàn toàn và đầy đủ. Tàu quân sự có những hoạt động gây hại không được hưởng các quyền được quy định tại Điều 17. Phải xin phép và tuân thủ các quy định pháp luật của quốc gia ven biển, chịu một số hạn chế nhất định. Mặc khác theo quy định tại khoản 1 Điều 25 UNCLOS “quốc gia ven biển có thể thi hành các biện pháp cần thiết trong lãnh hải của mình để ngăn chặn mọi việc đi qua có hại”. Đối với các trường hợp đi qua gây hại, thì thường các quốc gia quen biển sẽ không cho phép hành vi này diễn ra trên lãnh hải quốc gia mình.","b. Trong Công ước không có quy định cụ thể về việc thông báo, tuy nhiên có thể căn cứ theo điều 25, quốc gia ven biển có thể yêu cầu tàu quân sự đi qua gây hại có thể thông báo hoặc không thông báo, tuy nhiên trước đó vẫn phải thực hiện nghĩa vụ xin phép, trừ trường hợp hai quốc gia có thỏa thuận khác.","c. Trước hết là pháp luật Việt Nam không có quy định trực tiếp về giải quyết việc đi qua gây hại. Tuy nhiên, căn cứ vào Luật biển Việt Nam quy “Nhà nước thực hiện chủ quyền đầy đủ và toàn vẹn đối với lãnh hải”. Nên đối với tàu quân sự phải được sự cho phép của Việt Nam mới được đi qua lãnh hải, và có thể áp dụng các quy định về chế độ pháp lý về biên giới quốc gia trong trường hợp này.","Dưới góc độ luật quốc tế đây là một quy định hợp lý được thừa nhận chung, đảm bảo được các nguyên tắc cơ bản trong công pháp quốc tế, tuân thủ các quy định trong UNCLOS 1982."],"q":"Bài tập 6. Tàu quân sự của quốc gia B đi qua lãnh hải (không vào nội thủy của QG A. Anh/chị hãy cho biết:"},{"qs":["Bài tập 7. Tàu đánh cá của quốc gia B đánh cá trong vùng đặc quyền kinh tế của Việt Nam. Bằng kiến thức về Luật biển quốc tế và Luật biển VN đã được học, anh/chị hãy cho biết:","a) Tàu đánh cá của QG B có quyền hay không?","Chế độ pháp lý riêng của vùng ĐQKT được quy định cụ thể tại Phần V UNCLOS 1982, bao gồm các quyền chủ quyền và quyền tài phán của QG ven biển, các quyền tự do của các QG khác.","Điều 56 UNCLOS quy định quốc gia ven biển (trường hợp này là Việt Nam) có quyền khai thác các tài nguyên thiên nhiên sinh vật trong vùng đặc quyền kinh tế của mình. Theo mục 3 Tuyên bố của Chính phủ nước Cộng hòa xã hội chủ nghĩa Việt Nam về lãnh hải, vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế và thềm lục địa của Việt Nam ngày 12/5/1997 (sau đây gọi tắt là Tuyên bố ngày 12/5/1997): “Nước Cộng hòa xã hội chủ nghĩa Việt Nam có chủ quyền hoàn toàn về việc thăm dò, khai thác, bảo vệ và quản lý tất cả các tài nguyên thiên nhiên, sinh vật và không sinh vật ở vùng nước, ở đáy biển và trong lòng đất dưới đáy biển của vùng đặc quyền kinh tế của Việt Nam; có quyền và thẩm quyền riêng biệt về các hoạt động khác phục vụ cho việc thăm dò và khai thác vùng đặc quyền kinh tế nhằm mục đích kinh tế; …” và tại điểm a khoản 1 Điều 16 Luật Biển Việt Nam 2012 nhấn mạnh: “Trong vùng đặc quyền kinh tế, Nhà nước thực hiện: a) Quyền chủ quyền về việc thăm dò, khai thác, quản lý và bảo tồn tài nguyên thiên nhiên thuộc vùng nước bên trên đáy biển, đáy biển và lòng đất dưới đáy biển;…”. Như vậy, việc đánh bắt cá trong vùng đặc quyền kinh tế thuộc quyền chủ quyền của quốc gia ven biển (Việt Nam), mọi hành vi tùy tiện đánh bắt cá của các quốc gia khác trong vùng đặc quyền kinh tế của Việt Nam là vi phạm UNCLOS 1982.","Tuy nhiên, tàu đánh cá nước B có thể được quyền khai thác cá trong vùng đặc quyền kinh tế của Việt Nam nếu:","– B là quốc gia đang phát triển không có biển hoặc bất lợi về mặt địa lý hoặc các quốc gia đang phát triển khác trong cùng khu vực hoặc phân khu vực với Việt Nam;","– Nước B được Việt Nam cho phép hoạt động khai thác số dư khối lượng cá ở vùng đặc quyền kinh tế của Việt Nam thông qua việc ký kết các điều ước quốc tế và tàu thuyền đánh cá nước B được Việt Nam cấp giấy phép đánh bắt;","– Tàu đánh cá nước B thực hiện việc đánh bắt tuân thủ theo pháp luật và các quy định của Việt Nam đưa ra.","(CSPL: khoản 2,3,4 Điều 62; Điều 69 và Điều 70 UNCLOS).","b) VN có cho phép các QG khác được khai thác số dư của khối lượng cho phép đánh bắt trong vùng ĐQKT của VN không? CSPL?","Theo quy định tại khoản 2, 3 Điều 62 UNCLOS 1982, đối với các tài nguyên sinh vật trong vùng ĐQKT, QG ven biển tự định ra tổng khối lượng có thể đánh bắt được, tự đánh giá khả năng thực tế của mình trong việc khai thác các tài nguyên sinh vật biển và ấn định số dư của khối lượng cho phép đánh bắt. Nếu số dư này tồn tại thì QG ven biển được quyền cho phép các QG khác, thông qua các ĐƯQT hoặc những thỏa thuận liên quan, khai thác số dư của khối lượng cho phép đánh bắt này, có ưu tiên cho các quốc gia không có biển hoặc các quốc gia bất lợi về mặt địa lý.","Như vậy, Việt Nam được quyền cho phép các quốc gia khác khai thác số dư khối lượng cho phép đánh bắt trong vùng đặc quyền kinh tế của mình và trên thực tế Việt Nam và Trung Quốc đã ký kết Hiệp định phân định vịnh Bắc Bộ và hợp tác nghề cá giữa Cộng hòa xã hội chủ nghĩa Việt Nam và Cộng hòa nhân dân Trung Hoa ngày 26/12/2000, trong đó Điều 3.1 quy định hai bên ký kết nhất trí thành lập vùng đánh cá chung trong vùng đặc quyền kinh tế của mỗi nước và theo tinh thần Điều 6 của Hiệp định này thì sản lượng được phép đánh bắt trong vùng đánh cá chung là sản lượng tổng được phép đánh bắt của cả hai nước cho nên nếu như trong trường hợp các tàu đánh cá của Việt Nam khai thác không hết khối lượng cho phép đánh bắt của mình thì tàu đánh cá của Trung Quốc được quyền khai thác số dư này nhưng vẫn phải trong phạm vi sản lượng chung được phép đánh bắt trong vùng đánh cá chung, mà vùng này được thành lập trong vùng đặc quyền kinh tế của 2 nước Việt Nam và Trung Quốc. Ngoài ra, Việt Nam còn cho Lào là quốc gia đang phát triển không có biển khai thác số cá dư trong vùng đặc quyền kinh tế của mình theo thỏa thuận giữa hai bên.","c) Các cơ quan có thẩm quyền nào của VN được thực hiện quyền truy đuổi? Kết quả của hành vi truy đuổi là gì?","Theo quy định tại khoản 5 Điều 11 UNCLOS 1982 thì quyền truy đuổi chỉ có thể được thực hiện bởi các tàu quân sự hay các phương tiện quân sự hoặc các tàu hay các phương tiện khác có mang các dấu hiệu ở bên ngoài chỉ rõ ràng rằng các tàu hay phương tiện bay đó được sử dụng cho một cơ quan Nhà nước và được phép làm nhiệm vụ này. Theo đó, PL VN quy định cụ thể các cơ quan trong nước có thẩm quyền thực hiện quyền truy đuổi tại khoản 1 Điều 41 LBVN 2012 là lực lượng tuần tra, kiểm soát trên biển và theo Điều 47 LBVN 2012 thì lực lượng tuần tra, kiểm soát trên biển bao gồm: các lực lượng có thẩm quyền thuộc Quân đội nhân dân, Công an nhân dân, các lực lượng tuần tra, kiểm soát chuyên ngành khác; và các lực lượng dân quân tự vệ của các tỉnh, thành phố ven biển trực thuộc trung ương, lực lượng bảo vệ của cơ quan, tổ chức đóng ven biển các lực lượng khác cũng có trách nhiệm tham gia tuần tra, kiểm soát biển khi được cơ quan có thẩm quyền huy động.","Kết quả của hành vi truy đuổi là:","– Nếu tàu bị truy đuổi dừng lại trong các vùng biển của quốc gia ven biển hoặc biển quốc tế thì lực lượng tuần tra, kiểm soát trên biển có thể áp dụng các biện pháp ngăn chặn quy định tại Điều 51 Luật biển Việt Nam 2012: bắt, tạm giữ, tạm giam các cá nhân có hành vi vi phạm pháp luật; tạm giữ tàu thuyền sử dụng thực hiện hành vi vi phạm pháp luật; có thể ra quyết định xử lý vi phạm tại chỗ tùy theo tích chất và mức độ vi phạm hoặc dẫn giải người, tàu thuyền vi phạm vào bờ hoặc yêu cầu cơ quan hữu quan của quốc gia mà tàu mang cờ, quốc gia nơi tàu đó đến để xử lý vi phạm (Điều 50 Luật biển Việt Nam 2012).","– Nếu tàu bị truy đuổi đi vào lãnh hải của quốc gia mà nó thuộc quyền hay của một quốc gia khác thì quyền truy đuổi của quốc gia ven biển chấm dứt (khoản 3 Điều 111 UNCLOS, khoản 3 Điều 41 Luật biển Việt Nam 2012).","Những hành động này của cơ quan có thẩm quyền nhà nước là nhằm mục đích ngăn chặn các thiệt hại xấu xảy ra và trừng phạt kịp thời những đối tượng có hành vi vi phạm pháp luật đối với quốc gia ven biển."],"a":["Tàu đánh cá của quốc gia B đánh cá trong vùng đặc quyền kinh tế của Việt Nam.a/ Tàu đánh cá của quốc gia B có quyền này không?","Chế độ pháp lý riêng của vùng đặc quyền kinh tế được quy định cụ thể tại phần V của Công ước của Liên Hợp Quốc về Luật biển 1982 (UNCLOS), bao gồm các quyền chủ quyền và quyền tài phán của quốc gia ven biển, các quyền tự do của các quốc gia khác.","Điều 56 UNCLOS quy định quốc gia ven biển (trường hợp này là Việt Nam) có quyền khai thác các tài nguyên thiên nhiên sinh vật trong vùng đặc quyền kinh tế của mình. Theo mục 3 Tuyên bố của Chính phủ nước Cộng hòa xã hội chủ nghĩa Việt Nam về lãnh hải, vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế và thềm lục địa của Việt Nam ngày 12/5/1997 (sau đây gọi tắt là Tuyên bố ngày 12/5/1997): “Nước Cộng hòa xã hội chủ nghĩa Việt Nam có chủ quyền hoàn toàn về việc thăm dò, khai thác, bảo vệ và quản lý tất cả các tài nguyên thiên nhiên, sinh vật và không sinh vật ở vùng nước, ở đáy biển và trong lòng đất dưới đáy biển của vùng đặc quyền kinh tế của Việt Nam; có quyền và thẩm quyền riêng biệt về các hoạt động khác phục vụ cho việc thăm dò và khai thác vùng đặc quyền kinh tế nhằm mục đích kinh tế;…” và tại điểm a khoản 1 Điều 16 Luật Biển Việt Nam 2012 nhấn mạnh: “Trong vùng đặc quyền kinh tế, Nhà nước thực hiện: a) Quyền chủ quyền về việc thăm dò, khai thác, quản lý và bảo tồn tài nguyên thiên nhiên thuộc vùng nước bên trên đáy biển, đáy biển và lòng đất dưới đáy biển;…”. Như vậy, việc đánh bắt cá trong vùng đặc quyền kinh tế thuộc quyền chủ quyền của quốc gia ven biển (Việt Nam), mọi hành vi tùy tiện đánh bắt cá của các quốc gia khác trong vùng đặc quyền kinh tế của Việt Nam là vi phạm Công ước UNCLOS.","Tuy nhiên, tàu đánh cá nước B có thể được quyền khai thác cá trong vùng đặc quyền kinh tế của Việt Nam nếu:","- B là quốc gia đang phát triển không có biển hoặc bất lợi về mặt địa lý hoặc các quốc gia đang phát triển khác trong cùng khu vực hoặc phân khu vực với Việt Nam;","- Nước B được Việt Nam cho phép hoạt động khai thác số dư khối lượng cá ở vùng đặc quyền kinh tế của Việt Nam thông qua việc ký kết các điều ước quốc tế và tàu thuyền đánh cá nước B được Việt Nam cấp giấy phép đánh bắt;","- Tàu đánh cá nước B thực hiện việc đánh bắt tuân thủ theo pháp luật và các quy định của Việt Nam đưa ra.","(CSPL: khoản 2,3,4 Điều 62; Điều 69 và Điều 70 UNCLOS). b/ Việt Nam có cho phép các quốc gia khác được khai thác số dư của khối lượng cho phép đánh bắt trong vùng đặc quyền kinh tế của Việt Nam không? Cơ sở pháp lý?","Theo quy định tại khoản 2,3 Điều 62 UNCLOS, đối với các tài nguyên sinh vật trong vùng đặc quyền kinh tế, quốc gia ven biển tự định ra tổng khối lượng có thể đánh bắt được, tự đánh giá khả năng thực tế của mình trong việc khai thác các tài nguyên sinh vật biển và ấn định số dư của khối lượng cho phép đánh bắt. Nếu số dư này tồn tại thì quốc gia ven biển được quyền cho phép các quốc gia khác, thông qua các điều ước hoặc những thoả thuận liên quan, khai thác số dư của khối lượng cho phép đánh bắt này, có ưu tiên cho các quốc gia không có biển hoặc các quốc gia bất lợi về mặt địa lý.","Như vậy, Việt Nam được quyền cho phép các quốc gia khác khai thác số dư khối lượng cho phép đánh bắt trong vùng đặc quyền kinh tế của mình và trên thực tế Việt Nam và Trung Quốc đã ký kết Hiệp định phân định vịnh Bắc Bộ và hợp tác nghề cá giữa Cộng hòa xã hội chủ nghĩa Việt Nam và Cộng hòa nhân dân Trung Hoa ngày 26/12/2000, trong đó Điều 3.1 quy định hai bên ký kết nhất trí thành lập vùng đánh cá chung trong vùng đặc quyền kinh tế của mỗi nước và theo tinh thần Điều 6 của Hiệp định này thì sản lượng được phép đánh bắt trong vùng đánh cá chung là sản lượng tổng được phép đánh bắt của cả hai nước cho nên nếu như trong trường hợp các tàu đánh cá của Việt Nam khai thác không hết khối lượng cho phép đánh bắt của mình thì tàu đánh cá của Trung Quốc được quyền khai thác số dư này nhưng vẫn phải trong phạm vi sản lượng chung được phép đánh bắt trong vùng đánh cá chung, mà vùng này được thành lập trong vùng đặc quyền kinh tế của 2 nước Việt Nam và Trung Quốc. Ngoài ra, Việt Nam còn cho Lào là quốc gia đang phát triển không có biển khai thác số cá dư trong vùng đặc quyền kinh tế của mình theo thỏa thuận giữa hai bên.","c/ Các cơ quan có thẩm quyền nào của Việt Nam được thực hiện quyền truy đuổi? Kết quả của hành vi truy đuổi là gì?","Theo quy định của UNCLOS tại khoản 5 Điều 111 UNCLOS: “Quyền truy đuổi chỉ có thể được thực hiện bởi các tàu quân sự hay các phương tiện quân sự hoặc các tàu hay phương tiện nay khác có mang các dấu hiệu ở bên ngoài chỉ rõ ràng rằng, các tàu hay phương tiện bay đó được sử dụng cho một cơ quan Nhà nước và được phép làm nhiệm vụ này”. Dựa trên quy định của UNCLOS về các phương tiện được thực hiện quyền truy đuổi, pháp luật Việt Nam quy định cụ thể các cơ quan trong nước có thẩm quyền thực hiện quyền truy đuổi tại khoản1 Điều 41 Luật Biển Việt Nam 2012, đó là: “Lực lượng tuần tra, kiểm soát trên biển có quyền truy đuổi tàu thuyền nước ngoài…” và theo Điều 47 Luật Biển Việt Nam thì lực lượng tuần tra, kiểm soát trên biển bao gồm: các lực lượng có thẩm quyền thuộc Quân đội nhân dân, Công an nhân dân, các lực lượng tuần tra, kiểm soát chuyên ngành khác; và các lực lượng dân quân tự vệ của các tỉnh, thành phố ven biển trực thuộc trung ương, lực lượng bảo vệ của cơ quan, tổ chức đóng ven biển các lực lượng khác cũng có trách nhiệm tham gia tuần tra, kiểm soát biển khi được cơ quan có thẩm quyền huy động.","Kết quả của hành vi truy đuổi là: - Nếu tàu bị truy đuổi dừng lại trong các vùng biển của quốc gia ven biển hoặc biển quốc tế thì lực lượng tuần tra, kiểm soát trên biển có thể áp dụng các biện pháp ngăn chặn quy định tại Điều 51 Luật biển Việt Nam 2012: bắt, tạm giữ, tạm giam các cá nhân có hành vi vi phạm pháp luật; tạm giữ tàu thuyền sử dụng thực hiện hành vi vi phạm pháp luật; có thể ra quyết định xử lý vi phạm tại chỗ tùy theo tích chất và mức độ vi phạm hoặc dẫn giải người, tàu thuyền vi phạm vào bờ hoặc yêu cầu cơ quan hữu quan của quốc gia mà tàu mang cờ, quốc gia nơi tàu đó đến để xử lý vi phạm (Điều 50 Luật biển Việt Nam 2012).","- Nếu tàu bị truy đuổi đi vào lãnh hải của quốc gia mà nó thuộc quyền hay của một quốc gia khác thì quyền truy đuổi của quốc gia ven biển chấm dứt (khoản 3 Điều 111 UNCLOS, khoản 3 Điều 41 Luật biển Việt Nam 2012).","Những hành động này của cơ quan có thẩm quyền nhà nước là nhằm mục đích ngăn chặn các thiệt hại xấu xảy ra và trừng phạt kịp thời những đối tượng có hành vi vi phạm pháp luật đối với quốc gia ven biển."],"q":"Bài tập 7. Tàu đánh cá của quốc gia B đánh cá trong vùng đặc quyền kinh tế của Việt Nam. Bằng kiến thức về Luật biển quốc tế và Luật biển VN"},{"qs":["Bài tập 8. Tháng 6/2014, TQ chính thức đưa ra Tuyên bố đường yêu sách 10 đoạn (năm 2009 là 9 đoạn) trên Biển Đông (đường lưỡi bò) chiếm hầu hết hơn 90% diện tích Biển Đông.","a) Tuyên bố trên có CSPL không? Tại sao?","TQ là quốc gia thành viên của Công ước LHQ về Luật biển 1982. Do đó, việc Trung Quốc mở rộng vùng biển thuộc chủ quyền và quyền chủ quyền phải phù hợp với mục tiêu và các nguyên tắc của Liên Hiệp Quốc đã được nêu trong Hiến chương.","Đường chín đoạn là tên gọi dùng để chỉ đường quốc giới hải vực biển Đông mà Cộng hòa Nhân dân Trung Hoa chủ trương và đơn phương tuyên bố chủ quyền năm 2009 và gửi lên Tổng thư ký Liên Hiệp Quốc vào ngày 7 tháng 5 năm 2009. Đến tháng 6/2014, Trung Quốc chính thức đưa ra tuyên bố yêu sách 10 đoạn. Trung Quốc dựa vào các cơ sở như sau:"," Thứ nhất, “Đường mười một đoạn” trong phụ lục “Bản đồ vị trí các đảo Nam Hải”( xuất hiện công khai lần đầu tiên vào tháng 2 năm 1948) của “Bản đồ khu vực hành chính Trung Hoa Dân Quốc” do Cục Phương vực Bộ Nội chính Trung Hoa Dân Quốc phát hành."," Thứ hai, Trung Quốc đã cho rằng mình xuất bản bản đồ có thể hiện “đường lưỡi bò” trong một thời gian dài nhưng không có bất cứ một quốc gia nào phản đối hay cuộc đàm phán song phương và đa phương nào về vùng biển mà Trung Quốc đã được in trên bản đồ.","Tuy nhiên, đường này xuất hiện do thời điểm đó Trung Hoa Dân quốc không có khả năng đo lường các hòn đảo để xác định mọi địa hình tạo đường phân định cho khu vực hành chính xung quanh vì thế họ vẽ ra đường chạy qua điểm giữa các hòn đảo và vùng đất lân bang để chỉ ra rằng các đảo nằm bên trong đường vẽ ra là lãnh thổ Trung Hoa. Đường này chạy qua điểm trung tuyến giữa các điểm nhô ra nhất của các hòn đảo và địa hình của đất liền xung quanh. Không hề có các tọa độ địa lý cụ thể được nêu ra và những bản đồ mỗi thời in đường chín đoạn này lại khác nhau. Đến năm 1953 thì bỏ hai đoạn trong vịnh Bắc Bộ, trở thành “đường chín đoạn”. Thực tế lịch sử cho thấy, cả Chính phủ Trung Hoa Dân quốc lẫn Chính phủ Cộng Hòa Nhân dân Trung Hoa chưa bao giờ đưa ra lời tuyên bố hoặc giải thích chính thức gì về “đường lưỡi bò” đó. Năm 1993, chính phủ Đài Loan công bố Nam Hải Chính sách Cương lĩnh cho rằng Đường chín đoạn phân định ra vùng nước lịch sử. Nhưng đễn năm 2003 Tổng thống Đài Loan Trần Thủy Biển đã bác bỏ chính sách này.","Về mặt lịch sử, đường lưỡi bò mà Trung Quốc gửi lên Liên Hiệp Quốc nhằm hợp pháp hóa vùng biển thuộc chủ quyền và quyền chủ quyền nằm bên trong đường lưỡi bò đã không có giá trị. Vì về mặt lịch sử, đường này được tuyên không mang danh của nước Công hòa nhân dân Trung Hoa mà thực chất chỉ là tuyên bố của một cá nhân. Do vậy, vùng biển nằm bên trong đường lưỡi bò mà Trung Quốc tuyên bố không có “quyền lịch sử” với các vùng biển ở Biển Đông.","Về mặt pháp lí, đường lưỡi bò không phù hợp với cách tính của Công ước Liên Hiệp Quốc về Luật Biển 1982 mà Trung Quốc là thành viên, cụ thể là không rõ ràng về vùng biển thuộc chủ quyền và quyền chủ quyền nằm trong đường lưỡi bò. Bản đồ này chứa một số lỗi như sau: Tỉ lệ xích thì đúng nhưng thước tỉ lệ thì vẽ sai: 1 km được thể hiện bằng 635 mét. Như vậy nếu dùng thước tỷ lệ này vào việc đo 200 hải lý (370 km) trên bản đồ, chỉ bằng 127 hải lý (235 km) trên thực địa. Hơn nữa, áp thước tỷ lệ này trên các bản đồ của Mỹ thì hóa ra 1 km chỉ có 630 m. Trong khi đó theo UNCLOS quy định: 1 hải lí thì bằng 1852m trên thực địa. Như vậy việc Trung Quốc đơn phương tuyên bố đường chính đoạn đã vi phạm: Điều 8 – UNCLOS quy định về nội thủy, Điều 3 và 4 – UNCLOS quy định về lãnh hải, Điều 33 – UNCLOS quy định về vùng tiếp giáp lãnh hải, Điều 55 – UNCLOS, vùng đặc quyền kinh tế, Điều 76 – UNCLOS, thềm lục địa của một quốc gia ven biển.","Khái niệm “vịnh lịch sử” hay “vùng nước lịch sử” mà ở đó một quốc gia thực hiện quyền lực thuộc chủ quyền của mình đã được luật pháp quốc tế chấp nhận trong một số hoàn cảnh hạn chế. Điều 10 của UNCLOS thừa nhận sự tồn tại của một vùng nước như vậy, và một số các vịnh biển mà không đáp ứng được các tiêu chuẩn chính thức của một “vịnh” theo Điều 10 đã được trao cho quy chế này theo thời gian.","Khái niệm về yêu sách lịch sử được chấp nhận vào năm 1951 bởi Tòa án quốc tế (ICJ) khi phán xét về yêu sách của Na uy về vùng nước nằm tiếp liền bờ biển của nước này.","Theo đó thì một vịnh hay một vùng nước được coi là lịch sử, căn cứ theo tập quán quốc tế và các phán quyết của tòa án phải thỏa mãn ít nhất là hai điều kiện sau: 1) Quốc gia ven biển thực thi chủ quyền của mình đối với vùng được yêu sách; 2) Sự liên tục của việc thực thi quyền lực đó theo thời gian; 3) Quan điểm của các quốc gia khác với yêu sách đó. Ngoài ra, một quốc gia yêu sách danh nghĩa lịch sử phải có trách nhiệm đưa ra bằng chứng đối với các vùng nước có vấn đề đang tranh cãi này.","Bất cứ chính quyền nào yêu sách vùng nước nằm trong “đường lưỡi bò” là vùng nước lịch sử thì quy chế pháp lý đối với vùng nước này như thế nào, nếu các vùng nước này được yêu sách như vùng nội thủy thì các chính quyền yêu sách đó phải chứng minh được là họ đã thực thi chủ quyền một cách liên tục đối với các vùng nước bao bọc trong “đường lưỡi bò” qua một thời gian tương đối giống như đã thực thi chủ quyền đối với các vùng nội thủy khác. Nếu các vùng nước này được yêu sách như lãnh hải thì quốc gia yêu sách phải chỉ ra được rằng họ đã thực thi chủ quyền một cách liên tục đối với các vùng nước bị bao bọc này trong một thời gian dài như họ đã thực thi chủ quyền đối với các vùng lãnh hải khác. Cũng tương tự như vậy nếu họ muốn yêu sách các vùng nước bị bao bọc như là vùng nước lịch sử.","Đối với yêu sách như các vùng nội thủy:","Theo chế độ pháp lý của các vùng nội thủy, một quốc gia ven biển thực thi chủ quyền đầy đủ đối với vùng nước nằm phía bên trong đường cơ sở để tính chiều rộng lãnh hải, tàu nước ngoài không có quyền đi qua không gây hại trong vùng nội thủy của quốc gia ven biển, trừ khi được sự đồng ý của quốc gia đó.","Vậy vùng nước bị bao bọc bởi “đường lưỡi bò”có thể được coi là vùng nội thủy không? Câu trả lời đến ngay từ một học giả Đài Loan là không, bởi những lý do sau đây: thứ nhất, chính quyền Cộng hòa Trung Hoa chưa bao giờ yêu sách vùng nước bên trong “đường lưỡi bò” như là vùng nội thủy. Thứ hai, tàu nước ngoài, trong đó có cả tàu chiến vẫn thực hiện quyền đi lại trên vùng nước nằm trong “đường lưỡi bò” này từ khi “đường lưỡi bò” này xuất hiện trên bản đồ do Cộng Hòa Trung Hoa xuất bản năm 1948, và chính quyền Cộng Hòa Trung Hoa đã không có một hành động nào ngăn cản các tàu nước ngoài qua lại vùng này.","Đối với yêu sách như lãnh hải:","Theo quy định tại Điều 3 Công ước Luật biển của Liên Hợp Quốc năm 1982 (UNCLOS) thì: “Mọi quốc gia đều có quyền ấn định chiều rộng lãnh hải của mình; chiều rộng này không vượt quá 12 hải lý kể từ đường cơ sở được vạch ra theo đúng Công ước”. Mọi quốc gia có quyền thực thi chủ quyền đối với vùng lãnh hải của mình. Tàu thuyền nước ngoài chỉ được hưởng quyền đi qua không gây hại cho trong vùng lãnh hải của các quốc gia ven biển, trừ khi có các điều khoản, điều ước chuyên môn khác. Đối với vùng trời phía trên lãnh hải, các máy bay nước ngoài được quyền bay qua không gây hại.","Máy bay nước ngoài đã bay qua vùng trời phía trên của vùng nước này từ năm 1948 khi bản đồ được xuất bản. Như đã trình bày ở trên, máy bay của nước ngoài không được phép bay qua không gây hại trên vùng trời phía trên của lãnh hải quốc gia ven biển. Như vậy, đây không được xem là lãnh hải của Trung Quốc.","Đối với yêu sách như các vùng nước quần đảo:","Do chế độ pháp lý của “các vùng nước quần đảo” được phát triển trong giai đoạn hội nghị lần thứ III của UNCLOS (từ năm 1973 – 1982) và bản đồ thể hiện “đường lưỡi bò” xuất bản lần đầu năm 1948, nên khó có thể chứng minh được vùng nước bên trong “đường lưỡi bò” đó có được quy chế pháp lý của các vùng nước quần đảo, Cộng Hòa Trung Hoa đã không thực thi chủ quyền và quyền tài phán của mình đối toàn bộ các vùng nước bên trong “đường lưỡi bò” này, tàu và máy bay nước ngoài vẫn tiếp tục được hưởng quyền tự do hàng hải và hàng không trong vùng nước nằm trong đường này, thay cho quyền đi qua không gây hại và quyền được qua lại các tuyến hàng hải và hàng không đã được ấn định của vùng nước quần đảo. Vì thế, có thể kết luận là toàn bộ các vùng nước bên trong “đường lưỡi bò” không thể được xem là các vùng nước quần đảo của Cộng hòa Trung Hoa.","Theo các tiêu chí để thỏa mãn một vùng nước được coi là vùng nước lịch sử, thì Trung Quốc cũng phải chứng minh được họ đã thực thi chủ quyền trên toàn bộ vùng nước trong đường lưỡi bò này một cách thật sự và liên tục trong một thời gian dài. Điều này thật không đơn giản, bởi vì:","Thời điểm mà Trung Quốc thực sự đặt chân lên quần đảo Hoàng Sa là năm 1909, với hành động của Lý Chuẩn, tuy nhiên lúc này Hoàng Sa đã không còn là một lãnh thổ vô chủ nữa. Việt Nam đã thực thi chủ quyền của mình từ ít nhất là năm 1816.","Đường lưỡi bò không phải là con đường có tính ổn định và xác định. Từ 11 đoạn, năm 1953, Trung Quốc đã phải bỏ đi hai đoạn trong vịnh Bắc Bộ vì quá vô lý. Tính chất không liên tục của con đường này được các tác giả Trung Quốc giải thích là để cho “những điều chỉnh cần thiết trong tương lai”. Đặc tính quan trọng nhất của một đường biên giới quốc tế là sự ổn định và dứt khoát. “Đường lưỡi bò” không thể hiện được đặc tính đó, thêm nữa, vị trí của nó lại không được xác định tọa độ rõ ràng, vì thế khó mà biểu thị là một đường biên giới được.","Vấn đề thứ hai theo Yann Huei Song thì mặc dù “đường lưỡi bò” đã xuất hiện trên các bản đồ xuất bản ở Trung Hoa lục địa từ năm 1949, nhưng chưa bao giờ Cộng Hòa Nhân Dân Trung Hoa yêu sách chính thức các vùng nước nằm trong đường này như các vùng nước lịch sử. Đại diện của Cộng Hòa Nhân Dân Trung Hoa đã không tuyên bố như vậy trong Hội nghị Công ước Luật biển lần III.Theo luật pháp quốc tế, các hành vi mà quốc gia thể hiện phải mang tính công khai ý chí thực thi chủ quyền trên lãnh thổ đó. Những hành vi bí mật không thể tạo nên cơ sở cho quyền lịch sử, ít nhất các quốc gia phải có cơ hội được biết những gì đang diễn ra.","Như vậy, kể cả Cộng Hòa Trung Hoa lẫn Cộng Hòa Nhân Dân Trung Hoa đều chưa bao giờ công bố chính thức yêu sách về vùng biển bên trong “đường lưỡi bò” đó.","Đặc biệt, Điều 1 Tuyên bố năm 1958 về lãnh hải của Cộng hòa Nhân dân Trung Hoa đã nhấn mạnh rằng:","“Chiều rộng lãnh hải nước Cộng Hòa Nhân Dân Trung Hoa là 12 hải lý. Điều khoản này áp dụng cho tất cả các lãnh thổ của nước Cộng Hòa Nhân Dân Trung Hoa, bao gồm lục địa Trung Quốc và các đảo ven bờ của lục địa cũng như các đảo Đài Loan và xung quanh đó, quần đảo Penghu (Bành Hồ) và tất cả các đảo khác thuộc Trung Quốc bị phân cách với đất liền và các đảo ven bờ biển của nó bởi biển cả”.","Như vậy, Tuyên bố 1958 của Trung Quốc xác định rõ ràng các đảo bị tách biệt với lục địa bởi biển cả, chứ không phải là vùng nước lịch sử. Chẳng lẽ lại tồn tại vùng biển cả nằm trong nội thủy của Trung Quốc? Không thể có điều vô lý đó. Do vậy, Tuyên bố và các đạo luật của các nhà chức trách Trung Quốc, đặc biệt Tuyên bố năm 1958 của Cộng hòa Nhân dân Trung Hoa là không phù hợp với yêu sách lịch sử được phân định bởi “đường lưỡi bò”.","Tuyên bố về đường cơ sở của Trung Quốc ngày 15/5/1996 càng làm cho sự mập mờ này của họ bởi họ yêu sách một đường cơ sở nối cả Hoàng Sa nhưng lại không đề cập gì đến Trường Sa.","Hơn nữa, tại hội nghị San Francisco tháng 9 năm 1951, các quốc gia tham gia đã khước từ đề nghị trao trả cho Trung Quốc hai quần đảo Hoàng Sa và Trường Sa và thực tế tranh chấp về chủ quyền trên Hoàng Sa giữa Việt Nam và Trung Quốc hay tranh chấp chủ quyền đối với toàn bộ hay một phần quần đảo Trường Sa giữa Việt Nam, Malaysia, Philippines và Trung Quốc cho thấy không thể nói là “đường lưỡi bò” được các quốc gia khác công nhận. Như vậy, có thể nói là yêu sách này chưa bao giờ có được sự thừa nhận của cộng đồng quốc tế.","Từ những phân tích trên, nhóm khẳng định rằng, việc Trung Quốc tuyên bố đường lưỡi bò là không có cơ sở pháp lí và không có quyền lịch sử với các vùng biển ở Biển Đông theo Công ước Liên Hiệp Quốc về Luật Biển 1982 mà Trung Quốc là thành viên.","b) Những QG nào bị ảnh hưởng bởi Tuyên bố nói trên? Tại sao?","Các QG bị ảnh hưởng bởi tuyên bố “đường lưỡi bò” của TQ là VN, Philippines, Malaysia, Indonesia và Brunei. Bởi vì:","Đường lưỡi bò của TQ lấn lên vùng ĐQKT và thềm lục địa của QG này.","Theo năm tháng, “đường lưỡi bò” dần dần bành trướng đến khi nó bao trùm phần lớn Biển Đông, vào cách bờ biển của các nước khác dưới 100 hải lý mà không hề có một lập luận nào dựa trên luật pháp hay tập quán quốc tế."],"a":["Câu 1: Trung Quốc là quốc gia thành viên của Công ước của Liên Hiệp quốc về luật Biển 1982. Do đó, việc Trung Quốc mở rộng vùng biển thuộc chủ quyền và quyền chủ quyền phải phù hợp với mục tiêu và các nguyên tắc của Liên Hiệp Quốc đã được nêu trong Hiến chương.","Theo như nhóm tìm hiểu: Đường chín đoạn là tên gọi dùng để chỉ đường quốc giới hải vực biển Đông mà Cộng hòa Nhân dân Trung Hoa chủ trương và đơn phương tuyên bố chủ quyền năm 2009 và gửi lên Tổng thư ký Liên Hiệp Quốc vào ngày 7 tháng 5 năm 2009. Đến tháng 6/2014, Trung Quốc chính thức đưa ra tuyên bố yêu sách 10 đoạn. Trung Quốc dựa vào các cơ sở như sau:"," Thứ nhất, \"Đường mười một đoạn\" trong phụ lục \"Bản đồ vị trí các đảo Nam Hải\"( xuất hiện công khai lần đầu tiên vào tháng 2 năm 1948) của \"Bản đồ khu vực hành chính Trung Hoa Dân Quốc\" do Cục Phương vực Bộ Nội chính Trung Hoa Dân Quốc phát hành."," Thứ hai, Trung Quốc đã cho rằng mình xuất bản bản đồ có thể hiện \"đường lưỡi bò\" trong một thời gian dài nhưng không có bất cứ một quốc gia nào phản đối hay cuộc đàm phán song phương và đa phương nào về vùng biển mà Trung Quốc đã được in trên bản đồ.","Tuy nhiên, đường này xuất hiện do thời điểm đó Trung Hoa Dân quốc không có khả năng đo lường các hòn đảo để xác định mọi địa hình tạo đường phân định cho khu vực hành chính xung quanh vì thế họ vẽ ra đường chạy qua điểm giữa các hòn đảo và vùng đất lân bang để chỉ ra rằng các đảo nằm bên trong đường vẽ ra là lãnh thổ Trung Hoa. Đường này chạy qua điểm trung tuyến giữa các điểm nhô ra nhất của các hòn đảo và địa hình của đất liền xung quanh. Không hề có các tọa độ địa lý cụ thể được nêu ra và những bản đồ mỗi thời in đường chín đoạn này lại khác nhau. Đến năm 1953 thì bỏ hai đoạn trong vịnh Bắc Bộ, trở thành \"đường chín đoạn\". Thực tế lịch sử cho thấy, cả Chính phủ Trung Hoa Dân quốc lẫn Chính phủ Cộng Hòa Nhân dân Trung Hoa chưa bao giờ đưa ra lời tuyên bố hoặc giải thích chính thức gì về \"đường lưỡi bò\" đó. Năm 1993, chính phủ Đài Loan công bố Nam Hải Chính sách Cương lĩnh cho rằng Đường chín đoạn phân định ra vùng nước lịch sử. Nhưng đễn năm 2003 Tổng thống Đài Loan Trần Thủy Biển đã bác bỏ chính sách này.","Theo quan điểm của nhóm: Về mặt lịch sử, đường lưỡi bò mà Trung Quốc gửi lên Liên Hiệp Quốc nhằm hợp pháp hóa vùng biển thuộc chủ quyền và quyền chủ quyền nằm bên trong đường lưỡi bò đã không có giá trị. Vì về mặt lịch sử, đường này được tuyên không mang danh của nước Công hòa nhân dân Trung Hoa mà thực chất chỉ là tuyên bố của một cá nhân. Do vậy, vùng biển nằm bên trong đường lưỡi bò mà Trung Quốc tuyên bố không có “quyền lịch sử” với các vùng biển ở Biển Đông.","Về mặt pháp lí, đường lưỡi bò không phù hợp với cách tính của Công ước Liên Hiệp Quốc về Luật Biển 1982 mà Trung Quốc là thành viên, cụ thể là không rõ ràng về vùng biển thuộc chủ quyền và quyền chủ quyền nằm trong đường lưỡi bò. Bản đồ này chứa một số lỗi như sau: Tỉ lệ xích thì đúng nhưng thước tỉ lệ thì vẽ sai: 1 km được thể hiện bằng 635 mét. Như vậy nếu dùng thước tỷ lệ này vào việc đo 200 hải lý (370 km) trên bản đồ, chỉ bằng 127 hải lý (235 km) trên thực địa. Hơn nữa, áp thước tỷ lệ này trên các bản đồ của Mỹ thì hóa ra 1 km chỉ có 630 m. Trong khi đó theo UNCLOS quy định: 1 hải lí thì bằng 1852m trên thực địa. Như vậy việc Trung Quốc đơn phương tuyên bố đường chính đoạn đã vi phạm: Điều 8 – UNCLOS quy định về nội thủy, Điều 3 và 4 – UNCLOS quy định về lãnh hải, Điều 33 – UNCLOS quy định về vùng tiếp giáp lãnh hải, Điều 55 - UNCLOS, vùng đặc quyền kinh tế, Điều 76 - UNCLOS, thềm lục địa của một quốc gia ven biển.","Khái niệm “vịnh lịch sử” hay “vùng nước lịch sử” mà ở đó một quốc gia thực hiện quyền lực thuộc chủ quyền của mình đã được luật pháp quốc tế chấp nhận trong một số hoàn cảnh hạn chế. Điều 10 của UNCLOS thừa nhận sự tồn tại của một vùng nước như vậy, và một số các vịnh biển mà không đáp ứng được các tiêu chuẩn chính thức của một “vịnh” theo Điều 10 đã được trao cho quy chế này theo thời gian.","Khái niệm về yêu sách lịch sử được chấp nhận vào năm 1951 bởi Tòa án quốc tế (ICJ) khi phán xét về yêu sách của Na uy về vùng nước nằm tiếp liền bờ biển của nước này.","Theo đó thì một vịnh hay một vùng nước được coi là lịch sử, căn cứ theo tập quán quốc tế và các phán quyết của tòa án phải thỏa mãn ít nhất là hai điều kiện sau: 1) Quốc gia ven biển thực thi chủ quyền của mình đối với vùng được yêu sách; 2) Sự liên tục của việc thực thi quyền lực đó theo thời gian; 3) Quan điểm của các quốc gia khác với yêu sách đó. Ngoài ra, một quốc gia yêu sách danh nghĩa lịch sử phải có trách nhiệm đưa ra bằng chứng đối với các vùng nước có vấn đề đang tranh cãi này.","Bất cứ chính quyền nào yêu sách vùng nước nằm trong “đường lưỡi bò” là vùng nước lịch sử thì quy chế pháp lý đối với vùng nước này như thế nào, nếu các vùng nước này được yêu sách như vùng nội thủy thì các chính quyền yêu sách đó phải chứng minh được là họ đã thực thi chủ quyền một cách liên tục đối với các vùng nước bao bọc trong “đường lưỡi bò” qua một thời gian tương đối giống như đã thực thi chủ quyền đối với các vùng nội thủy khác. Nếu các vùng nước này được yêu sách như lãnh hải thì quốc gia yêu sách phải chỉ ra được rằng họ đã thực thi chủ quyền một cách liên tục đối với các vùng nước bị bao bọc này trong một thời gian dài như họ đã thực thi chủ quyền đối với các vùng lãnh hải khác. Cũng tương tự như vậy nếu họ muốn yêu sách các vùng nước bị bao bọc như là vùng nước lịch sử.","a. Đối với yêu sách như các vùng nội thủy Theo chế độ pháp lý của các vùng nội thủy, một quốc gia ven biển thực thi chủ quyền đầy đủ đối với vùng nước nằm phía bên trong đường cơ sở để tính chiều rộng lãnh hải, tàu nước ngoài không có quyền đi qua không gây hại trong vùng nội thủy của quốc gia ven biển, trừ khi được sự đồng ý của quốc gia đó.","Vậy vùng nước bị bao bọc bởi “đường lưỡi bò”có thể được coi là vùng nội thủy không? Câu trả lời đến ngay từ một học giả Đài Loan là không, bởi những lý do sau đây: thứ nhất, chính quyền Cộng hòa Trung Hoa chưa bao giờ yêu sách vùng nước bên trong “đường lưỡi bò” như là vùng nội thủy. Thứ hai, tàu nước ngoài, trong đó có cả tàu chiến vẫn thực hiện quyền đi lại trên vùng nước nằm trong “đường lưỡi bò” này từ khi “đường lưỡi bò” này xuất hiện trên bản đồ do Cộng Hòa Trung Hoa xuất bản năm 1948, và chính quyền Cộng Hòa Trung Hoa đã không có một hành động nào ngăn cản các tàu nước ngoài qua lại vùng này.","b. Đối với yêu sách như “lãnh hải”. Theo quy định tại Điều 3 Công ước Luật biển của Liên Hợp Quốc năm 1982 (UNCLOS) thì: “Mọi quốc gia đều có quyền ấn định chiều rộng lãnh hải của mình; chiều rộng này không vượt quá 12 hải lý kể từ đường cơ sở được vạch ra theo đúng Công ước”. Mọi quốc gia có quyền thực thi chủ quyền đối với vùng lãnh hải của mình. Tàu thuyền nước ngoài chỉ được hưởng quyền đi qua không gây hại cho trong vùng lãnh hải của các quốc gia ven biển, trừ khi có các điều khoản, điều ước chuyên môn khác. Đối với vùng trời phía trên lãnh hải, các máy bay nước ngoài được quyền bay qua không gây hại.","Máy bay nước ngoài đã bay qua vùng trời phía trên của vùng nước này từ năm 1948 khi bản đồ được xuất bản. Như đã trình bày ở trên, máy bay của nước ngoài không được phép bay qua không gây hại trên vùng trời phía trên của lãnh hải quốc gia ven biển. Như vậy, đây không được xem là lãnh hải của Trung Quốc.","c. Đối với yêu sách như các vùng nước quần đảo.","Khái niệm về các vùng nước quần đảo là một khái niệm mới trong luật biển quốc tế, được đưa ra trong Hội nghị Liên Hợp Quốc về Luật biển lần III (UNCLOS III), theo đó, các vùng nước nằm bên trong đường cơ sở thẳng của quần đảo là vùng nước quần đảo, nó không phải là nội thủy, cũng không phải là lãnh hải. Một quốc gia quần đảo có quyền thực thi chủ quyền đối với vùng nước quần đảo của mình. Chủ quyền quốc gia “được mở rộng đến vùng trời phía trên của vùng nước quần đảo cũng như đến đáy của vùng nước đó và lòng đất tương ứng và đến các nguồn tài nguyên ở đó”. Tàu nước ngoài được quyền đi qua không gây hại tại vùng nước quần đảo, tàu biển và máy bay nước ngoài được quyền có đường hàng hải, đường hàng không đi qua vùng nước quần đảo.","Do chế độ pháp lý của “các vùng nước quần đảo” được phát triển trong giai đoạn hội nghị lần thứ III của UNCLOS (từ năm 1973 – 1982) và bản đồ thể hiện “đường lưỡi bò” xuất bản lần đầu năm 1948, nên khó có thể chứng minh được vùng nước bên trong “đường lưỡi bò” đó có được quy chế pháp lý của các vùng nước quần đảo, Cộng Hòa Trung Hoa đã không thực thi chủ quyền và quyền tài phán của mình đối toàn bộ các vùng nước bên trong “đường lưỡi bò” này, tàu và máy bay nước ngoài vẫn tiếp tục được hưởng quyền tự do hàng hải và hàng không trong vùng nước nằm trong đường này, thay cho quyền đi qua không gây hại và quyền được qua lại các tuyến hàng hải và hàng không đã được ấn định của vùng nước quần đảo. Vì thế, có thể kết luận là toàn bộ các vùng nước bên trong “đường lưỡi bò” không thể được xem là các vùng nước quần đảo của Cộng hòa Trung Hoa.","Theo các tiêu chí để thỏa mãn một vùng nước được coi là vùng nước lịch sử, thì Trung Quốc cũng phải chứng minh được họ đã thực thi chủ quyền trên toàn bộ vùng nước trong đường lưỡi bò này một cách thật sự và liên tục trong một thời gian dài. Điều này thật không đơn giản, bởi vì:","Thời điểm mà Trung Quốc thực sự đặt chân lên quần đảo Hoàng Sa là năm 1909, với hành động của Lý Chuẩn, tuy nhiên lúc này Hoàng Sa đã không còn là một lãnh thổ vô chủ nữa. Việt Nam đã thực thi chủ quyền của mình từ ít nhất là năm 1816.","Đường lưỡi bò không phải là con đường có tính ổn định và xác định. Từ 11 đoạn, năm 1953, Trung Quốc đã phải bỏ đi hai đoạn trong vịnh Bắc Bộ vì quá vô lý. Tính chất không liên tục của con đường này được các tác giả Trung Quốc giải thích là để cho “những điều chỉnh cần thiết trong tương lai”. Đặc tính quan trọng nhất của một đường biên giới quốc tế là sự ổn định và dứt khoát. “Đường lưỡi bò” không thể hiện được đặc tính đó, thêm nữa, vị trí của nó lại không được xác định tọa độ rõ ràng, vì thế khó mà biểu thị là một đường biên giới được.","Vấn đề thứ hai theo Yann Huei Song thì mặc dù “đường lưỡi bò” đã xuất hiện trên các bản đồ xuất bản ở Trung Hoa lục địa từ năm 1949, nhưng chưa bao giờ Cộng Hòa Nhân Dân Trung Hoa yêu sách chính thức các vùng nước nằm trong đường này như các vùng nước lịch sử. Đại diện của Cộng Hòa Nhân Dân Trung Hoa đã không tuyên bố như vậy trong Hội nghị Công ước Luật biển lần III.Theo luật pháp quốc tế, các hành vi mà quốc gia thể hiện phải mang tính công khai ý chí thực thi chủ quyền trên lãnh thổ đó. Những hành vi bí mật không thể tạo nên cơ sở cho quyền lịch sử, ít nhất các quốc gia phải có cơ hội được biết những gì đang diễn ra.","Như vậy, kể cả Cộng Hòa Trung Hoa lẫn Cộng Hòa Nhân Dân Trung Hoa đều chưa bao giờ công bố chính thức yêu sách về vùng biển bên trong “đường lưỡi bò” đó.","Đặc biệt, Điều 1 Tuyên bố năm 1958 về lãnh hải của Cộng hòa Nhân dân Trung Hoa đã nhấn mạnh rằng:","“Chiều rộng lãnh hải nước Cộng Hòa Nhân Dân Trung Hoa là 12 hải lý. Điều khoản này áp dụng cho tất cả các lãnh thổ của nước Cộng Hòa Nhân Dân Trung Hoa, bao gồm lục địa Trung Quốc và các đảo ven bờ của lục địa cũng như các đảo Đài Loan và xung quanh đó, quần đảo Penghu (Bành Hồ) và tất cả các đảo khác thuộc Trung Quốc bị phân cách với đất liền và các đảo ven bờ biển của nó bởi biển cả”.","Như vậy, Tuyên bố 1958 của Trung Quốc xác định rõ ràng các đảo bị tách biệt với lục địa bởi biển cả, chứ không phải là vùng nước lịch sử. Chẳng lẽ lại tồn tại vùng biển cả nằm trong nội thủy của Trung Quốc? Không thể có điều vô lý đó. Do vậy, Tuyên bố và các đạo luật của các nhà chức trách Trung Quốc, đặc biệt Tuyên bố năm 1958 của Cộng hòa Nhân dân Trung Hoa là không phù hợp với yêu sách lịch sử được phân định bởi “đường lưỡi bò”.","Tuyên bố về đường cơ sở của Trung Quốc ngày 15/5/1996 càng làm cho sự mập mờ này của họ bởi họ yêu sách một đường cơ sở nối cả Hoàng Sa nhưng lại không đề cập gì đến Trường Sa.","Hơn nữa, tại hội nghị San Francisco tháng 9 năm 1951, các quốc gia tham gia đã khước từ đề nghị trao trả cho Trung Quốc hai quần đảo Hoàng Sa và Trường Sa và thực tế tranh chấp về chủ quyền trên Hoàng Sa giữa Việt Nam và Trung Quốc hay tranh chấp chủ quyền đối với toàn bộ hay một phần quần đảo Trường Sa giữa Việt Nam, Malaysia, Philippines và Trung Quốc cho thấy không thể nói là “đường lưỡi bò” được các quốc gia khác công nhận. Như vậy, có thể nói là yêu sách này chưa bao giờ có được sự thừa nhận của cộng đồng quốc tế.","Từ những phân tích trên, nhóm khẳng định rằng, việc Trung Quốc tuyên bố đường lưỡi bò là không có cơ sở pháp lí và không có quyền lịch sử với các vùng biển ở Biển Đông theo Công ước Liên Hiệp Quốc về Luật Biển 1982 mà Trung Quốc là thành viên.","Câu 2: Các quốc gia bị ảnh hưởng bởi tuyên bố \"Đường lưỡi bò\" của Trung Quốc là Việt Nam, Philippines, Malaysia, Indonesia, Brunei.","Bởi vì:","Đường lưỡi bò của Trung Quốc lấn lên vùng đặc quyền kinh tế và thềm lục địa của các quốc gia này.","Theo năm tháng, \"đường lưỡi bò” dần dần bành trướng đến khi nó bao trùm phần lớn Biển Đông, vào cách bờ biển của các nước khác dưới 100 hải lý, mà không hề có một lập luận nào dựa trên luật pháp hay tập quán quốc tế."],"q":"Bài tập 8. Tháng 6/2014, TQ chính thức đưa ra Tuyên bố đường yêu sách 10 đoạn (năm 2009 là 9 đoạn) trên Biển Đông (đường lưỡi bò) chiếm hầu "},{"qs":["Bài tập 9. Năm 2016, Tòa trọng tài theo Phụ lục VII của CULB 1982 đã ra phán quyết vụ Philippines kiện Trung Quốc; bằng kiến thức về Luật biển quốc tế đã được học, anh/chị hãy cho biết:","a) Philippines kiện Trung Quốc về vụ việc gì?","Với tư cách là một quốc gia thành viên của Công ước LHQ về Luật biển 1982, ngày 22/01/2013, Philippines đã đệ đơn kiện về việc Trung Quốc đã giải thích và áp dụng sai UNCLOS 1982 theo Điều 279, Điều 283, Điều 284 lên Tòa Trọng tài thường trực The Haye (PCA).","Cụ thể, Philippines khởi kiện Trung Quốc 15 nội dung, tập trung vào 3 nhóm vấn đề:","Yêu sách đường chín đoạn Trung Quốc đưa ra dựa trên “Quyền lịch sử” không phù hợp với UNCLOS cho nên nó vô giá trị.","Philippines yêu cầu PCA xác định xem, theo UNCLOS, thì một số thực thể địa lý, mà cả Philippines lẫn Trung Quốc yêu sách, là đảo, đá, bãi cạn lúc nổi lúc chìm hay bãi ngầm nằm hoàn toàn dưới mực nước biển, trên cơ sở đó để xác định hiệu lực pháp lý của các thực thể này đến đâu (có hay không có lãnh hải 12 hải lý, vùng đặc quyền kinh tế 200 hải lý).","Philippines yêu cầu PCA tuyên bố Trung Quốc đã vi phạm UNCLOS khi cản trở Philippines thực thi các quyền chủ quyền, quyền tài phán và quyền tự do của Philippines theo UNCLOS cũng như việc Trung Quốc gây tổn hại môi trường biển trong các hoạt động bồi lấp xây dựng đảo, đánh bắt cá mà nước này tiến hành.","Ngày 29/10/2015, PCA – Tòa Trọng tài Thường trực The Haye, ra thông cáo báo chí về vụ kiện giữa Cộng hòa Philippines với Cộng hòa Nhân dân Trung Hoa; trong đó đã khẳng định rằng PCA có thẩm quyền thụ lý, xét xử vụ kiện này theo đúng quy định của UNCLOS và rằng, cả Trung Quốc và Philippines đều là thành viên ràng buộc của UNCLOS có trách nhiệm và nghĩa vụ tuân thủ mọi điều khoản của UNCLOS. Việc Trung Quốc từ chối tham gia vụ kiện không làm mất đi thẩm quyền ra phán quyết của PCA.","PCA đã bác bỏ lập luận của Trung Quốc rằng Philippines chủ yếu khởi kiện các nội dung liên quan đến chủ quyền lãnh thổ và phân định biên giới biển giữa 2 nước, do đó nó vượt qua thẩm quyền của PCA. Ngược lại Tòa khẳng định, bản chất vụ kiện của Philippines phản ánh tranh chấp giữa 2 nước liên quan đến việc giải thích và áp dụng UNCLOS.","Đồng thời, PCA cũng đã bác bỏ lập luận của Trung Quốc cho rằng Tuyên bố về ứng xử của các bên trên Biển Đông (DOC) ký giữa Trung Quốc với ASEAN năm 2002 là thỏa thuận để giải quyết tranh chấp Biển Đông thông qua thương lượng. PCA phán quyết rằng DOC chỉ là một thỏa thuận chính trị mà không ràng buộc pháp lý, do đó không liên quan đến các quy định trong UNCLOS về việc ưu tiên giải quyết tranh chấp thông qua bất kỳ phương tiện nào mà hai bên đồng ý.","b) Phụ lục VII của UNCLOS 1982 đề cập đến nội dung gì?","Phụ lục VII của UNCLOS 1982 đề cập về thẩm quyền, thủ tục và giải quyết tranh chấp bằng trọng tài gồm các nội dung như sau:","Thứ nhất, thẩm quyền thành lập trọng tài quy định tại Điều 1 Phụ lục VII UNCLOS 1982;","Thứ hai, theo quy định của Điều 3 Phụ lục VII về trọng tài, trọng tài gồm 5 thành viên, trừ khi các bên tranh chấp có thỏa thuận khác;","Thứ ba, chức năng của trọng tài: theo quy định tại Điều 4, Phụ lục VII của UNCLOS, trọng tài thi hành các chức năng theo đúng Phụ lục VII và các quy định khác của UNCLOS, Điều 6 về những nghĩa vụ của các bên;","Thứ 4, về xét xử vắng mặt của một bên được quy định tại Điều 9 Phụ lục VII;","Thứ 5, giải thích và thi hành bản án.","Toà trọng tài được thành lập và hoạt động theo đúng Phụ lục VII của Công ước luật biển, là cơ quan tài phán quốc tế.","Toà trọng tài thực hiện các chức năng của mình theo đúng phụ lục VII và các quy định khác của Công ước trong việc giải quyết các tranh chấp liên quan tới luật biển. Bản án của Toà trọng tài có tính tối hậu và không được kháng cao, trừ khi các bên trong vụ tranh chấp đã có thoả thuận trước về một thủ tục kháng cáo. Tất cả các bên trong vụ tranh chấp khi được Toà trọng tài giải quyết vụ việc bằng bản án thì đều phải tuân theo.","c) Phán quyết của Tòa án đề cập tới nội dung gì?","Chiều ngày 12/07/2016, Phán quyết của Hội đồng trọng tài đã chính thức được công bố. Nội dung của Phán quyết đã đề cập đầy đủ 7 nội dung mà Tòa trọng tài đã lựa chọn thuộc thẩm quyền xét xử của mình trong số 15 điểm của đơn khởi kiện. Nội dung phán quyết của Tòa chỉ tập trung phán xét về việc giải thích và áp dụng sai các quy định của UNCLOS 1982, không liên quan gì đến tranh chấp chủ quyền lãnh thổ và tranh chấp về việc phân định các vùng chồng lấn, cụ thể:","- Bác bỏ “Quyền lịch sử” đối với tài nguyên trong đường 9 đoạn - Khẳng định các cấu trúc (thực thể địa lý) thuộc Trường Sa không có hiệu lực để có vùng ĐQKT 200 hải lý - Tòa cũng quyết định rằng các đảo Trường Sa không thể cùng nhau tạo ra các vùng biển như một thực thể thống nhất - Các hoạt động khai thác, xây đảo nhân tạo của TQ đã gây hại cho môi trường biển - Tất cả những hoạt động đó của TQ đã làm trầm trọng thêm tranh chấp"],"a":["1. Philippines kiện Trung quốc về vụ việc gì?","Với tư cách là một quốc gia thành viên Công ước của Liên Hợp Quốc về Luật Biển 1982 (UNCLOS), ngày 22/1/2013, Philippines đã đệ đơn kiện về việc Trung Quốc đã giải thích và áp dụng sai UNCLOS theo Điều 279, Điều 283, Điều 284 lên Tòa Trọng tài Thường trực The Haye (PCA).","Cụ thể, Philippines khởi kiện Trung Quốc 15 nội dung, tập trung vào 3 nhóm vấn đề:","a. Yêu sách đường chín đoạn Trung Quốc đưa ra dựa trên \"Quyền lịch sử\" không phù hợp với UNCLOS cho nên nó vô giá trị.","b. Philippines yêu cầu PCA xác định xem, theo UNCLOS, thì một số thực thể địa lý, mà cả Philippines lẫn Trung Quốc yêu sách, là đảo, đá, bãi cạn lúc nổi lúc chìm hay bãi ngầm nằm hoàn toàn dưới mực nước biển, trên cơ sở đó để xác định hiệu lực pháp lý của các thực thể này đến đâu (có hay không có lãnh hải 12 hải lý, vùng đặc quyền kinh tế 200 hải lý).","c. Philippines yêu cầu PCA tuyên bố Trung Quốc đã vi phạm UNCLOS khi cản trở Philippines thực thi các quyền chủ quyền, quyền tài phán và quyền tự do của Philippines theo UNCLOS cũng như việc Trung Quốc gây tổn hại môi trường biển trong các hoạt động bồi lấp xây dựng đảo, đánh bắt cá mà nước này tiến hành.","Ngày 29/10/2015, PCA - Tòa Trọng tài Thường trực The Haye, ra thông cáo báo chí về vụ kiện giữa Cộng hòa Philippines với Cộng hòa Nhân dân Trung Hoa; trong đó đã khẳng định rằng PCA có thẩm quyền thụ lý, xét xử vụ kiện này theo đúng quy định của UNCLOS và rằng, cả Trung Quốc và Philippines đều là thành viên ràng buộc của UNCLOS có trách nhiệm và nghĩa vụ tuân thủ mọi điều khoản của UNCLOS. Việc Trung Quốc từ chối tham gia vụ kiện không làm mất đi thẩm quyền ra phán quyết của PCA.PCA đã bác bỏ lập luận của Trung Quốc rằng Philippines chủ yếu khởi kiện các nội dung liên quan đến chủ quyền lãnh thổ và phân định biên giới biển giữa 2 nước, do đó nó vượt qua thẩm quyền của PCA. Ngược lại Tòa khẳng định, bản chất vụ kiện của Philippines phản ánh tranh chấp giữa 2 nước liên quan đến việc giải thích và áp dụng UNCLOS.","Đồng thời, PCA cũng đã bác bỏ lập luận của Trung Quốc cho rằng Tuyên bố về ứng xử của các bên trên Biển Đông (DOC) ký giữa Trung Quốc với ASEAN năm 2002 là thỏa thuận để giải quyết tranh chấp Biển Đông thông qua thương lượng. PCA phán quyết rằng DOC chỉ là một thỏa thuận chính trị mà không ràng buộc pháp lý, do đó không liên quan đến các quy định trong UNCLOS về việc ưu tiên giải quyết tranh chấp thông qua bất kỳ phương tiện nào mà hai bên đồng ý.","2. Phụ lục VII của Công ước về Luật Biển 1982 đề cập đến những nội dung gì?","Phụ lục VII của CULB 1982 đề cập về thẩm quyền, thủ tục và giải quyết tranh chấp bằng trọng tài gồm các nội dung như sau:","Thứ 1, thẩm quyền thành lập trọng tài quy định tại Điều 1 Phụ lục VII CULB1982; Thứ 2, Theo quy định của Điều 3, Phụ lục VII về trọng tài, trọng tài gồm 5 thành viên, trừ khi các bên tranh chấp có thỏa thuận khác;","Thứ 3, chức năng của trọng tài: Theo quy định tại Điều 4, Phụ lục VII của UNCLOS, trọng tài thi hành các chức năng theo đúng Phụ lục VII và các quy định khác của UNCLOS, Điều 6 về những nghĩa vụ của các bên;","Thứ 4, về xét xử vắng mặt của một bên được quy định tại Điều 9 Phụ lục VII; Thứ 5: giải thích và thi hành bản án. Toà trọng tài được thành lập và hoạt động theo đúng Phụ lục VII của Công ước luật biển, là cơ quan tài phán quốc tế.","Toà trọng tài thực hiện các chức năng của mình theo đúng phụ lục VII và các quy định khác của Công ước trong việc giải quyết các tranh chấp liên quan tới luật biển. Bản án của Toà trọng tài có tính tối hậu và không được kháng cao, trừ khi các bên trong vụ tranh chấp đã có thoả thuận trước về một thủ tục kháng cáo. Tất cả các bên trong vụ tranh chấp khi được Toà trọng tài giải quyết vụ việc bằng bản án thì đều phải tuân theo.","Phụ lục VII \"ĐIỀU 1. Việc khởi tố Với điều kiện phải tuân thủ Phần XV, bất kỳ bên nào trong một vụ tranh chấp đều có thể đưa vụ tranh chấp ra giải quyết bằng thủ tục trọng tài đã trù định trong Phụ lục này bằng một thông báo viết gửi tới bên kia hoặc hoặc các bên kia trong vụ tranh chấp. Thông báo có kèm theo bản trình bày các yêu sách và các lý do làm căn cứ cho các yêu sách đó.","ĐIỀU 2. Danh sách các trọng tài 1. Tổng thư ký Liên hợp quốc lập ra và giữ một bản danh sách các trọng tài. Mỗi quốc gia thành viên có thể chỉ định bốn trọng tài có kinh nghiệm về những vấn đề biển và nổi tiếng nhất về sự công bằng, về năng lực và liêm khiết. Tên của những người được chỉ định như vậy được ghi rõ trên một bản danh sách.","2. Vào một thời điểm nào đó, nếu số lượng trọng tài được một quốc gia thành viên chỉ định và có trong bản danh sách dưới bốn người thì quốc gia này có quyền tiến hành việc chỉ định bổ sung mà mình có quyền.","3. Tên của một trọng tài được ghi ở trên bản danh sách cho đến khi quốc gia thành viên đã chỉ định người trọng tài này rút người đó khỏi danh sách; dĩ nhiên, người trọng tài này phải tiếp tục làm nhiệm vụ trong mọi Toà trọng tài mà họ được cử cho đến khi thủ tục tiến hành trước toà này kết thúc.","ĐIỀU 3. Thành lập Toà trọng tài Theo thủ tục được trù định trong Phụ lục này, trừ khi các bên liên quan có thoả thuận khác, Toà trọng tài được lập ra, như sau:","a) Với điều kiện tuân thủ điểm g, Toà trọng tài gồm có năm thành viên; b) Bên nguyên cử một thành viên mà mình tuỳ ý lựa chọn ở trên bản danh sách nói ở Điều 2 của Phụ lục này và người đó có thể là công dân của mình. Tên của người đó được ghi trong bản thông báo nói trong Điều 1 của Phụ lục này;","c) Bên bị trong vụ tranh chấp cử trong thời hạn 30 ngày, tính từ khi nhận được thông báo nói ở Điều 1 của Phụ lục này một thành viên mà mình tuỳ ý lựa chọn trên bản danh sách, và người đó có thể là công dân của mình. Nếu họ không cử người trong thời hạn nói trên, thì bên nguyên có thể yêu cầu tiến hành việc cử thành viên đó theo đúng điểm c trong hai tuần lễ sau khi hết thời hạn này;","d) Ba thành viên khác được các bên thoả thuận cử ra. Họ được các bên tuỳ ý chọn trên bản danh sách và là công dân của các quốc gia thứ ba, trừ khi các bên có thoả thuận khác. Các bên cử Chánh toà của Toà trọng tài trong số ba thành viên đó. Nêu trong thời hạn 60 ngày kể từ ngày nhận được thông báo nói ở Điều 1 của Phụ lục này, các bên hữu quan không thể thoả thuận về việc chỉ định một hay nhiều thành viên của Toà mà họ phải cử theo thoả thuận chung hay là về việc cử Chánh toà, thì theo yêu cầu của bất kỳ bên nào trong vụ tranh chấp, cần tiến hành cử 1 người hay những người đó theo đúng điểm e Yêu cầu đó phải được đưa lên trong hai tuần sau khi hết hạn 60 ngày này;","e) Trừ khi các bên hữu quan thoả thuận giao cho một người hoặc cho một quốc gia thứ ba do họ lựa chọn tiến hành các việc cử người cần thiết theo điểm c và d, Chánh án của Toà án quốc tế về luật biển cần tiến hành việc hành. Nếu Chánh án bận hoặc là công dân của một trong các bên trong vụ tranh chấp, thì việc cử người giao cho thành viên thâm niên nhất của Toà án quốc tế về luật biển sẵn sàng làm việc này và không phải là công dân của một trong các bên hữu quan. Việc cử người tiến hành bằng cách lựa chọn trên bản danh cách nói ở Điều 2 của Phụ lục này trong một thời hạn là 30 ngày kể từ ngày nhận được đơn yêu cầu và có tham kháo ý kiến của các bên. Các thành viên được cử như thế cần phải thuộc các quốc tịch khác nhau, không được làm việc cho một bên nào trong vụ tranh chấp; họ không trú ngụ thường xuyên ở trên lãnh thổ của một trong các bên hữu quan đó và không phải là công dân của một bên nào;","f) Mọi ghế bị trống đều được cử người thay thế theo các quy định cho lần bổ nhiệm đầu tiên ;","g) Các bên cùng một phía cùng nhau cử một thành viên của Toà qua thoả thuận chung. Khi có nhiều bên đối lập nhau hay trong trường hợp không thống nhất về điểm liệu các bên có đứng vào cùng một phía không, thì mỗi bên trong số họ cử một thành viên của Toà. Số lượng thành viên của Toà do các bên cử riêng rẽ bao giờ cũng phải ít hơn một người so với số lượng các thành viên của Toà được các bên hữu quan cùng cử ;","h) Các điểm a đến f được áp dụng đến hết mức có thể vào các vụ tranh chấp xảy ra có quá hai bên hữu quan trở lên.","ĐIỀU 4. Các chức năng của Toà trọng tài Một toà trọng tài được thành lập theo Điều 3 của Phụ lục này thi hành các chức năng của mình theo đúng Phụ lục này và quy định khác của Công ước.","ĐIỀU 5. Thủ tục Trừ khi các bên có thoả thuận khác, Toà trọng tài tự quy định thủ tục của mình bằng cách cho mỗi bên có khả năng bảo vệ các quyền của mình và trình bày căn cứ của mình.","ĐIỀU 6. Những nghĩa vụ của các bên Các bên tham gia tranh chấp tạo điều kiện dễ dàng cho Toà trọng tài thực hiện nhiệm vụ của mình và, đặc biệt là, theo đúng pháp luật của mình và bằng tất cả các phương tiện thuộc quyền sử dụng của mình, cần phải:","a) Cung cấp cho Toà mọi tài liệu, các điều kiện dễ dàng và các thông tin thích hợp; và b) Cho Toà, khi điều đó là cần thiết, có khả năng dẫn ra và nghe người làm chứng hoặc các chuyên gia và đến tại chỗ.","ĐIỀU 7. Lệ phí Trừ khi Toà trọng tài có quyết định khác vì có những hoàn cảnh đặc biệt của vụ việc, lệ phí của Toà, kể ca thù lao cho các thành viên của Toà, phải do các bên trong vụ tranh chấp chịu ngang nhau.","ĐIỀU 8. Đa số cần thiết phải thông qua các bản án Các quyết định của Toà trọng tài được thông qua theo đa số các thành viên của Toà. Sự vắng mặt hoặc bỏ phiếu trắng của dưới một nửa số thành viên không cản trở Toà ra quyết định. Trong trường hợp số phiếu ngang nhau, lá phiếu của Chánh toà là lá phiếu quyết định.","ĐIỀU 9. Vắng mặt Khi một trong số các bên trong vụ tranh chấp không ra Toà hoặc không trình bày các lý lẽ của mình, thì bên kia có thể yêu cầu Toà tiếp tục trình tự tố tụng và phán quyết. Việc một bên vắng mặt hay việc một bên không trình bày các lý lẽ của mình không cản trở cho trình tự tố tụng. Trước khi ra phán quyết, Toà trọng tài cần phải biết chắc chắn rằng không những Toà có thẩm quyền xét xử vụ tranh chấp mà còn chắc chắn rằng đơn kiện có cơ sở về mặt thực tế pháp lý.","ĐIỀU 10. Bản án Bản án của Toà trọng tài được giới hạn ở nội dung của vụ tranh chấp và phải nêu căn cứ. Bản án nêu tên của các thành viên của Toà trọng tài đã tham gia xét xử và thời gian ra bản án. Bất kỳ thành viên nào của Toà cũng có thể đính thêm vào bản án trình bày ý kiến riêng hoặc bất đồng của mình.","ĐIỀU 11. Tính chất tối hậu của bản án Bản án có tính chất tối hậu và không được kháng cáo, trừ khi các bên trong vụ tranh chấp phải tuân theo bản án này.","ĐIỀU 12. Giải thích hoặc thi hành bản án 1. Bất kỳ tranh cãi nào có thể xảy ra giữa các bên trong vụ tranh chấp liên quan đến việc giải thích hay cách thi hành bản án, đều có thể được bên này hoặc bên kia đưa ra để Toà trọng tài đã tuyên án quyết định. Vì mục đích ấy, các ghế bị trống đều được cử người thay theo phương pháp được trù định cho việc bổ nhiệm ban đầu các thành viên của Toà.","2. Nếu tất cả các bên trong vụ tranh chấp thoả thuận, thì bất kỳ tranh cãi nào thuộc loại này đều có thể được đệ trình lên một Toà khác theo đúng Điều 287.","ĐIỀU 13. Áp dụng đối với các thực thể không phải là các quốc gia thành viên Phụ lục này được áp dụng mutatis mutandis (với những thay đổi cần thiết về chi tiết) cho mọi vụ tranh chấp nào liên quan đến các thực thể không phải là quốc gia thành viên.\" 3. Phán quyết của Tòa đề cập tới nội dung gì? Chiều ngày 12/7/2016 (theo Thông cáo báo chí của Tòa Trọng tài), Phán quyết của Hội đồng Trọng tài đã chính thức được công bố. Nội dung của Phán quyết đã đề cập đầy đủ 7 nội dung mà Tòa Trọng tài đã lựa chọn thuộc thẩm quyền xét xử của mình trong số 15 điểm của đơn khởi kiện. Nội dung Phán quyết của Tòa chỉ tập trung phán xét về việc giải thích và áp dụng sai các quy định của Công ước LHQ về Luật Biển, không liên quan gì đến tranh chấp chủ quyền lãnh thổ và tranh chấp về việc phân định các vùng chồng lấn; cụ thể là:","a. Bác bỏ “Quyền lịch sử” đối với tài nguyên trong đường 9 đoạn; Toà Trọng tài nhận thấy có thẩm quyền để xem xét tranh chấp giữa các bên liên quan đến quyền lịch sử và nguồn của quyền hưởng các vùng biển tại Biển Đông. Về mặt nội dung thực chất, Toà kết luận rằng Công ước quy định một cách toàn diện về các quyền đối với các vùng biển, và việc bảo vệ các quyền tồn tại trước Công ước liên quan đến tài nguyên đã được xem xét, nhưng chúng không được thông qua và quy định tại Công ước.","Theo đó, Tòa kết luận rằng trong phạm vi quyền lịch sử của Trung Quốc đối với các nguồn tài nguyên trong các vùng biển ở Biển Đông, quyền này bị xóa bỏ do chúng không phù hợp với chế định vùng đặc quyền kinh tế trong Công ước.","Toà cũng nhận thấy dù trong lịch sử, những người đi biển cũng như ngư dân từ Trung Quốc cũng như từ các nước khác đã sử dụng các đảo tại Biển Đông nhưng không có bất kỳ bằng chứng nào cho thấy về mặt lịch sử Trung Quốc đã chỉ một mình thực hiện việc kiểm soát vùng nước này cũng như tài nguyên tại đây.","Vì vậy, Toà kết luận không có cơ sở pháp lý để Trung Quốc yêu sách quyền lịch sử đối với tài nguyên tại các vùng biển phía bên trong đường 9 đoạn.","b. Khẳng định các cấu trúc (thực thể địa lý) thuộc Trường Sa không có hiệu lực để có vùng đặc quyền kinh tế 200 hải lý;","Tiếp theo, Toà Trọng tài xem xét đến quyền hưởng các vùng biển và quy chế của các cấu trúc. Trước tiên, Toà tiến hành đánh giá liệu một số bãi do Trung Quốc yêu sách có nổi khi thuỷ triều lên đỉnh hay không.","Các cấu trúc nổi khi thủy triều lên cao sẽ tạo ra quyền ít nhất đối với lãnh hải 12 hải lý trong khi các cấu trúc chìm khi thuỷ triều lên cao sẽ không tạo ra quyền như vậy.","Toà nhận thấy rằng các bãi này đã bị làm biến đổi mạnh mẽ do việc bồi đắp, xây dựng và Toà cũng nhắc lại rằng Công ước phân loại các cấu trúc dựa trên điều kiện tự nhiên của chúng và dựa vào các tài liệu lịch sử để đánh giá các cấu trúc.","Sau đó, Toà tiến hành đánh giá liệu các có cấu trúc nào trong số các cấu trúc do Trung Quốc yêu sách có thể tạo ra vùng biển ngoài phạm vi 12 hải lý không.","Theo Công ước, các đảo tạo ra vùng đặc quyền kinh tế 200 hải lý và thềm lục địa nhưng các “đảo đá không thích hợp cho con người đến ở và có đời sống kinh tế riêng không có vùng đặc quyền kinh tế và thềm lục địa”.","Toà kết luận rằng quy định này phụ thuộc vào khả năng khách quan của các cấu trúc khi chúng ở tình trạng tự nhiên để có thể duy trì một cộng đồng dân cư ổn định hoặc các hoạt động kinh tế mà không phụ thuộc vào các nguồn lực từ bên ngoài hoặc hoàn toàn chỉ có tính chất khai thác.","Toà cũng nhận thấy rằng sự có mặt của các nhân viên công vụ trên các cấu trúc là phụ thuộc vào sự hỗ trợ từ bên ngoài và không phản ánh khả năng của các cấu trúc.","Toà cũng thấy rằng các bằng chứng lịch sử có ý nghĩa hơn và nhận thấy quần đảo Trường Sa trong lịch sử được sử dụng bởi một số nhóm nhỏ các ngư dân và rằng đã có một vài hoạt động khai thác phân dơi và đánh cá của Nhật Bản.","Toà kết luận rằng việc việc sử dụng ngắn hạn như vậy không phải là sự định cư của một cộng đồng ổn định và rằng các hoạt động kinh tế trong lịch sử chỉ là hoạt động mang tính khai thác.","Theo đó, Toà kết luận rằng không một cấu trúc nào tại Trường Sa có khả năng tạo ra các vùng biển mở rộng.","c. Toà cũng quyết định rằng các đảo Trường Sa không thể cùng nhau tạo ra các vùng biển như một thực thể thống nhất.","Các hoạt động của Trung Quốc ngăn cản Philippines thực hiện các quyền của mình trong vùng đặc quyền kinh tế, kể cả vùng biên xung quanh bãi cạn Scaborough là vi phạm UNCLOS 1982;","d. Các hoạt động khai thác, xây đảo nhân tạo của Trung Quốc đã gây hại cho môi trường biển;","Gây hại cho môi trường biển: Toà xem xét ảnh hưởng với môi trường biển của các hoạt động bồi đắp và xây dựng nhân tạo trên 7 cấu trúc của Quần đảo Trường Sa gần đây của Trung Quốc, và nhận thấy rằng Trung Quốc đã gây hại nghiêm trọng với môi trường của các rặng san hô và vi phạm nghĩa vụ bảo tồn và bảo vệ các hệ sinh thái dễ bị tổn thương và môi trường sống của các loài đang suy yếu, bị đe doạ và bị huỷ diệt.","Toà cũng cho rằng nhà chức trách Trung Quốc đã nhận thức được việc ngư dân Trung Quốc đã đánh bắt các loài rùa biển, san hô và trai khổng lồ quý hiếm trên diện rộng ở Biển Đông (bằng các biện pháp gây ra tổn hại nghiêm trọng với môi trường rặng san hô) và đã không thực hiện các nghĩa vụ của nước này trong việc ngăn chặn và chấm dứt các hoạt động này.","Toà nhận thấy rằng việc bồi đắp và xây dựng đảo nhân tạo trên quy mô lớn của Trung Quốc gần đây là không phù hợp với nghĩa vụ của quốc gia thành viên Công ước trong quá trình giải quyết tranh chấp, trong chừng mực mà Trung Quốc đã gây ra những tác hại không thể sửa chữa được với môi trường biển, xây dựng một đảo nhân tạo lớn trong vùng đặc quyền kinh tế của Phi-líp-pin, và phá huỷ các bằng chứng về điều kiện tự nhiên của các cấu trúc ở Biển Đông mà là một phần của tranh chấp giữa các Bên.","e. Tất cả những hoạt động đó của Trung Quốc đã làm trầm trọng thêm tranh chấp.","Làm trầm trọng thêm tranh chấp: Cuối cùng, Toà xem xét liệu các hoạt động của Trung Quốc kể từ khi Toà bắt đầu xem xét vụ việc có làm trầm trọng thêm tranh chấp giữa các bên hay không.","Toà nhận thấy rằng Toà thiếu thẩm quyền để xem xét tác động của vụ đối đầu giữa tàu hải quân của Phi-líp-pin và tàu hải quân và chấp pháp của Trung Quốc ở Bãi cạn Second Thomas, cho rằng tranh chấp này liên quan đến các hoạt động quân sự và do vậy, nằm ngoài cơ chế giải quyết tranh chấp bắt buộc."],"q":"Bài tập 9. Năm 2016, Tòa trọng tài theo Phụ lục VII của CULB 1982 đã ra phán quyết vụ Philippines kiện Trung Quốc; bằng kiến thức về Luật bi"},{"qs":["Bài tập 10. Tháng 5/2014, TQ hạ đặt giàn khoan Hải Dương 981 cách Đảo Lý Sơn của VN 119 hải lý. Hãy cho biết:","a) Giàn khoan HD981 được hạ đặt ở vùng biển nào theo quy định của UNCLOS 1982 và Luật biển VN 2012?","Vị trí giàn khoan 981 được đặt trái phép ở vị trí nằm cách đảo Lý Sơn của Việt Nam 119 hải lý, cách đảo Tri Tôn mà TQ đang chiếm 18 hải lý, cách ranh giời ngoài Vùng đặc quyền kinh tế 200 hải lý của Việt Nam theo đúng quy định của Công ước Luật Biển năm 1982 là 80 hải lý.Đây là vị trí nằm hoàn toàn trong vùng đặc quyền kinh tế, thềm lục địa của Việt Nam, nhưng cũng phải thấy rằng đây cũng là vị trí khá nhạy cảm mà Trung Quốc đã cố tình lựa chọn để thực hiện chiến thuật “bắn một mũi tên trúng hai đích”: một là tiếp tục khẳng định chủ quyền của họ đối với “Tây Sa”, thực hiện ý đồ cố tình giải thích và áp dung sai Công ước Luật Biển 1982 trong việc mở rộng phạm vi các vùng biển và thềm lục địa dựa vào vị trí của quần đảo này, cũng như các quần đảo khác trong Biển Đông, nhằm hiện thực hóa yêu sách “đường lưỡi bò”phi lý của họ; hai là, cố tình tạo ra vùng chồng lấn, biến vùng không tranh chấp thành vùng tranh chấp để áp đặt chủ trương “gác tranh chấp, cùng khai thác” mà mục tiêu trước mắt là tranh giành việc khai thác nguồn tài nguyên sinh vật và không sinh vật vốn thuộc các vùng biển và thềm lục địa của các quốc gia ở chung quanh Biển Đông theo quy định của Công ước Luật Biển 1982.","b) TQ đã vi phạm nội dung gì theo quy định của UNCLOS 1982?","Việc TQ hạ đặt giàn khoan HD981 trong vùng ĐQKT và thềm lục địa của VN là hành vi vi phạm Hiến chương LHQ, UNCLOS, DOC và Thỏa thuận về nguyên tắc 6 điểm giải quyết tranh chấp trên biển giữa Việt Nam và Trung Quốc năm 2011. Đồng thời, hành vi này đã xâm phạm quyền chủ quyền và quyền tài phán trong vùng đặc quyền kinh tế và thềm lục địa của Việt Nam đã được quy định tại Điều 56, 77 và 81 UNCLOS 1982; ảnh hưởng đến hoạt động hàng hải, hàng không và thương mại quốc tế; đe dọa hòa bình, an ninh của khu vực và thế giới; làm tổn hại đến tình đoàn kết hữu nghị giữa Nhà nước và nhân dân hai nước Việt Nam – Trung Quốc.","c) VN có thể áp dụng cơ chế nào để giải quyết tranh chấp vụ việc này?","VN có thể áp dụng mọi biện pháp phù hợp cần thiết để bảo vệ các quyền và lợi ích chính đáng của mình.","Việt Nam luôn thể hiện thiện chí, kiên trì giải quyết thỏa đáng bất đồng thông qua đàm phán, đối thoại và các biện pháp hòa bình khác theo đúng nhận thức chung của Lãnh đạo cấp cao hai nước, Thỏa thuận về các Nguyên tắc cơ bản chỉ đạo giải quyết vấn đề trên biển, phù hợp với các quy định và thực tiễn Luật pháp quốc tế, nhất là Công ước Liên hợp quốc về Luật biển 1982, không để vấn đề này tổn hại đến sự tin cậy chính trị và hợp tác giữa hai bên.","Việt Nam có thể sử dụng cơ chế giải quyết thỏa đáng các bất đồng thông qua đàm phán, đối thoại và các biện pháp hòa bình khác.","Một trong những biệp pháp hòa bình thông dụng nhất là vai trò của các cơ quan tài phán quốc tế trong việc giải quyết các tranh chấp có liên quan đến việc giải thích và áp dụng Công ước của LHQ về Luật Biển năm 1982. VN có thể kiện Trung Quốc lên Tòa án của LHQ về Luật Biển theo đung thủ tục và cơ chế thích hợp mà Công ước Luật Biển 1982 quy định. Áp dụng thủ tục này là một sinh hoạt bình thường để xử lý các quan hệ trong một xã hội văn minh, hiện đại, quốc nội cũng như quốc tế. Nó chỉ có thể củng cố hơn nữa mối quan hệ hưu nghị giữa các quốc gia láng giềng một các lâu dài , bền vững, dựa trên nền tảng của nhưng quy định, pháp lý quốc tế đã được loài người dày công xây dựng."],"a":[],"q":"Bài tập 10. Tháng 5/2014, TQ hạ đặt giàn khoan Hải Dương 981 cách Đảo Lý Sơn của VN 119 hải lý. Hãy cho biết:"}]}]}];
